using GroupedDgemmBatchFunction = void (*)(
    int,
    const std::int32_t*,
    const std::int32_t*,
    const std::int32_t*,
    const std::int32_t*,
    const std::int32_t*,
    const double*,
    const double**,
    const std::int32_t*,
    const double**,
    const std::int32_t*,
    const double*,
    double**,
    const std::int32_t*,
    std::int32_t,
    const std::int32_t*
);

GroupedDgemmBatchFunction grouped_dgemm_batch_function() noexcept {
#if defined(__APPLE__) || defined(__linux__)
    static const auto function = reinterpret_cast<
        GroupedDgemmBatchFunction
    >(dlsym(RTLD_DEFAULT, "cblas_dgemm_batch"));
    return function;
#else
    return nullptr;
#endif
}

bool grouped_dgemm_batch_is_openblas() noexcept {
#if defined(__APPLE__) || defined(__linux__)
    using OpenBlasConfigFunction = const char* (*)();
    static const auto config = reinterpret_cast<OpenBlasConfigFunction>(
        dlsym(RTLD_DEFAULT, "openblas_get_config")
    );
    return config != nullptr;
#else
    return false;
#endif
}

bool disable_grouped_output_products() noexcept {
    const char* value =
        std::getenv("PYQED_SU2_DISABLE_GROUPED_OUTPUT_PRODUCTS");
    return value != nullptr && value[0] != '\0' && value[0] != '0';
}

bool grouped_output_product_is_safe(std::int64_t work) noexcept {
#ifdef __APPLE__
    // OpenBLAS 0.3.30's VORTEX small-matrix batch kernel crashes for
    // products at or below its 100^3 dispatch threshold.
    if (grouped_dgemm_batch_is_openblas() && work <= 1'000'000) {
        return false;
    }
#else
    static_cast<void>(work);
#endif
    return true;
}

