template<std::size_t N>
inline void combine_fixed_complementary_right_panel(
    const std::vector<ComplementaryLocalTerm>& terms,
    const std::vector<ReducedContextualMatrix>& matrices,
    std::uint32_t term_start,
    double* target,
    std::size_t count
) {
    std::array<const ReducedContextualMatrix*, N> sources{};
    std::array<double, N> scales{};
    for (std::size_t local = 0; local < N; ++local) {
        const ComplementaryLocalTerm& term = terms[term_start + local];
        sources[local] = &matrices[static_cast<std::size_t>(
            term.right_matrix
        )];
        scales[local] = term.scale;
    }
    const std::int64_t rows = sources[0]->rows;
    const std::int64_t cols = sources[0]->cols;
    if (count != static_cast<std::size_t>(rows * cols)) {
        throw std::logic_error(
            "Complementary right panel element count changed."
        );
    }
    for (std::int64_t row = 0; row < rows; ++row) {
        for (std::int64_t col = 0; col < cols; ++col) {
            double value = 0.0;
            for (std::size_t local = 0; local < N; ++local) {
                value += scales[local] * sources[local]->value(row, col);
            }
            target[static_cast<std::size_t>(row * cols + col)] = value;
        }
    }
}

inline void combine_complementary_right_panel(
    const std::vector<ComplementaryLocalTerm>& terms,
    const std::vector<ReducedContextualMatrix>& matrices,
    std::uint32_t term_start,
    std::uint32_t term_stop,
    double* target,
    std::size_t count,
    std::vector<double>& scratch
) {
    const std::size_t nterms = term_stop - term_start;
    const ComplementaryLocalTerm& first = terms[term_start];
    const ReducedContextualMatrix& first_matrix =
        matrices[static_cast<std::size_t>(first.right_matrix)];
    bool common_storage = count >= 32;
    for (
        std::size_t term_index = term_start;
        common_storage && term_index < term_stop;
        ++term_index
    ) {
        const ReducedContextualMatrix& matrix = matrices[
            static_cast<std::size_t>(terms[term_index].right_matrix)
        ];
        common_storage =
            matrix.rows == first_matrix.rows &&
            matrix.cols == first_matrix.cols &&
            matrix.size() == count &&
            matrix.transposed() == first_matrix.transposed();
    }
    if (common_storage) {
        double* combined = target;
        if (first_matrix.transposed()) {
            scratch.resize(count);
            combined = scratch.data();
        }
#ifdef __APPLE__
        cblas_dcopy(
            static_cast<int>(count),
            first_matrix.data(),
            1,
            combined,
            1
        );
        cblas_dscal(
            static_cast<int>(count),
            first.scale,
            combined,
            1
        );
        for (
            std::size_t term_index = term_start + 1;
            term_index < term_stop;
            ++term_index
        ) {
            const ComplementaryLocalTerm& term = terms[term_index];
            const ReducedContextualMatrix& matrix = matrices[
                static_cast<std::size_t>(term.right_matrix)
            ];
            cblas_daxpy(
                static_cast<int>(count),
                term.scale,
                matrix.data(),
                1,
                combined,
                1
            );
        }
#else
        for (std::size_t index = 0; index < count; ++index) {
            combined[index] = first.scale * first_matrix.data()[index];
        }
        for (
            std::size_t term_index = term_start + 1;
            term_index < term_stop;
            ++term_index
        ) {
            const ComplementaryLocalTerm& term = terms[term_index];
            const ReducedContextualMatrix& matrix = matrices[
                static_cast<std::size_t>(term.right_matrix)
            ];
            for (std::size_t index = 0; index < count; ++index) {
                combined[index] += term.scale * matrix.data()[index];
            }
        }
#endif
        if (first_matrix.transposed()) {
            constexpr std::int64_t block = 32;
            for (
                std::int64_t column_start = 0;
                column_start < first_matrix.cols;
                column_start += block
            ) {
                const std::int64_t column_stop = std::min(
                    first_matrix.cols,
                    column_start + block
                );
                for (
                    std::int64_t row_start = 0;
                    row_start < first_matrix.rows;
                    row_start += block
                ) {
                    const std::int64_t row_stop = std::min(
                        first_matrix.rows,
                        row_start + block
                    );
                    for (
                        std::int64_t column = column_start;
                        column < column_stop;
                        ++column
                    ) {
                        const double* source = combined
                            + column * first_matrix.rows + row_start;
                        for (
                            std::int64_t row = row_start;
                            row < row_stop;
                            ++row
                        ) {
                            target[
                                static_cast<std::size_t>(
                                    row * first_matrix.cols + column
                                )
                            ] = source[row - row_start];
                        }
                    }
                }
            }
        }
        return;
    }
    if (nterms == 1) {
        combine_fixed_complementary_right_panel<1>(
            terms, matrices, term_start, target, count
        );
        return;
    }
    if (nterms == 2) {
        combine_fixed_complementary_right_panel<2>(
            terms, matrices, term_start, target, count
        );
        return;
    }
    if (nterms == 3) {
        combine_fixed_complementary_right_panel<3>(
            terms, matrices, term_start, target, count
        );
        return;
    }
    if (nterms == 4) {
        combine_fixed_complementary_right_panel<4>(
            terms, matrices, term_start, target, count
        );
        return;
    }
    for (std::size_t index = 0; index < count; ++index) {
        target[index] = first.scale * first_matrix.flat_value(index);
    }
    for (
        std::size_t term_index = term_start + 1;
        term_index < term_stop;
        ++term_index
    ) {
        const ComplementaryLocalTerm& term = terms[term_index];
        const ReducedContextualMatrix& matrix =
            matrices[static_cast<std::size_t>(term.right_matrix)];
        for (std::size_t index = 0; index < count; ++index) {
            target[index] += term.scale * matrix.flat_value(index);
        }
    }
}

std::atomic<std::uint64_t> split_site_owner_clock{0};

std::uint64_t fingerprint_word(
    std::uint64_t seed,
    std::uint64_t value
) noexcept {
    seed ^= value
        + std::uint64_t{0x9e3779b97f4a7c15}
        + (seed << 6)
        + (seed >> 2);
    return seed;
}

std::uint64_t fingerprint_double(
    std::uint64_t seed,
    double value
) noexcept {
    std::uint64_t bits = 0;
    static_assert(sizeof(bits) == sizeof(value));
    std::memcpy(&bits, &value, sizeof(bits));
    return fingerprint_word(seed, bits);
}

std::uint64_t fingerprint_metric_double(
    std::uint64_t seed,
    double value
) noexcept {
    if (!std::isfinite(value)) {
        return fingerprint_double(seed, value);
    }
    if (std::abs(value) <= 1.0e-14) {
        return fingerprint_word(seed, 0);
    }
    int exponent = 0;
    const double mantissa = std::frexp(value, &exponent);
    const auto quantized = static_cast<std::int64_t>(
        std::llround(std::ldexp(mantissa, 40))
    );
    seed = fingerprint_word(
        seed,
        static_cast<std::uint64_t>(quantized)
    );
    return fingerprint_word(
        seed,
        static_cast<std::uint64_t>(
            static_cast<std::int64_t>(exponent)
        )
    );
}

std::uint64_t fingerprint_metric_values(
    std::uint64_t seed,
    const double* values,
    std::size_t size
) noexcept {
    seed = fingerprint_word(seed, size);
    for (std::size_t index = 0; index < size; ++index) {
        seed = fingerprint_metric_double(seed, values[index]);
    }
    return seed;
}

template <std::size_t Size>
struct IntegerArrayHash {
    std::size_t operator()(
        const std::array<std::int64_t, Size>& values
    ) const noexcept {
        std::size_t seed = 0;
        for (const std::int64_t value : values) {
            seed ^= std::hash<std::int64_t>{}(value)
                + 0x9e3779b97f4a7c15ULL
                + (seed << 6)
                + (seed >> 2);
        }
        return seed;
    }
};

struct IntegerPairHash {
    std::size_t operator()(
        const std::pair<std::int64_t, std::int64_t>& values
    ) const noexcept {
        std::size_t seed = std::hash<std::int64_t>{}(values.first);
        seed ^= std::hash<std::int64_t>{}(values.second)
            + 0x9e3779b97f4a7c15ULL
            + (seed << 6)
            + (seed >> 2);
        return seed;
    }
};

