std::size_t factorized_output_work_limit() noexcept {
    static const std::size_t limit = []() noexcept {
        const char* value =
            std::getenv("PYQED_SU2_FACTORIZED_OUTPUT_WORK");
        if (value == nullptr || value[0] == '\0') {
            return std::size_t{65'536};
        }
        char* end = nullptr;
        const unsigned long long parsed =
            std::strtoull(value, &end, 10);
        return (
            end != value && end != nullptr && end[0] == '\0'
            ? static_cast<std::size_t>(parsed)
            : std::size_t{65'536}
        );
    }();
    return limit;
}

