System::System(
    const double* h1,
    const double* eri,
    std::size_t n_sites,
    double ecore,
    std::int64_t n_elec,
    std::int64_t two_s,
    const std::int64_t* orb_sym,
    double cutoff,
    bool include_half
) :
    n_sites_(n_sites),
    n_elec_(n_elec),
    two_s_(two_s),
    ecore_(ecore),
    cutoff_(std::max(0.0, cutoff)),
    include_half_(include_half) {
    if (n_sites_ == 0) {
        throw std::invalid_argument("System requires at least one active orbital.");
    }
    if (h1 == nullptr || eri == nullptr || orb_sym == nullptr) {
        throw std::invalid_argument("System received a null input buffer.");
    }
    if (n_elec_ < 0 || n_elec_ > static_cast<std::int64_t>(2 * n_sites_)) {
        throw std::invalid_argument("System received an invalid electron count.");
    }
    if (std::abs(two_s_) > n_elec_ || ((n_elec_ + two_s_) & 1LL) != 0) {
        throw std::invalid_argument("System received an invalid doubled spin.");
    }

    const std::size_t h1_size = n_sites_ * n_sites_;
    const std::size_t eri_size = h1_size * h1_size;
    h1_.assign(h1, h1 + h1_size);
    eri_.assign(eri, eri + eri_size);
    orb_sym_.assign(orb_sym, orb_sym + n_sites_);
    for (double value : h1_) {
        if (!std::isfinite(value)) {
            throw std::invalid_argument("System h1 contains a non-finite value.");
        }
    }
    for (double value : eri_) {
        if (!std::isfinite(value)) {
            throw std::invalid_argument("System ERI contains a non-finite value.");
        }
    }

    std::uint64_t revision = 1469598103934665603ULL;
    revision = mix_revision(revision, static_cast<std::uint64_t>(n_sites_));
    revision = mix_revision(revision, static_cast<std::uint64_t>(n_elec_));
    revision = mix_revision(revision, static_cast<std::uint64_t>(two_s_));
    revision = mix_revision(revision, static_cast<std::uint64_t>(include_half_));
    revision = mix_revision(revision, std::hash<double>{}(ecore_));
    revision = mix_revision(revision, std::hash<double>{}(cutoff_));
    for (std::int64_t symmetry : orb_sym_) {
        revision = mix_revision(
            revision,
            static_cast<std::uint64_t>(symmetry)
        );
    }
    for (double value : h1_) {
        revision = mix_revision(revision, std::hash<double>{}(value));
    }
    for (double value : eri_) {
        revision = mix_revision(revision, std::hash<double>{}(value));
    }
    revision_ = revision == 0 ? 1 : revision;
    build_families();
    build_normal_complementary_plans();
    build_normal_complementary_primitives();
}

void System::build_families() {
    std::map<Index2, double> h_entries;
    std::map<Index2, double> r_entries;
    std::map<Index2, double> a_entries;
    std::map<Index2, double> b_entries;
    std::map<Index3, double> q_entries;
    std::map<Index4, double> p_entries;
    std::set<std::int64_t> active_orbitals;

    for (std::size_t p = 0; p < n_sites_; ++p) {
        for (std::size_t q = 0; q < n_sites_; ++q) {
            const double value = h1_[p * n_sites_ + q];
            if (std::abs(value) > cutoff_) {
                const Index2 key{
                    static_cast<std::int64_t>(p),
                    static_cast<std::int64_t>(q),
                };
                h_entries[key] = value;
                active_orbitals.insert(static_cast<std::int64_t>(p));
                active_orbitals.insert(static_cast<std::int64_t>(q));
            }
        }
    }

    const double scale = include_half_ ? 0.5 : 1.0;
    for (std::size_t p = 0; p < n_sites_; ++p) {
        for (std::size_t q = 0; q < n_sites_; ++q) {
            for (std::size_t r = 0; r < n_sites_; ++r) {
                for (std::size_t s = 0; s < n_sites_; ++s) {
                    const std::size_t index =
                        ((p * n_sites_ + q) * n_sites_ + r) * n_sites_ + s;
                    const double value = scale * eri_[index];
                    if (std::abs(value) <= cutoff_) {
                        continue;
                    }
                    const auto pi = static_cast<std::int64_t>(p);
                    const auto qi = static_cast<std::int64_t>(q);
                    const auto ri = static_cast<std::int64_t>(r);
                    const auto si = static_cast<std::int64_t>(s);
                    p_entries[Index4{pi, qi, ri, si}] = value;
                    a_entries[Index2{pi, qi}] = 1.0;
                    a_entries[Index2{ri, si}] = 1.0;
                    active_orbitals.insert(pi);
                    active_orbitals.insert(qi);
                    active_orbitals.insert(ri);
                    active_orbitals.insert(si);
                    if (q == r) {
                        q_entries[Index3{pi, si, qi}] -= value;
                    }
                }
            }
        }
    }
    erase_small(q_entries, cutoff_);

    r_entries = h_entries;
    for (const auto& [key, value] : q_entries) {
        const auto [p, s, q] = key;
        static_cast<void>(q);
        r_entries[Index2{p, s}] += value;
    }
    erase_small(r_entries, cutoff_);

    for (const auto& [key, value] : h_entries) {
        static_cast<void>(value);
        b_entries[key] = 1.0;
    }
    for (const auto& [key, value] : p_entries) {
        static_cast<void>(value);
        const auto [p, q, r, s] = key;
        b_entries[Index2{p, q}] = 1.0;
        b_entries[Index2{r, s}] = 1.0;
    }
    for (const auto& [key, value] : r_entries) {
        static_cast<void>(value);
        b_entries[key] = 1.0;
    }
    if (active_orbitals.empty()) {
        for (std::size_t site = 0; site < n_sites_; ++site) {
            active_orbitals.insert(static_cast<std::int64_t>(site));
        }
    }

    FamilyData s_family;
    s_family.rank = 1;
    for (std::int64_t site : active_orbitals) {
        s_family.indices.push_back(site);
        s_family.values.push_back(1.0);
    }
    families_[static_cast<std::int32_t>(Family::S)] = std::move(s_family);

    FamilyData r_family;
    r_family.rank = 2;
    append_family(r_family, r_entries);
    families_[static_cast<std::int32_t>(Family::R)] = std::move(r_family);

    FamilyData a_family;
    a_family.rank = 2;
    append_family(a_family, a_entries);
    families_[static_cast<std::int32_t>(Family::A)] = std::move(a_family);

    FamilyData p_family;
    p_family.rank = 4;
    append_family(p_family, p_entries);
    families_[static_cast<std::int32_t>(Family::P)] = std::move(p_family);

    FamilyData b_family;
    b_family.rank = 2;
    append_family(b_family, b_entries);
    families_[static_cast<std::int32_t>(Family::B)] = std::move(b_family);

    FamilyData q_family;
    q_family.rank = 3;
    append_family(q_family, q_entries);
    families_[static_cast<std::int32_t>(Family::Q)] = std::move(q_family);
}

void System::update_h1(const double* h1, std::size_t n_values) {
    if (h1 == nullptr || n_values != n_sites_ * n_sites_) {
        throw std::invalid_argument("Updated h1 has an invalid shape.");
    }
    for (std::size_t index = 0; index < n_values; ++index) {
        if (!std::isfinite(h1[index])) {
            throw std::invalid_argument("Updated h1 contains a non-finite value.");
        }
    }
    h1_.assign(h1, h1 + n_values);
    revision_ = mix_revision(revision_, revision_ + 1);
    build_families();
    build_normal_complementary_plans();
    build_normal_complementary_primitives();
}

void System::update_integrals(
    const double* h1,
    std::size_t n_h1_values,
    const double* eri,
    std::size_t n_eri_values,
    double ecore
) {
    const std::size_t expected_h1 = n_sites_ * n_sites_;
    const std::size_t expected_eri = expected_h1 * expected_h1;
    if (
        h1 == nullptr || n_h1_values != expected_h1
        || eri == nullptr || n_eri_values != expected_eri
    ) {
        throw std::invalid_argument("Updated SU(2) integrals have invalid shapes.");
    }
    if (!std::isfinite(ecore)) {
        throw std::invalid_argument("Updated SU(2) core energy is non-finite.");
    }
    for (std::size_t index = 0; index < n_h1_values; ++index) {
        if (!std::isfinite(h1[index])) {
            throw std::invalid_argument("Updated h1 contains a non-finite value.");
        }
    }
    for (std::size_t index = 0; index < n_eri_values; ++index) {
        if (!std::isfinite(eri[index])) {
            throw std::invalid_argument("Updated ERI contains a non-finite value.");
        }
    }
    h1_.assign(h1, h1 + n_h1_values);
    eri_.assign(eri, eri + n_eri_values);
    ecore_ = ecore;
    revision_ = mix_revision(revision_, revision_ + 1);
    build_families();
    build_normal_complementary_plans();
    build_normal_complementary_primitives();
}

void System::build_normal_complementary_plans() {
    // This is the SU(2) normal/complementary (NC) layout used by a QC sweep.
    // At cut c the normal left block owns C/D/A/AD/B and the complementary
    // right block owns RD/R.  The numbered channels deliberately match the
    // compact block2 NC layout: 2 + 2*K + 6*c*c.  Unlike the historical
    // S/R/A/P/B/Q metadata, every nontrivial coefficient below is already a
    // screened C++ integral contraction and can feed an environment action
    // without rebuilding a Python MPO term dictionary.
    const auto n = static_cast<std::int64_t>(n_sites_);
    const auto bit = [](Family family) noexcept {
        return std::uint64_t{1}
            << static_cast<std::uint64_t>(family);
    };
    const auto channel_count = [n](std::int64_t cut) noexcept {
        return 2 + 2 * n + 6 * cut * cut;
    };
    const auto c_channel = [](std::int64_t index) noexcept {
        return 2 + index;
    };
    const auto d_or_rd_channel = [](std::int64_t cut, std::int64_t index) noexcept {
        return 2 + cut + index;
    };
    const auto r_channel = [n](std::int64_t index) noexcept {
        return 2 + n + index;
    };
    const auto pair_channel = [n](
        std::int64_t cut,
        std::int64_t component,
        std::int64_t first,
        std::int64_t second
    ) noexcept {
        return 2 + 2 * n + component * cut * cut + first * cut + second;
    };
    const auto channel_quantum_numbers = [
        this,
        n,
        channel_count,
        c_channel,
        d_or_rd_channel,
        r_channel,
        pair_channel
    ](std::int64_t cut) {
        std::vector<NormalComplementaryChannel> channels(
            static_cast<std::size_t>(channel_count(cut))
        );
        const auto set = [&channels](
            std::int64_t channel,
            std::int64_t charge,
            std::int32_t two_j,
            std::int64_t point_group
        ) {
            channels[static_cast<std::size_t>(channel)] = {
                charge,
                two_j,
                point_group,
            };
        };
        set(0, 0, 0, 0);
        set(1, 0, 0, 0);
        for (std::int64_t i = 0; i < cut; ++i) {
            set(c_channel(i), 1, 1, orb_sym_[static_cast<std::size_t>(i)]);
            set(
                d_or_rd_channel(cut, i),
                -1,
                1,
                orb_sym_[static_cast<std::size_t>(i)]
            );
        }
        for (std::int64_t i = cut; i < n; ++i) {
            set(
                d_or_rd_channel(cut, i),
                1,
                1,
                orb_sym_[static_cast<std::size_t>(i)]
            );
            set(
                r_channel(i),
                -1,
                1,
                orb_sym_[static_cast<std::size_t>(i)]
            );
        }
        for (std::int64_t component = 0; component < 6; ++component) {
            const std::int64_t charge = (
                component < 2 ? 2 : (component < 4 ? -2 : 0)
            );
            const std::int32_t two_j = component & 1 ? 2 : 0;
            for (std::int64_t first = 0; first < cut; ++first) {
                for (std::int64_t second = 0; second < cut; ++second) {
                    set(
                        pair_channel(cut, component, first, second),
                        charge,
                        two_j,
                        orb_sym_[static_cast<std::size_t>(first)] ^
                            orb_sym_[static_cast<std::size_t>(second)]
                    );
                }
            }
        }
        return channels;
    };
    const auto eri = [this, n](
        std::int64_t p,
        std::int64_t q,
        std::int64_t r,
        std::int64_t s
    ) noexcept {
        const auto index = static_cast<std::size_t>(
            ((p * n + q) * n + r) * n + s
        );
        return eri_[index];
    };
    const auto q0 = [&eri](
        std::int64_t i,
        std::int64_t j,
        std::int64_t m
    ) noexcept {
        return 2.0 * eri(i, j, m, m) - eri(i, m, m, j);
    };
    const auto q1 = [&eri](
        std::int64_t i,
        std::int64_t j,
        std::int64_t m
    ) noexcept {
        return eri(i, m, m, j);
    };
    const double sqrt3 = std::sqrt(3.0);

    normal_complementary_plans_.clear();
    normal_complementary_plans_.resize(static_cast<std::size_t>(n));
    for (std::int64_t m = 0; m < n; ++m) {
        NormalComplementaryPlan& plan =
            normal_complementary_plans_[static_cast<std::size_t>(m)];
        plan.site = m;
        plan.left_channels = channel_count(m);
        plan.right_channels = channel_count(m + 1);
        plan.left_channel_quantum_numbers = channel_quantum_numbers(m);
        plan.right_channel_quantum_numbers = channel_quantum_numbers(m + 1);
        const auto component_offsets = [](
            const std::vector<NormalComplementaryChannel>& channels
        ) {
            std::vector<std::int64_t> offsets;
            offsets.reserve(channels.size() + 1);
            offsets.push_back(0);
            for (const NormalComplementaryChannel& channel : channels) {
                offsets.push_back(
                    offsets.back() +
                    static_cast<std::int64_t>(channel.two_j) + 1
                );
            }
            return offsets;
        };
        plan.left_component_offsets = component_offsets(
            plan.left_channel_quantum_numbers
        );
        plan.right_component_offsets = component_offsets(
            plan.right_channel_quantum_numbers
        );
        plan.transitions.clear();
        plan.component_actions.clear();
        plan.component_action_offsets.clear();
        plan.family_transition_counts.fill(0);

        const auto emit = [&plan, this](
            std::int64_t source,
            std::int64_t target,
            NCOperator local_operator,
            double coefficient,
            std::uint64_t family_mask = 0,
            std::int64_t first_index = -1,
            std::int64_t second_index = -1,
            bool retain_zero = false
        ) {
            if (!retain_zero && std::abs(coefficient) <= cutoff_) {
                return;
            }
            plan.transitions.push_back(
                NormalComplementaryTransition{
                    static_cast<std::int32_t>(source),
                    static_cast<std::int32_t>(target),
                    local_operator,
                    first_index,
                    second_index,
                    coefficient,
                    family_mask,
                }
            );
            for (std::int32_t family = 0; family < 6; ++family) {
                if (family_mask & (std::uint64_t{1} << family)) {
                    ++plan.family_transition_counts[
                        static_cast<std::size_t>(family)
                    ];
                }
            }
        };

        // H/I spine.
        emit(0, 0, NCOperator::Identity, 1.0);
        emit(1, 0, NCOperator::Hamiltonian, 1.0);
        emit(1, 1, NCOperator::Identity, 1.0);

        // Normal single operators grow recursively on the left.
        for (std::int64_t i = 0; i < m; ++i) {
            emit(c_channel(i), c_channel(i), NCOperator::Identity, 1.0);
            emit(
                d_or_rd_channel(m, i),
                d_or_rd_channel(m + 1, i),
                NCOperator::Identity,
                1.0
            );
        }
        emit(1, c_channel(m), NCOperator::Create, 1.0, bit(Family::S));
        emit(
            1,
            d_or_rd_channel(m + 1, m),
            NCOperator::Destroy,
            1.0,
            bit(Family::S)
        );

        // Close the left normal operators and the current complementary
        // operators into H.  The R/RD normalization follows block2's
        // tr_op = 2 convention, matching the routes used below to grow the
        // future complementary channels.
        for (std::int64_t i = 0; i < m; ++i) {
            emit(
                c_channel(i),
                0,
                NCOperator::Destroy,
                h1_[static_cast<std::size_t>(i * n + m)] *
                    (1.0 / std::sqrt(2.0)),
                bit(Family::R),
                i,
                -1,
                true
            );
            emit(
                c_channel(i),
                0,
                NCOperator::ReducedDestroy,
                2.0 * eri(i, m, m, m),
                bit(Family::R),
                i
            );
            emit(
                d_or_rd_channel(m, i),
                0,
                NCOperator::Create,
                h1_[static_cast<std::size_t>(m * n + i)] *
                    (1.0 / std::sqrt(2.0)),
                bit(Family::R),
                i,
                -1,
                true
            );
            emit(
                d_or_rd_channel(m, i),
                0,
                NCOperator::ReducedCreate,
                2.0 * eri(m, i, m, m),
                bit(Family::R),
                i
            );
        }
        emit(
            d_or_rd_channel(m, m),
            0,
            NCOperator::Destroy,
            1.0,
            bit(Family::R),
            m
        );
        emit(
            r_channel(m),
            0,
            NCOperator::Create,
            1.0,
            bit(Family::R),
            m
        );

        // Close the accumulated normal pair and particle-hole families with
        // their local complementary P/PD/Q operators.
        for (std::int64_t i = 0; i < m; ++i) {
            for (std::int64_t j = 0; j < m; ++j) {
                const double p = eri(i, m, j, m);
                const double pd = eri(m, i, m, j);
                emit(
                    pair_channel(m, 0, i, j),
                    0,
                    NCOperator::ComplementPairDestroy0,
                    -0.5 * p,
                    bit(Family::P),
                    i,
                    j
                );
                emit(
                    pair_channel(m, 1, i, j),
                    0,
                    NCOperator::ComplementPairDestroy1,
                    -0.5 * sqrt3 * p,
                    bit(Family::P),
                    i,
                    j
                );
                emit(
                    pair_channel(m, 2, i, j),
                    0,
                    NCOperator::ComplementPairCreate0,
                    -0.5 * pd,
                    bit(Family::P),
                    i,
                    j
                );
                emit(
                    pair_channel(m, 3, i, j),
                    0,
                    NCOperator::ComplementPairCreate1,
                    -0.5 * sqrt3 * pd,
                    bit(Family::P),
                    i,
                    j
                );
                emit(
                    pair_channel(m, 4, i, j),
                    0,
                    NCOperator::ComplementHole0,
                    q0(i, j, m),
                    bit(Family::Q),
                    i,
                    j
                );
                emit(
                    pair_channel(m, 5, i, j),
                    0,
                    NCOperator::ComplementHole1,
                    (i == j ? 1.0 : -1.0) * sqrt3 * q1(i, j, m),
                    bit(Family::Q),
                    i,
                    j
                );
            }
        }

        // Complementary R/RD routes.  Split the one-electron C/D part from
        // the fixed local three-operator RD/R primitive here, so every local
        // operator ID has site-independent reduced matrix elements.  This is
        // block2's tr_op = 2 convention applied directly to the coefficients.
        for (std::int64_t i = m + 1; i < n; ++i) {
            const std::int64_t source_rd = d_or_rd_channel(m, i);
            const std::int64_t target_rd = d_or_rd_channel(m + 1, i);
            const std::int64_t source_r = r_channel(i);
            const std::int64_t target_r = r_channel(i);
            emit(source_rd, target_rd, NCOperator::Identity, 1.0);
            emit(
                1,
                target_rd,
                NCOperator::Create,
                h1_[static_cast<std::size_t>(m * n + i)] *
                    (1.0 / std::sqrt(2.0)),
                bit(Family::R),
                i,
                -1,
                true
            );
            emit(
                1,
                target_rd,
                NCOperator::ReducedCreate,
                2.0 * eri(m, i, m, m),
                bit(Family::R),
                i
            );
            emit(source_r, target_r, NCOperator::Identity, 1.0);
            emit(
                1,
                target_r,
                NCOperator::Destroy,
                h1_[static_cast<std::size_t>(i * n + m)] *
                    (1.0 / std::sqrt(2.0)),
                bit(Family::R),
                i,
                -1,
                true
            );
            emit(
                1,
                target_r,
                NCOperator::ReducedDestroy,
                2.0 * eri(i, m, m, m),
                bit(Family::R),
                i
            );

            for (std::int64_t k = 0; k < m; ++k) {
                const double pd = eri(m, k, m, i);
                const double p = eri(k, m, i, m);
                emit(
                    d_or_rd_channel(m, k),
                    target_rd,
                    NCOperator::PairCreate0,
                    -pd,
                    bit(Family::P),
                    k,
                    i
                );
                emit(
                    d_or_rd_channel(m, k),
                    target_rd,
                    NCOperator::PairCreate1,
                    sqrt3 * pd,
                    bit(Family::P),
                    k,
                    i
                );
                emit(
                    c_channel(k),
                    target_rd,
                    NCOperator::Hole0,
                    q0(k, i, m),
                    bit(Family::Q),
                    k,
                    i
                );
                emit(
                    c_channel(k),
                    target_rd,
                    NCOperator::Hole1,
                    sqrt3 * q1(k, i, m),
                    bit(Family::Q),
                    k,
                    i
                );

                emit(
                    c_channel(k),
                    target_r,
                    NCOperator::PairDestroy0,
                    p,
                    bit(Family::P),
                    k,
                    i
                );
                emit(
                    c_channel(k),
                    target_r,
                    NCOperator::PairDestroy1,
                    -sqrt3 * p,
                    bit(Family::P),
                    k,
                    i
                );
                emit(
                    d_or_rd_channel(m, k),
                    target_r,
                    NCOperator::Hole0,
                    -q0(i, k, m),
                    bit(Family::Q),
                    i,
                    k
                );
                emit(
                    d_or_rd_channel(m, k),
                    target_r,
                    NCOperator::Hole1,
                    -3.0 * sqrt3 * q1(i, k, m),
                    bit(Family::Q),
                    i,
                    k
                );
            }

            for (std::int64_t j = 0; j < m; ++j) {
                for (std::int64_t l = 0; l < m; ++l) {
                    const double rd0 = -0.5 * (
                        eri(j, i, l, m) + eri(l, i, j, m)
                    );
                    const double rd1 = 1.5 * sqrt3 * (
                        eri(j, i, l, m) - eri(l, i, j, m)
                    );
                    emit(
                        pair_channel(m, 0, j, l),
                        target_rd,
                        NCOperator::Destroy,
                        rd0,
                        bit(Family::A)
                    );
                    emit(
                        pair_channel(m, 1, j, l),
                        target_rd,
                        NCOperator::Destroy,
                        rd1,
                        bit(Family::A)
                    );

                    const double r0 = -0.5 * (
                        eri(i, j, m, l) + eri(i, l, m, j)
                    );
                    const double r1 = -1.5 * sqrt3 * (
                        eri(i, j, m, l) - eri(i, l, m, j)
                    );
                    emit(
                        pair_channel(m, 2, j, l),
                        target_r,
                        NCOperator::Create,
                        r0,
                        bit(Family::A)
                    );
                    emit(
                        pair_channel(m, 3, j, l),
                        target_r,
                        NCOperator::Create,
                        r1,
                        bit(Family::A)
                    );
                }
            }
            for (std::int64_t k = 0; k < m; ++k) {
                for (std::int64_t l = 0; l < m; ++l) {
                    emit(
                        pair_channel(m, 4, l, k),
                        target_rd,
                        NCOperator::Create,
                        2.0 * eri(m, i, l, k) - eri(l, i, m, k),
                        bit(Family::B)
                    );
                    emit(
                        pair_channel(m, 4, k, l),
                        target_r,
                        NCOperator::Destroy,
                        2.0 * eri(i, m, k, l) - eri(i, l, k, m),
                        bit(Family::B)
                    );
                }
            }
            for (std::int64_t j = 0; j < m; ++j) {
                for (std::int64_t k = 0; k < m; ++k) {
                    const double b1_phase = j == k ? 1.0 : -1.0;
                    emit(
                        pair_channel(m, 5, j, k),
                        target_rd,
                        NCOperator::Create,
                        b1_phase * 3.0 * sqrt3 * eri(j, i, m, k),
                        bit(Family::B)
                    );
                    emit(
                        pair_channel(m, 5, k, j),
                        target_r,
                        NCOperator::Destroy,
                        -b1_phase * 3.0 * sqrt3 * eri(i, j, k, m),
                        bit(Family::B)
                    );
                }
            }
        }

        // Pair and particle-hole normal operators.  Their six rank channels
        // are propagated and enlarged entirely in the C++ route arena.
        for (std::int64_t component = 0; component < 6; ++component) {
            for (std::int64_t i = 0; i < m; ++i) {
                for (std::int64_t j = 0; j < m; ++j) {
                    emit(
                        pair_channel(m, component, i, j),
                        pair_channel(m + 1, component, i, j),
                        NCOperator::Identity,
                        1.0
                    );
                }
            }
        }
        for (std::int64_t component = 0; component < 2; ++component) {
            const bool rank_one = component == 1;
            for (std::int64_t i = 0; i < m; ++i) {
                emit(
                    c_channel(i),
                    pair_channel(m + 1, component, i, m),
                    NCOperator::Create,
                    1.0,
                    bit(Family::A)
                );
                emit(
                    c_channel(i),
                    pair_channel(m + 1, component, m, i),
                    rank_one ? NCOperator::CreateNegative : NCOperator::Create,
                    1.0,
                    bit(Family::A)
                );
            }
            emit(
                1,
                pair_channel(m + 1, component, m, m),
                rank_one ? NCOperator::PairCreate1 : NCOperator::PairCreate0,
                1.0,
                bit(Family::A)
            );
        }
        for (std::int64_t component = 0; component < 2; ++component) {
            const bool rank_one = component == 1;
            const std::int64_t target_component = 2 + component;
            for (std::int64_t i = 0; i < m; ++i) {
                emit(
                    d_or_rd_channel(m, i),
                    pair_channel(m + 1, target_component, i, m),
                    rank_one ? NCOperator::DestroyNegative : NCOperator::Destroy,
                    1.0,
                    bit(Family::A)
                );
                emit(
                    d_or_rd_channel(m, i),
                    pair_channel(m + 1, target_component, m, i),
                    NCOperator::Destroy,
                    1.0,
                    bit(Family::A)
                );
            }
            emit(
                1,
                pair_channel(m + 1, target_component, m, m),
                rank_one ? NCOperator::PairDestroy1 : NCOperator::PairDestroy0,
                1.0,
                bit(Family::A)
            );
        }
        for (std::int64_t component = 0; component < 2; ++component) {
            const bool rank_one = component == 1;
            const std::int64_t target_component = 4 + component;
            for (std::int64_t i = 0; i < m; ++i) {
                emit(
                    c_channel(i),
                    pair_channel(m + 1, target_component, i, m),
                    NCOperator::Destroy,
                    1.0,
                    bit(Family::B)
                );
                emit(
                    d_or_rd_channel(m, i),
                    pair_channel(m + 1, target_component, m, i),
                    rank_one ? NCOperator::CreateNegative : NCOperator::Create,
                    1.0,
                    bit(Family::B)
                );
            }
            emit(
                1,
                pair_channel(m + 1, target_component, m, m),
                rank_one ? NCOperator::Hole1 : NCOperator::Hole0,
                1.0,
                bit(Family::B)
            );
        }

        // Expand only the tiny virtual SU(2) component factor here.  The
        // physical reduced primitive remains identified by local_operator;
        // the boundary executor can therefore multiply a fixed primitive
        // block by these C++-owned actions without constructing a generic
        // RankCoupledMPO or recomputing Clebsch-Gordan coefficients.
        plan.component_action_offsets.reserve(plan.transitions.size() + 1);
        plan.component_action_offsets.push_back(0);
        for (
            std::size_t transition_index = 0;
            transition_index < plan.transitions.size();
            ++transition_index
        ) {
            const NormalComplementaryTransition& transition =
                plan.transitions[transition_index];
            const NormalComplementaryChannel& source =
                plan.left_channel_quantum_numbers[
                    static_cast<std::size_t>(transition.source)
                ];
            const NormalComplementaryChannel& target =
                plan.right_channel_quantum_numbers[
                    static_cast<std::size_t>(transition.target)
                ];
            const std::int32_t local_two_j =
                local_operator_two_j(transition.local_operator);
            const std::int64_t operator_charge =
                local_operator_charge(transition.local_operator);
            if (
                target.charge != source.charge +
                    operator_charge ||
                target.two_j < std::abs(source.two_j - local_two_j) ||
                target.two_j > source.two_j + local_two_j ||
                ((source.two_j + local_two_j - target.two_j) & 1) != 0
            ) {
                throw std::logic_error(
                    "Invalid SU(2) normal/complementary transition."
                );
            }
            for (
                std::int32_t source_component = 0;
                source_component <= source.two_j;
                ++source_component
            ) {
                const std::int32_t source_two_m =
                    source.two_j - 2 * source_component;
                for (
                    std::int32_t target_component = 0;
                    target_component <= target.two_j;
                    ++target_component
                ) {
                    const std::int32_t target_two_m =
                        target.two_j - 2 * target_component;
                    const auto orientation = [operator_charge](
                        const NormalComplementaryChannel& source_channel,
                        const NormalComplementaryChannel& target_channel,
                        bool left
                    ) noexcept {
                        if (
                            source_channel.two_j == 1 &&
                            target_channel.two_j == 2 &&
                            std::abs(target_channel.charge) == 2 &&
                            operator_charge != 0
                        ) {
                            return operator_charge > 0 ? -1 : 1;
                        }
                        if (
                            !left &&
                            source_channel.two_j == 0 &&
                            target_channel.two_j != 0 &&
                            operator_charge != 0
                        ) {
                            return operator_charge > 0 ? 1 : -1;
                        }
                        if (
                            left &&
                            target_channel.two_j == 0 &&
                            source_channel.two_j != 0 &&
                            operator_charge != 0
                        ) {
                            return operator_charge > 0 ? -1 : 1;
                        }
                        const std::int64_t charge = (
                            left
                            ? source_channel.charge
                            : target_channel.charge
                        );
                        return charge < 0 ? -1 : 1;
                    };
                    const std::int32_t left_orientation =
                        orientation(source, target, true);
                    const std::int32_t right_orientation =
                        orientation(source, target, false);
                    const bool orient_virtual_coupling =
                        source.charge * target.charge < 0;
                    const bool same_charge_dual = (
                        (
                            (
                                transition.local_operator ==
                                    NCOperator::Identity &&
                                std::abs(source.charge) != 2
                            ) ||
                            transition.local_operator == NCOperator::Hole0 ||
                            transition.local_operator ==
                                NCOperator::Hole1 ||
                            transition.local_operator ==
                                NCOperator::ComplementHole0 ||
                            transition.local_operator ==
                                NCOperator::ComplementHole1
                        ) &&
                        source.charge != 0 &&
                        source.charge == target.charge
                    );
                    const bool charged_pair_dual = (
                        source.two_j == 2 &&
                        target.two_j == 1 &&
                        std::abs(source.charge) == 2
                    );
                    const bool dual_right_coupling =
                        same_charge_dual || charged_pair_dual;
                    const bool phase_from_charged_scalar_source = (
                        std::abs(source.charge) == 2 &&
                        source.two_j == 0 &&
                        target.two_j != 0 &&
                        local_two_j != 0
                    );
                    const bool phase_to_charged_pair_target = (
                        std::abs(target.charge) == 2 &&
                        source.two_j != 0 &&
                        local_two_j != 0
                    );
                    std::int32_t local_two_m =
                        right_orientation * target_two_m -
                        left_orientation * source_two_m;
                    std::int32_t coupling_left = source_two_m;
                    std::int32_t coupling_right = target_two_m;
                    std::int32_t coupling_component =
                        target_two_m - source_two_m;
                    if (local_two_j == 0) {
                        local_two_m = 0;
                    }
                    if (dual_right_coupling) {
                        local_two_m = -(
                            source_two_m + target_two_m
                        );
                        if (charged_pair_dual) {
                            local_two_m *= left_orientation;
                        }
                        coupling_component = -(
                            source_two_m + target_two_m
                        );
                        coupling_right = -target_two_m;
                    } else if (orient_virtual_coupling) {
                        coupling_left =
                            left_orientation * source_two_m;
                        coupling_right =
                            right_orientation * target_two_m;
                        coupling_component = local_two_m;
                    }
                    double virtual_cg = clebsch_gordan_doubled(
                        source.two_j,
                        local_two_j,
                        target.two_j,
                        coupling_left,
                        coupling_component,
                        coupling_right
                    );
                    if (dual_right_coupling) {
                        virtual_cg *= phase_from_doubled(
                            target.two_j + target_two_m
                        );
                    }
                    const bool scalar_dual_transport = (
                        local_two_j == 0 &&
                        source.two_j == target.two_j &&
                        source.two_j != 0 &&
                        (
                            transition.local_operator ==
                                NCOperator::Identity ||
                            transition.local_operator ==
                                NCOperator::Hole0 ||
                            transition.local_operator ==
                                NCOperator::ComplementHole0
                        )
                    );
                    if (scalar_dual_transport) {
                        virtual_cg = (
                            target_two_m == -source_two_m
                            ? phase_from_doubled(
                                source.two_j + source_two_m
                            )
                            : 0.0
                        );
                        if (
                            transition.local_operator ==
                                NCOperator::Identity &&
                            std::abs(source.charge) != 2
                        ) {
                            virtual_cg *= left_orientation;
                        }
                    }
                    if (phase_from_charged_scalar_source) {
                        virtual_cg *= -target_two_m;
                    }
                    if (phase_to_charged_pair_target) {
                        virtual_cg *= -source_two_m;
                    }
                    if (
                        std::abs(local_two_m) > local_two_j ||
                        ((local_two_j - local_two_m) & 1) != 0
                    ) {
                        continue;
                    }
                    const double coefficient =
                        transition.coefficient * virtual_cg;
                    if (std::abs(coefficient) <= cutoff_) {
                        continue;
                    }
                    plan.component_actions.push_back(
                        NormalComplementaryComponentAction{
                            static_cast<std::int32_t>(transition_index),
                            source_component,
                            target_component,
                            local_two_m,
                            coefficient,
                        }
                    );
                }
            }
            plan.component_action_offsets.push_back(
                static_cast<std::int64_t>(plan.component_actions.size())
            );
        }
    }
}

void System::build_normal_complementary_primitives() {
    normal_complementary_primitives_.assign(
        n_sites_ * nc_primitive_table_size,
        0.0
    );
    const double inv_sqrt2 = 1.0 / std::sqrt(2.0);
    const double sqrt2 = std::sqrt(2.0);
    const auto eri = [this](
        std::int64_t p,
        std::int64_t q,
        std::int64_t r,
        std::int64_t s
    ) noexcept {
        const std::int64_t n = static_cast<std::int64_t>(n_sites_);
        return eri_[static_cast<std::size_t>(
            ((p * n + q) * n + r) * n + s
        )];
    };
    for (
        std::int64_t site = 0;
        site < static_cast<std::int64_t>(n_sites_);
        ++site
    ) {
        double* table = normal_complementary_primitives_.data() +
            static_cast<std::size_t>(site) * nc_primitive_table_size;
        const auto set = [table](
            std::int64_t output_charge,
            std::int64_t input_charge,
            NCOperator op,
            std::int32_t two_m,
            double value
        ) {
            table[nc_primitive_index(
                output_charge,
                input_charge,
                op,
                two_m
            )] = value;
        };
        const auto copy_operator = [table](
            NCOperator target,
            NCOperator source
        ) {
            for (
                std::int64_t output_charge = 0;
                output_charge <
                    static_cast<std::int64_t>(nc_physical_charge_count);
                ++output_charge
            ) {
                for (
                    std::int64_t input_charge = 0;
                    input_charge <
                        static_cast<std::int64_t>(nc_physical_charge_count);
                    ++input_charge
                ) {
                    for (std::int32_t two_m = -2; two_m <= 2; ++two_m) {
                        table[nc_primitive_index(
                            output_charge,
                            input_charge,
                            target,
                            two_m
                        )] = table[nc_primitive_index(
                            output_charge,
                            input_charge,
                            source,
                            two_m
                        )];
                    }
                }
            }
        };

        for (std::int64_t charge = 0; charge < 3; ++charge) {
            set(charge, charge, NCOperator::Identity, 0, 1.0);
        }
        const double h = h1_[
            static_cast<std::size_t>(
                site * static_cast<std::int64_t>(n_sites_) + site
            )
        ];
        const double core = site == 0 ? ecore_ : 0.0;
        set(0, 0, NCOperator::Hamiltonian, 0, core);
        set(1, 1, NCOperator::Hamiltonian, 0, core + h);
        set(
            2,
            2,
            NCOperator::Hamiltonian,
            0,
            core + 2.0 * h + eri(site, site, site, site)
        );

        for (const std::int32_t two_m : {-1, 1}) {
            set(1, 0, NCOperator::Create, two_m, 1.0);
            set(2, 1, NCOperator::Create, two_m, inv_sqrt2);
            set(0, 1, NCOperator::Destroy, two_m, 1.0);
            set(1, 2, NCOperator::Destroy, two_m, inv_sqrt2);
            set(1, 0, NCOperator::CreateNegative, two_m, -1.0);
            set(
                2,
                1,
                NCOperator::CreateNegative,
                two_m,
                -inv_sqrt2
            );
            set(0, 1, NCOperator::DestroyNegative, two_m, -1.0);
            set(
                1,
                2,
                NCOperator::DestroyNegative,
                two_m,
                -inv_sqrt2
            );
            set(2, 1, NCOperator::ReducedCreate, two_m, 0.5);
            set(1, 2, NCOperator::ReducedDestroy, two_m, 0.5);
        }

        set(2, 0, NCOperator::PairCreate0, 0, sqrt2);
        set(0, 2, NCOperator::PairDestroy0, 0, -sqrt2);
        set(1, 1, NCOperator::Hole0, 0, inv_sqrt2);
        set(2, 2, NCOperator::Hole0, 0, sqrt2);
        for (const std::int32_t two_m : {-2, 0, 2}) {
            set(1, 1, NCOperator::Hole1, two_m, inv_sqrt2);
        }
        copy_operator(
            NCOperator::ComplementPairCreate0,
            NCOperator::PairCreate0
        );
        copy_operator(
            NCOperator::ComplementPairCreate1,
            NCOperator::PairCreate1
        );
        copy_operator(
            NCOperator::ComplementPairDestroy0,
            NCOperator::PairDestroy0
        );
        copy_operator(
            NCOperator::ComplementPairDestroy1,
            NCOperator::PairDestroy1
        );
        copy_operator(NCOperator::ComplementHole0, NCOperator::Hole0);
        copy_operator(NCOperator::ComplementHole1, NCOperator::Hole1);

        NormalComplementaryPlan& plan =
            normal_complementary_plans_[static_cast<std::size_t>(site)];
        for (auto& active : plan.active_transitions_by_physical_pair) {
            active.clear();
        }
        for (auto& offsets : plan.active_source_transition_offsets) {
            offsets.clear();
        }
        for (auto& transitions : plan.active_source_transitions) {
            transitions.clear();
        }
        for (auto& offsets : plan.active_target_transition_offsets) {
            offsets.clear();
        }
        for (auto& transitions : plan.active_target_transitions) {
            transitions.clear();
        }
        for (auto& block_ids : plan.active_transition_block_ids) {
            block_ids.clear();
        }
        for (auto& channels : plan.active_block_channels) {
            channels.clear();
        }
        for (
            std::int64_t output_charge = 0;
            output_charge <
                static_cast<std::int64_t>(nc_physical_charge_count);
            ++output_charge
        ) {
            for (
                std::int64_t input_charge = 0;
                input_charge <
                    static_cast<std::int64_t>(nc_physical_charge_count);
                ++input_charge
            ) {
                auto& active =
                    plan.active_transitions_by_physical_pair[
                        static_cast<std::size_t>(
                            output_charge * nc_physical_charge_count
                            + input_charge
                        )
                    ];
                for (
                    std::size_t transition_index = 0;
                    transition_index < plan.transitions.size();
                    ++transition_index
                ) {
                    const NormalComplementaryTransition& transition =
                        plan.transitions[transition_index];
                    const std::size_t action_start =
                        static_cast<std::size_t>(
                            plan.component_action_offsets[transition_index]
                        );
                    const std::size_t action_stop =
                        static_cast<std::size_t>(
                            plan.component_action_offsets[
                                transition_index + 1
                            ]
                        );
                    bool nonzero = false;
                    for (
                        std::size_t action_index = action_start;
                        action_index < action_stop;
                        ++action_index
                    ) {
                        const std::int32_t local_index =
                            plan.component_actions[
                                action_index
                            ].local_two_m + 2;
                        if (
                            local_index >= 0 &&
                            local_index <
                                static_cast<std::int32_t>(
                                    nc_components_per_operator
                                ) &&
                            table[nc_primitive_index(
                                output_charge,
                                input_charge,
                                transition.local_operator,
                                local_index - 2
                            )] != 0.0
                        ) {
                            nonzero = true;
                            break;
                        }
                    }
                    if (nonzero) {
                        active.push_back(
                            static_cast<std::int64_t>(transition_index)
                        );
                    }
                }
                const std::size_t pair_index = static_cast<std::size_t>(
                    output_charge * nc_physical_charge_count + input_charge
                );
                const auto build_channel_index = [
                    &plan,
                    &active
                ](
                    bool source,
                    std::vector<std::int64_t>& offsets,
                    std::vector<std::int64_t>& transitions
                ) {
                    const std::size_t channel_count = static_cast<std::size_t>(
                        source ? plan.left_channels : plan.right_channels
                    );
                    offsets.assign(channel_count + 1, 0);
                    for (const std::int64_t transition_index : active) {
                        const NormalComplementaryTransition& transition =
                            plan.transitions[static_cast<std::size_t>(
                                transition_index
                            )];
                        const std::int32_t channel = source
                            ? transition.source
                            : transition.target;
                        ++offsets[static_cast<std::size_t>(channel) + 1];
                    }
                    for (
                        std::size_t channel = 0;
                        channel < channel_count;
                        ++channel
                    ) {
                        offsets[channel + 1] += offsets[channel];
                    }
                    transitions.resize(active.size());
                    std::vector<std::int64_t> cursor = offsets;
                    for (const std::int64_t transition_index : active) {
                        const NormalComplementaryTransition& transition =
                            plan.transitions[static_cast<std::size_t>(
                                transition_index
                            )];
                        const std::int32_t channel = source
                            ? transition.source
                            : transition.target;
                        transitions[static_cast<std::size_t>(
                            cursor[static_cast<std::size_t>(channel)]++
                        )] = transition_index;
                    }
                };
                build_channel_index(
                    true,
                    plan.active_source_transition_offsets[pair_index],
                    plan.active_source_transitions[pair_index]
                );
                build_channel_index(
                    false,
                    plan.active_target_transition_offsets[pair_index],
                    plan.active_target_transitions[pair_index]
                );
                auto& block_ids =
                    plan.active_transition_block_ids[pair_index];
                auto& block_channels =
                    plan.active_block_channels[pair_index];
                std::map<std::pair<std::int32_t, std::int32_t>, std::int32_t>
                    block_lookup;
                block_ids.reserve(active.size());
                for (const std::int64_t transition_index : active) {
                    const NormalComplementaryTransition& transition =
                        plan.transitions[
                            static_cast<std::size_t>(transition_index)
                        ];
                    const auto channel_pair = std::make_pair(
                        transition.source,
                        transition.target
                    );
                    const auto inserted = block_lookup.emplace(
                        channel_pair,
                        static_cast<std::int32_t>(block_lookup.size())
                    );
                    if (inserted.second) {
                        block_channels.push_back(
                            std::array<std::int32_t, 2>{
                                transition.source,
                                transition.target,
                            }
                        );
                    }
                    block_ids.push_back(inserted.first->second);
                }
            }
        }
    }
}

std::size_t System::n_sites() const noexcept { return n_sites_; }
std::int64_t System::n_elec() const noexcept { return n_elec_; }
std::int64_t System::two_s() const noexcept { return two_s_; }
double System::ecore() const noexcept { return ecore_; }
double System::cutoff() const noexcept { return cutoff_; }
bool System::include_half() const noexcept { return include_half_; }
std::uint64_t System::revision() const noexcept { return revision_; }

std::size_t System::stored_integral_elements() const noexcept {
    return h1_.size() + eri_.size();
}

std::size_t System::stored_family_terms() const noexcept {
    std::size_t total = 0;
    for (const auto& [family_id, family] : families_) {
        static_cast<void>(family_id);
        total += family.values.size();
    }
    return total;
}

const NormalComplementaryPlan& System::normal_complementary_plan(
    std::int64_t site
) const {
    if (site < 0 || site >= static_cast<std::int64_t>(n_sites_)) {
        throw std::out_of_range(
            "Normal/complementary plan site is outside the system."
        );
    }
    return normal_complementary_plans_[static_cast<std::size_t>(site)];
}

std::size_t System::normal_complementary_transition_count() const noexcept {
    std::size_t total = 0;
    for (const NormalComplementaryPlan& plan : normal_complementary_plans_) {
        total += plan.transitions.size();
    }
    return total;
}

std::size_t
System::normal_complementary_component_action_count() const noexcept {
    std::size_t total = 0;
    for (const NormalComplementaryPlan& plan : normal_complementary_plans_) {
        total += plan.component_actions.size();
    }
    return total;
}

std::size_t System::normal_complementary_left_component_count(
    std::int64_t site
) const {
    const NormalComplementaryPlan& plan = normal_complementary_plan(site);
    return static_cast<std::size_t>(plan.left_component_offsets.back());
}

std::size_t System::normal_complementary_right_component_count(
    std::int64_t site
) const {
    const NormalComplementaryPlan& plan = normal_complementary_plan(site);
    return static_cast<std::size_t>(plan.right_component_offsets.back());
}

const double* System::normal_complementary_primitives(
    std::int64_t site
) const {
    if (site < 0 || site >= static_cast<std::int64_t>(n_sites_)) {
        throw std::out_of_range(
            "Normal/complementary primitive site is outside the system."
        );
    }
    return normal_complementary_primitives_.data() +
        static_cast<std::size_t>(site) * nc_primitive_table_size;
}

std::size_t System::normal_complementary_primitive_count() const noexcept {
    return nc_primitive_table_size;
}

std::size_t System::normal_complementary_primitive_bytes() const noexcept {
    return normal_complementary_primitives_.capacity() * sizeof(double);
}

void System::apply_normal_complementary_core(
    std::int64_t site,
    const double* primitive_components,
    std::size_t n_primitive_components,
    const double* input,
    std::size_t n_input,
    std::size_t batch_size,
    double* output,
    std::size_t n_output
) const {
    constexpr std::size_t components_per_operator = 5;
    constexpr std::size_t operator_count =
        static_cast<std::size_t>(NCOperator::ComplementHole1) + 1;
    if (
        primitive_components == nullptr ||
        input == nullptr ||
        output == nullptr ||
        batch_size == 0
    ) {
        throw std::invalid_argument(
            "Normal/complementary core action received an invalid buffer."
        );
    }
    if (n_primitive_components != operator_count * components_per_operator) {
        throw std::invalid_argument(
            "Normal/complementary primitive table must have shape (20, 5)."
        );
    }
    const NormalComplementaryPlan& plan = normal_complementary_plan(site);
    const std::size_t left_components =
        static_cast<std::size_t>(plan.left_component_offsets.back());
    const std::size_t right_components =
        static_cast<std::size_t>(plan.right_component_offsets.back());
    if (
        n_input != left_components * batch_size ||
        n_output != right_components * batch_size
    ) {
        throw std::invalid_argument(
            "Normal/complementary core action dimensions are inconsistent."
        );
    }
    std::fill(output, output + n_output, 0.0);
    for (
        const NormalComplementaryComponentAction& action :
        plan.component_actions
    ) {
        const NormalComplementaryTransition& transition =
            plan.transitions[static_cast<std::size_t>(action.transition)];
        const std::int32_t local_index = action.local_two_m + 2;
        if (local_index < 0 || local_index >= 5) {
            throw std::logic_error(
                "Normal/complementary local component is outside [-2, 2]."
            );
        }
        const std::size_t primitive_index =
            static_cast<std::size_t>(transition.local_operator) *
                components_per_operator +
            static_cast<std::size_t>(local_index);
        const double scale =
            action.coefficient * primitive_components[primitive_index];
        if (scale == 0.0) {
            continue;
        }
        const std::size_t source =
            static_cast<std::size_t>(
                plan.left_component_offsets[
                    static_cast<std::size_t>(transition.source)
                ] +
                action.source_component
            );
        const std::size_t target =
            static_cast<std::size_t>(
                plan.right_component_offsets[
                    static_cast<std::size_t>(transition.target)
                ] +
                action.target_component
            );
        const double* input_row = input + source * batch_size;
        double* output_row = output + target * batch_size;
        for (std::size_t batch = 0; batch < batch_size; ++batch) {
            output_row[batch] += scale * input_row[batch];
        }
    }
}

std::size_t System::normal_complementary_memory_bytes() const noexcept {
    std::size_t total = normal_complementary_plans_.capacity()
        * sizeof(NormalComplementaryPlan);
    for (const NormalComplementaryPlan& plan : normal_complementary_plans_) {
        total += plan.left_channel_quantum_numbers.capacity()
            * sizeof(NormalComplementaryChannel);
        total += plan.right_channel_quantum_numbers.capacity()
            * sizeof(NormalComplementaryChannel);
        total += plan.left_component_offsets.capacity()
            * sizeof(std::int64_t);
        total += plan.right_component_offsets.capacity()
            * sizeof(std::int64_t);
        total += plan.transitions.capacity()
            * sizeof(NormalComplementaryTransition);
        total += plan.component_actions.capacity()
            * sizeof(NormalComplementaryComponentAction);
        total += plan.component_action_offsets.capacity()
            * sizeof(std::int64_t);
        for (
            const auto& active :
            plan.active_transitions_by_physical_pair
        ) {
            total += active.capacity() * sizeof(std::int64_t);
        }
        for (const auto& offsets : plan.active_source_transition_offsets) {
            total += offsets.capacity() * sizeof(std::int64_t);
        }
        for (const auto& transitions : plan.active_source_transitions) {
            total += transitions.capacity() * sizeof(std::int64_t);
        }
        for (const auto& offsets : plan.active_target_transition_offsets) {
            total += offsets.capacity() * sizeof(std::int64_t);
        }
        for (const auto& transitions : plan.active_target_transitions) {
            total += transitions.capacity() * sizeof(std::int64_t);
        }
        for (
            const auto& block_ids :
            plan.active_transition_block_ids
        ) {
            total += block_ids.capacity() * sizeof(std::int32_t);
        }
        for (
            const auto& channels :
            plan.active_block_channels
        ) {
            total += channels.capacity()
                * sizeof(std::array<std::int32_t, 2>);
        }
    }
    total += normal_complementary_primitive_bytes();
    return total;
}

std::size_t System::memory_bytes() const noexcept {
    std::size_t total =
        h1_.capacity() * sizeof(double) +
        eri_.capacity() * sizeof(double) +
        orb_sym_.capacity() * sizeof(std::int64_t);
    for (const auto& [family_id, family] : families_) {
        static_cast<void>(family_id);
        total += family.indices.capacity() * sizeof(std::int64_t);
        total += family.values.capacity() * sizeof(double);
    }
    total += normal_complementary_memory_bytes();
    return total;
}

void System::family_partition_counts(
    std::int32_t family_id,
    bool left,
    std::int64_t bond,
    std::size_t* internal,
    std::size_t* cross,
    std::size_t* external
) const {
    if (internal == nullptr || cross == nullptr || external == nullptr) {
        throw std::invalid_argument("Family partition count output is null.");
    }
    if (bond < 0 || bond >= static_cast<std::int64_t>(n_sites_)) {
        throw std::out_of_range("Family partition bond is outside the system.");
    }
    const FamilyData& data = family(family_id);
    *internal = 0;
    *cross = 0;
    *external = 0;
    for (std::size_t term = 0; term < data.values.size(); ++term) {
        const std::size_t begin = term * static_cast<std::size_t>(data.rank);
        std::int64_t minimum = std::numeric_limits<std::int64_t>::max();
        std::int64_t maximum = std::numeric_limits<std::int64_t>::min();
        for (std::int32_t axis = 0; axis < data.rank; ++axis) {
            const std::int64_t index =
                data.indices[begin + static_cast<std::size_t>(axis)];
            minimum = std::min(minimum, index);
            maximum = std::max(maximum, index);
        }
        const bool is_internal = left ? maximum < bond : minimum > bond;
        const bool is_external = left ? minimum >= bond : maximum <= bond;
        if (is_internal) {
            ++(*internal);
        } else if (is_external) {
            ++(*external);
        } else {
            ++(*cross);
        }
    }
}

const std::vector<double>& System::h1() const noexcept { return h1_; }
const std::vector<double>& System::eri() const noexcept { return eri_; }
const std::vector<std::int64_t>& System::orb_sym() const noexcept {
    return orb_sym_;
}

const FamilyData& System::family(std::int32_t family_id) const {
    const auto it = families_.find(family_id);
    if (it == families_.end()) {
        throw std::out_of_range("Unknown SU(2) complementary family id.");
    }
    return it->second;
}

MovingEnvironment::MovingEnvironment(const System* system) : system_(system) {
    if (system_ == nullptr) {
        throw std::invalid_argument("MovingEnvironment requires a System.");
    }
    split_site_owner_revision_ =
        split_site_owner_clock.fetch_add(1, std::memory_order_relaxed) + 1;
}

std::string MovingEnvironment::boundary_key(
    const std::string& side,
    std::int64_t bond
) {
    if (side != "left" && side != "right") {
        throw std::invalid_argument("Boundary side must be 'left' or 'right'.");
    }
    if (bond < 0) {
        throw std::invalid_argument("Boundary bond must be nonnegative.");
    }
    return side + ":" + std::to_string(bond);
}

bool MovingEnvironment::install_boundary(
    const std::string& side,
    std::int64_t bond,
    const double* values,
    std::size_t n_values,
    const std::int64_t* offsets,
    std::size_t n_offsets,
    const std::int64_t* labels,
    std::size_t n_labels,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision
) {
    if ((n_values != 0 && values == nullptr) ||
        (n_offsets != 0 && offsets == nullptr) ||
        (n_labels != 0 && labels == nullptr)) {
        throw std::invalid_argument("Boundary arena received a null buffer.");
    }
    if (n_offsets == 0 || offsets[0] != 0 ||
        static_cast<std::size_t>(offsets[n_offsets - 1]) != n_values) {
        throw std::invalid_argument(
            "Boundary offsets do not cover the value arena."
        );
    }
    const std::string key = boundary_key(side, bond);
    complex_boundaries_.erase(key);
    PackedArena& arena = boundaries_[key];
    const bool same_topology =
        arena.topology_revision == topology_revision &&
        arena.offsets.size() == n_offsets &&
        arena.labels.size() == n_labels &&
        std::equal(arena.offsets.begin(), arena.offsets.end(), offsets) &&
        std::equal(arena.labels.begin(), arena.labels.end(), labels);
    if (!same_topology) {
        arena.offsets.assign(offsets, offsets + n_offsets);
        arena.labels.assign(labels, labels + n_labels);
        decode_boundary_shapes(arena);
        arena.topology_revision = topology_revision;
        ++boundary_topology_builds_;
    }
    if (arena.n_values < n_values) {
        ++boundary_reallocations_;
    }
    arena.owned_values.reset();
    arena.values = values;
    arena.n_values = n_values;
    arena.numeric_revision = numeric_revision;
    arena.owns_values = false;
    arena.symbolic_identity = false;
    ++boundary_numeric_refreshes_;
    return same_topology;
}

bool MovingEnvironment::install_metric_boundary(
    const std::string& side,
    std::int64_t bond,
    const double* values,
    std::size_t n_values,
    const std::int64_t* offsets,
    std::size_t n_offsets,
    const std::int64_t* labels,
    std::size_t n_labels,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision
) {
    if (
        (n_values != 0 && values == nullptr) ||
        (n_offsets != 0 && offsets == nullptr) ||
        (n_labels != 0 && labels == nullptr)
    ) {
        throw std::invalid_argument(
            "Metric boundary arena received a null buffer."
        );
    }
    if (
        n_offsets == 0 || offsets[0] != 0 ||
        static_cast<std::size_t>(offsets[n_offsets - 1]) != n_values
    ) {
        throw std::invalid_argument(
            "Metric boundary offsets do not cover the value arena."
        );
    }
    const std::string key = boundary_key(side, bond);
    complex_metric_boundaries_.erase(key);
    PackedArena& arena = metric_boundaries_[key];
    const bool same_topology =
        arena.topology_revision == topology_revision &&
        arena.offsets.size() == n_offsets &&
        arena.labels.size() == n_labels &&
        std::equal(arena.offsets.begin(), arena.offsets.end(), offsets) &&
        std::equal(arena.labels.begin(), arena.labels.end(), labels);
    if (!same_topology) {
        arena.offsets.assign(offsets, offsets + n_offsets);
        arena.labels.assign(labels, labels + n_labels);
        decode_boundary_shapes(arena);
        arena.topology_revision = topology_revision;
        ++boundary_topology_builds_;
    }
    if (arena.n_values < n_values) {
        ++boundary_reallocations_;
    }
    arena.owned_values.reset();
    arena.values = values;
    arena.n_values = n_values;
    arena.numeric_revision = numeric_revision;
    arena.owns_values = false;
    arena.symbolic_identity = false;
    ++boundary_numeric_refreshes_;
    return same_topology;
}

bool MovingEnvironment::release_boundary(
    const std::string& side,
    std::int64_t bond
) {
    const std::string key = boundary_key(side, bond);
    const bool released_real = boundaries_.erase(key) != 0;
    const bool released_complex = complex_boundaries_.erase(key) != 0;
    return released_real || released_complex;
}

void MovingEnvironment::clear_boundaries() {
    boundaries_.clear();
    metric_boundaries_.clear();
    complex_boundaries_.clear();
    complex_metric_boundaries_.clear();
}

void MovingEnvironment::decode_boundary_shapes(PackedArena& arena) {
    if (arena.labels.size() < 7) {
        arena.shape_offsets.clear();
        arena.shapes.clear();
        return;
    }
    std::size_t cursor = 7;
    for (std::size_t field = 0; field < 5; ++field) {
        if (arena.labels[field] < 0) {
            arena.shape_offsets.clear();
            arena.shapes.clear();
            return;
        }
        cursor += static_cast<std::size_t>(arena.labels[field]);
    }
    const std::int64_t n_shape_offsets_raw = arena.labels[5];
    const std::int64_t n_shapes_raw = arena.labels[6];
    if (n_shape_offsets_raw < 0 || n_shapes_raw < 0) {
        arena.shape_offsets.clear();
        arena.shapes.clear();
        return;
    }
    const std::size_t n_shape_offsets =
        static_cast<std::size_t>(n_shape_offsets_raw);
    const std::size_t n_shapes = static_cast<std::size_t>(n_shapes_raw);
    if (
        cursor + n_shape_offsets + n_shapes > arena.labels.size() ||
        n_shape_offsets != arena.offsets.size()
    ) {
        arena.shape_offsets.clear();
        arena.shapes.clear();
        return;
    }
    arena.shape_offsets.assign(
        arena.labels.begin() + static_cast<std::ptrdiff_t>(cursor),
        arena.labels.begin() + static_cast<std::ptrdiff_t>(
            cursor + n_shape_offsets
        )
    );
    cursor += n_shape_offsets;
    arena.shapes.assign(
        arena.labels.begin() + static_cast<std::ptrdiff_t>(cursor),
        arena.labels.begin() + static_cast<std::ptrdiff_t>(
            cursor + n_shapes
        )
    );
    if (
        arena.shape_offsets.empty() ||
        arena.shape_offsets.front() != 0 ||
        static_cast<std::size_t>(arena.shape_offsets.back()) != n_shapes
    ) {
        arena.shape_offsets.clear();
        arena.shapes.clear();
    }
}

template <std::size_t Rank>
std::vector<std::array<std::uint32_t, Rank>> compile_boundary_block_dims(
    const std::int64_t* offsets,
    std::size_t n_offsets,
    const std::int64_t* shape_offsets,
    std::size_t n_shape_offsets,
    const std::int64_t* shapes,
    std::size_t n_shapes,
    const char* name
) {
    if (
        offsets == nullptr || shape_offsets == nullptr || shapes == nullptr
        || n_offsets == 0 || n_shape_offsets != n_offsets
        || offsets[0] != 0 || shape_offsets[0] != 0
    ) {
        throw std::invalid_argument(
            std::string("Compiled boundary ") + name
            + " metadata is inconsistent."
        );
    }
    std::vector<std::array<std::uint32_t, Rank>> result(n_offsets - 1);
    for (std::size_t block = 0; block + 1 < n_offsets; ++block) {
        const std::int64_t shape_start = shape_offsets[block];
        const std::int64_t shape_stop = shape_offsets[block + 1];
        if (
            shape_start < 0
            || shape_stop - shape_start != static_cast<std::int64_t>(Rank)
            || static_cast<std::size_t>(shape_stop) > n_shapes
            || offsets[block] < 0
            || offsets[block + 1] < offsets[block]
        ) {
            throw std::invalid_argument(
                std::string("Compiled boundary ") + name
                + " block metadata is inconsistent."
            );
        }
        std::size_t elements = 1;
        for (std::size_t axis = 0; axis < Rank; ++axis) {
            const std::int64_t extent = shapes[
                static_cast<std::size_t>(shape_start) + axis
            ];
            if (
                extent <= 0
                || extent > static_cast<std::int64_t>(
                    std::numeric_limits<std::uint32_t>::max()
                )
            ) {
                throw std::overflow_error(
                    std::string("Compiled boundary ") + name
                    + " block extent is invalid."
                );
            }
            result[block][axis] = static_cast<std::uint32_t>(extent);
            elements *= static_cast<std::size_t>(extent);
        }
        if (
            static_cast<std::size_t>(
                offsets[block + 1] - offsets[block]
            ) != elements
        ) {
            throw std::invalid_argument(
                std::string("Compiled boundary ") + name
                + " block size is inconsistent."
            );
        }
    }
    return result;
}

bool MovingEnvironment::boundary_installed(
    const std::string& side,
    std::int64_t bond,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision
) const noexcept {
    if ((side != "left" && side != "right") || bond < 0) {
        return false;
    }
    const auto it = boundaries_.find(side + ":" + std::to_string(bond));
    return (
        it != boundaries_.end() &&
        it->second.topology_revision == topology_revision &&
        it->second.numeric_revision == numeric_revision
    );
}

bool MovingEnvironment::metric_boundary_installed(
    const std::string& side,
    std::int64_t bond,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision
) const noexcept {
    if ((side != "left" && side != "right") || bond < 0) {
        return false;
    }
    const auto it = metric_boundaries_.find(
        side + ":" + std::to_string(bond)
    );
    return (
        it != metric_boundaries_.end() &&
        it->second.topology_revision == topology_revision &&
        it->second.numeric_revision == numeric_revision
    );
}

bool MovingEnvironment::advance_boundary(
    const std::string& side,
    std::int64_t parent_bond,
    std::int64_t child_bond,
    bool left,
    const std::int64_t* routes,
    std::size_t n_routes,
    const double* bra_values,
    std::size_t n_bra_values,
    const std::int64_t* bra_offsets,
    std::size_t n_bra_offsets,
    const std::int64_t* bra_shape_offsets,
    std::size_t n_bra_shape_offsets,
    const std::int64_t* bra_shapes,
    std::size_t n_bra_shapes,
    const double* ket_values,
    std::size_t n_ket_values,
    const std::int64_t* ket_offsets,
    std::size_t n_ket_offsets,
    const std::int64_t* ket_shape_offsets,
    std::size_t n_ket_shape_offsets,
    const std::int64_t* ket_shapes,
    std::size_t n_ket_shapes,
    const double* mpo_values,
    std::size_t n_mpo_values,
    const std::int64_t* mpo_offsets,
    std::size_t n_mpo_offsets,
    const std::int64_t* mpo_shape_offsets,
    std::size_t n_mpo_shape_offsets,
    const std::int64_t* mpo_shapes,
    std::size_t n_mpo_shapes,
    const std::int64_t* output_offsets,
    std::size_t n_output_offsets,
    const std::int64_t* output_shape_offsets,
    std::size_t n_output_shape_offsets,
    const std::int64_t* output_shapes,
    std::size_t n_output_shapes,
    const std::int64_t* output_labels,
    std::size_t n_output_labels,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision,
    const double* route_coefficients,
    bool metric_boundary,
    bool accumulate_output,
    bool finalize_update,
    const NormalComplementaryBoundaryAction* compiled_action
) {
    const double started = wall_seconds();
    if (
        side != (left ? "left" : "right") ||
        parent_bond < 0 ||
        child_bond < 0
    ) {
        throw std::invalid_argument(
            "Boundary update direction and bond metadata are inconsistent."
        );
    }
    if (
        (
            n_routes != 0
            && routes == nullptr
            && compiled_action == nullptr
        ) ||
        bra_values == nullptr || ket_values == nullptr || mpo_values == nullptr ||
        bra_offsets == nullptr || ket_offsets == nullptr || mpo_offsets == nullptr ||
        bra_shape_offsets == nullptr || ket_shape_offsets == nullptr ||
        mpo_shape_offsets == nullptr || bra_shapes == nullptr ||
        ket_shapes == nullptr || mpo_shapes == nullptr ||
        output_offsets == nullptr || output_shape_offsets == nullptr ||
        output_shapes == nullptr || output_labels == nullptr
    ) {
        throw std::invalid_argument("Boundary update received a null buffer.");
    }
    auto& boundary_store = metric_boundary
        ? metric_boundaries_
        : boundaries_;
    const auto parent_it = boundary_store.find(
        boundary_key(side, parent_bond)
    );
    if (parent_it == boundary_store.end()) {
        throw std::invalid_argument(
            "Boundary update parent is not installed in the moving environment."
        );
    }
    const PackedArena& parent = parent_it->second;
    if (
        parent.values == nullptr ||
        parent.offsets.empty() ||
        parent.shape_offsets.size() != parent.offsets.size()
    ) {
        throw std::invalid_argument("Boundary update parent arena is incomplete.");
    }

    const auto validate_pool = [](
        const double* values,
        std::size_t n_values,
        const std::int64_t* offsets,
        std::size_t n_offsets,
        const std::int64_t* shape_offsets,
        std::size_t n_shape_offsets,
        const std::int64_t* shapes,
        std::size_t n_shapes,
        const char* name
    ) {
        static_cast<void>(values);
        static_cast<void>(shapes);
        if (
            n_offsets == 0 ||
            n_shape_offsets != n_offsets ||
            offsets[0] != 0 ||
            shape_offsets[0] != 0 ||
            offsets[n_offsets - 1] < 0 ||
            shape_offsets[n_shape_offsets - 1] < 0 ||
            static_cast<std::size_t>(offsets[n_offsets - 1]) != n_values ||
            static_cast<std::size_t>(shape_offsets[n_shape_offsets - 1]) != n_shapes
        ) {
            throw std::invalid_argument(
                std::string("Boundary update ") + name +
                " pool metadata is inconsistent."
            );
        }
    };
    validate_pool(
        bra_values, n_bra_values, bra_offsets, n_bra_offsets,
        bra_shape_offsets, n_bra_shape_offsets, bra_shapes, n_bra_shapes, "bra"
    );
    validate_pool(
        ket_values, n_ket_values, ket_offsets, n_ket_offsets,
        ket_shape_offsets, n_ket_shape_offsets, ket_shapes, n_ket_shapes, "ket"
    );
    validate_pool(
        mpo_values, n_mpo_values, mpo_offsets, n_mpo_offsets,
        mpo_shape_offsets, n_mpo_shape_offsets, mpo_shapes, n_mpo_shapes, "MPO"
    );
    if (
        n_output_offsets == 0 ||
        n_output_shape_offsets != n_output_offsets ||
        output_offsets[0] != 0 ||
        output_shape_offsets[0] != 0 ||
        output_offsets[n_output_offsets - 1] < 0 ||
        output_shape_offsets[n_output_shape_offsets - 1] < 0 ||
        static_cast<std::size_t>(
            output_shape_offsets[n_output_shape_offsets - 1]
        ) != n_output_shapes
    ) {
        throw std::invalid_argument(
            "Boundary update output pool metadata is inconsistent."
        );
    }
    if (
        compiled_action != nullptr
        && (
            compiled_action->routes.size() != n_routes
            || compiled_action->parent_block_dims.size() + 1
                != parent.offsets.size()
            || compiled_action->bra_block_dims.size() + 1
                != n_bra_offsets
            || compiled_action->ket_block_dims.size() + 1
                != n_ket_offsets
            || compiled_action->mpo_block_dims.size() + 1
                != n_mpo_offsets
            || compiled_action->output_block_dims.size() + 1
                != n_output_offsets
        )
    ) {
        throw std::logic_error(
            "Compiled boundary block topology is stale."
        );
    }

    const std::string child_key = boundary_key(side, child_bond);
    PackedArena& child = boundary_store[child_key];
    const bool same_topology =
        child.topology_revision == topology_revision &&
        child.offsets.size() == n_output_offsets &&
        child.labels.size() == n_output_labels &&
        std::equal(
            child.offsets.begin(), child.offsets.end(), output_offsets
        ) &&
        std::equal(
            child.labels.begin(), child.labels.end(), output_labels
        );
    if (!same_topology) {
        child.offsets.assign(
            output_offsets,
            output_offsets + n_output_offsets
        );
        child.labels.assign(output_labels, output_labels + n_output_labels);
        child.shape_offsets.assign(
            output_shape_offsets,
            output_shape_offsets + n_output_shape_offsets
        );
        child.shapes.assign(output_shapes, output_shapes + n_output_shapes);
        child.topology_revision = topology_revision;
        ++boundary_topology_builds_;
        ++boundary_update_topology_builds_;
    }
    const std::size_t n_output_values =
        static_cast<std::size_t>(output_offsets[n_output_offsets - 1]);
    if (accumulate_output) {
        if (
            !same_topology ||
            !child.owned_values ||
            child.owned_values->size() != n_output_values
        ) {
            throw std::logic_error(
                "Boundary batch accumulation requires an initialized output."
            );
        }
    } else {
        const bool allocate_output =
            !child.owned_values ||
            child.owned_values.use_count() != 1;
        if (
            allocate_output ||
            child.owned_values->capacity() < n_output_values
        ) {
            ++boundary_reallocations_;
        }
        if (allocate_output) {
            child.owned_values =
                std::make_shared<std::vector<double>>();
        }
        child.owned_values->assign(n_output_values, 0.0);
    }
    child.values = child.owned_values->data();
    child.n_values = child.owned_values->size();
    child.numeric_revision = numeric_revision;
    child.owns_values = true;

    const auto dims = [](
        const std::int64_t* offsets,
        std::size_t n_offsets,
        const std::int64_t* shape_offsets,
        std::size_t n_shape_offsets,
        const std::int64_t* shapes,
        std::size_t n_shapes,
        std::int64_t index,
        std::size_t rank,
        const char* name
    ) -> std::array<std::size_t, 4> {
        if (
            index < 0 ||
            static_cast<std::size_t>(index + 1) >= n_offsets ||
            static_cast<std::size_t>(index + 1) >= n_shape_offsets
        ) {
            throw std::out_of_range(
                std::string("Boundary update ") + name +
                " block index is out of range."
            );
        }
        const std::int64_t shape_start = shape_offsets[index];
        const std::int64_t shape_stop = shape_offsets[index + 1];
        if (
            shape_start < 0 ||
            shape_stop - shape_start != static_cast<std::int64_t>(rank) ||
            static_cast<std::size_t>(shape_stop) > n_shapes
        ) {
            throw std::invalid_argument(
                std::string("Boundary update ") + name +
                " block rank is inconsistent."
            );
        }
        std::array<std::size_t, 4> result{1, 1, 1, 1};
        std::size_t elements = 1;
        for (std::size_t axis = 0; axis < rank; ++axis) {
            const std::int64_t extent =
                shapes[static_cast<std::size_t>(shape_start) + axis];
            if (extent <= 0) {
                throw std::invalid_argument(
                    std::string("Boundary update ") + name +
                    " block has a nonpositive extent."
                );
            }
            result[axis] = static_cast<std::size_t>(extent);
            elements *= result[axis];
        }
        if (
            offsets[index] < 0 ||
            offsets[index + 1] - offsets[index] !=
                static_cast<std::int64_t>(elements)
        ) {
            throw std::invalid_argument(
                std::string("Boundary update ") + name +
                " block size is inconsistent."
            );
        }
        return result;
    };

    std::int64_t cached_first_parent = -1;
    std::int64_t cached_first_bra = -1;
    std::size_t cached_first_elements = 0;
    std::int64_t cached_product_parent = -1;
    std::int64_t cached_product_bra = -1;
    std::int64_t cached_product_ket = -1;
    std::size_t cached_product_elements = 0;
    for (std::size_t route_index = 0; route_index < n_routes; ++route_index) {
        const std::int64_t* route = (
            routes == nullptr
            ? nullptr
            : routes + 5 * route_index
        );
        const NormalComplementaryBoundaryRoute* compact_route = (
            compiled_action == nullptr
            ? nullptr
            : compiled_action->routes.data() + route_index
        );
        const double route_coefficient = route_coefficients == nullptr
            ? 1.0
            : route_coefficients[route_index];
        const std::int64_t parent_index = (
            compact_route == nullptr
            ? route[0]
            : compact_route->parent
        );
        const std::int64_t bra_index = (
            compact_route == nullptr
            ? route[1]
            : compact_route->bra
        );
        const std::int64_t ket_index = (
            compact_route == nullptr
            ? route[2]
            : compact_route->ket
        );
        const std::int64_t mpo_index = (
            compact_route == nullptr
            ? route[3]
            : compact_route->core
        );
        const std::int64_t output_index = (
            compact_route == nullptr
            ? route[4]
            : compact_route->output
        );
        std::array<std::size_t, 4> parent_dims{};
        std::array<std::size_t, 4> bra_dims{};
        std::array<std::size_t, 4> ket_dims{};
        std::array<std::size_t, 4> mpo_dims{};
        std::array<std::size_t, 4> output_dims{};
        if (compiled_action != nullptr) {
            const auto& parent_shape =
                compiled_action->parent_block_dims[
                    static_cast<std::size_t>(parent_index)
                ];
            const auto& bra_shape =
                compiled_action->bra_block_dims[
                    static_cast<std::size_t>(bra_index)
                ];
            const auto& ket_shape =
                compiled_action->ket_block_dims[
                    static_cast<std::size_t>(ket_index)
                ];
            const auto& mpo_shape =
                compiled_action->mpo_block_dims[
                    static_cast<std::size_t>(mpo_index)
                ];
            const auto& output_shape =
                compiled_action->output_block_dims[
                    static_cast<std::size_t>(output_index)
                ];
            parent_dims = {
                parent_shape[0], parent_shape[1], parent_shape[2], 1
            };
            bra_dims = {bra_shape[0], bra_shape[1], bra_shape[2], 1};
            ket_dims = {ket_shape[0], ket_shape[1], ket_shape[2], 1};
            mpo_dims = {
                mpo_shape[0], mpo_shape[1], mpo_shape[2], mpo_shape[3]
            };
            output_dims = {
                output_shape[0], output_shape[1], output_shape[2], 1
            };
        } else {
            parent_dims = dims(
                parent.offsets.data(), parent.offsets.size(),
                parent.shape_offsets.data(), parent.shape_offsets.size(),
                parent.shapes.data(), parent.shapes.size(),
                parent_index, 3, "parent"
            );
            bra_dims = dims(
                bra_offsets, n_bra_offsets,
                bra_shape_offsets, n_bra_shape_offsets,
                bra_shapes, n_bra_shapes, bra_index, 3, "bra"
            );
            ket_dims = dims(
                ket_offsets, n_ket_offsets,
                ket_shape_offsets, n_ket_shape_offsets,
                ket_shapes, n_ket_shapes, ket_index, 3, "ket"
            );
            mpo_dims = dims(
                mpo_offsets, n_mpo_offsets,
                mpo_shape_offsets, n_mpo_shape_offsets,
                mpo_shapes, n_mpo_shapes, mpo_index, 4, "MPO"
            );
            output_dims = dims(
                output_offsets, n_output_offsets,
                output_shape_offsets, n_output_shape_offsets,
                output_shapes, n_output_shapes, output_index, 3, "output"
            );
        }
        const double* boundary =
            parent.values + parent.offsets[static_cast<std::size_t>(parent_index)];
        const double* bra =
            bra_values + bra_offsets[static_cast<std::size_t>(bra_index)];
        const double* ket =
            ket_values + ket_offsets[static_cast<std::size_t>(ket_index)];
        const double* mpo =
            mpo_values + mpo_offsets[static_cast<std::size_t>(mpo_index)];
        double* output =
            child.owned_values->data() +
            output_offsets[static_cast<std::size_t>(output_index)];

        if (left) {
            const auto [x_dim, i_dim, j_dim, unused_parent] = parent_dims;
            const auto [bra_i, p_dim, r_dim, unused_bra] = bra_dims;
            const auto [ket_j, q_dim, s_dim, unused_ket] = ket_dims;
            const auto [mpo_x, y_dim, mpo_p, mpo_q] = mpo_dims;
            const auto [out_y, out_r, out_s, unused_output] = output_dims;
            static_cast<void>(unused_parent);
            static_cast<void>(unused_bra);
            static_cast<void>(unused_ket);
            static_cast<void>(unused_output);
            if (
                bra_i != i_dim || ket_j != j_dim ||
                mpo_x != x_dim || mpo_p != p_dim || mpo_q != q_dim ||
                out_y != y_dim || out_r != r_dim || out_s != s_dim
            ) {
                std::ostringstream message;
                message << "Left boundary update route dimensions are "
                    "inconsistent at route " << route_index
                    << ": parent=(" << x_dim << ',' << i_dim << ',' << j_dim
                    << "), bra=(" << bra_i << ',' << p_dim << ',' << r_dim
                    << "), ket=(" << ket_j << ',' << q_dim << ',' << s_dim
                    << "), mpo=(" << mpo_x << ',' << y_dim << ',' << mpo_p
                    << ',' << mpo_q << "), output=(" << out_y << ',' << out_r
                    << ',' << out_s << ").";
                throw std::invalid_argument(message.str());
            }
#ifdef __APPLE__
            if (p_dim == 1 && q_dim == 1) {
                std::size_t nonzero_coefficients = 0;
                for (std::size_t x = 0; x < x_dim; ++x)
                for (std::size_t y = 0; y < y_dim; ++y) {
                    nonzero_coefficients +=
                        mpo[x * y_dim + y] != 0.0;
                }
                const std::size_t contraction_work =
                    x_dim * r_dim * i_dim * j_dim
                    + nonzero_coefficients * r_dim * j_dim * s_dim;
                if (contraction_work >= 256) {
                    const std::size_t first_elements =
                        x_dim * r_dim * j_dim;
                    if (
                        cached_first_parent != parent_index
                        || cached_first_bra != bra_index
                        || cached_first_elements != first_elements
                    ) {
                        boundary_update_temporary_.resize(first_elements);
                        for (std::size_t x = 0; x < x_dim; ++x) {
                            cblas_dgemm(
                                101, 112, 111,
                                static_cast<int>(r_dim),
                                static_cast<int>(j_dim),
                                static_cast<int>(i_dim),
                                1.0,
                                bra,
                                static_cast<int>(r_dim),
                                boundary + x * i_dim * j_dim,
                                static_cast<int>(j_dim),
                                0.0,
                                boundary_update_temporary_.data()
                                    + x * r_dim * j_dim,
                                static_cast<int>(j_dim)
                            );
                        }
                        cached_first_parent = parent_index;
                        cached_first_bra = bra_index;
                        cached_first_elements = first_elements;
                    }
                    const std::size_t product_elements =
                        x_dim * r_dim * s_dim;
                    if (
                        cached_product_parent != parent_index
                        || cached_product_bra != bra_index
                        || cached_product_ket != ket_index
                        || cached_product_elements != product_elements
                    ) {
                        boundary_update_product_.resize(product_elements);
                        for (std::size_t x = 0; x < x_dim; ++x) {
                            cblas_dgemm(
                                101, 111, 111,
                                static_cast<int>(r_dim),
                                static_cast<int>(s_dim),
                                static_cast<int>(j_dim),
                                1.0,
                                boundary_update_temporary_.data()
                                    + x * r_dim * j_dim,
                                static_cast<int>(j_dim),
                                ket,
                                static_cast<int>(s_dim),
                                0.0,
                                boundary_update_product_.data()
                                    + x * r_dim * s_dim,
                                static_cast<int>(s_dim)
                            );
                        }
                        cached_product_parent = parent_index;
                        cached_product_bra = bra_index;
                        cached_product_ket = ket_index;
                        cached_product_elements = product_elements;
                    }
                    for (std::size_t x = 0; x < x_dim; ++x) {
                        const double* product =
                            boundary_update_product_.data()
                            + x * r_dim * s_dim;
                        for (std::size_t y = 0; y < y_dim; ++y) {
                            const double coefficient =
                                route_coefficient * mpo[x * y_dim + y];
                            if (coefficient == 0.0) {
                                continue;
                            }
                            cblas_daxpy(
                                static_cast<int>(r_dim * s_dim),
                                coefficient,
                                product,
                                1,
                                output + y * r_dim * s_dim,
                                1
                            );
                        }
                    }
                    continue;
                }
            }
#endif
            for (std::size_t x = 0; x < x_dim; ++x) {
                for (std::size_t y = 0; y < y_dim; ++y) {
                    for (std::size_t p = 0; p < p_dim; ++p) {
                        for (std::size_t q = 0; q < q_dim; ++q) {
                            const double coefficient =
                                route_coefficient *
                                mpo[((x * y_dim + y) * p_dim + p) * q_dim + q];
                            if (coefficient == 0.0) {
                                continue;
                            }
                            for (std::size_t i = 0; i < i_dim; ++i) {
                                for (std::size_t r = 0; r < r_dim; ++r) {
                                    const double bra_value =
                                        bra[(i * p_dim + p) * r_dim + r] *
                                        coefficient;
                                    if (bra_value == 0.0) {
                                        continue;
                                    }
                                    for (std::size_t j = 0; j < j_dim; ++j) {
                                        const double env_value =
                                            boundary[
                                                (x * i_dim + i) * j_dim + j
                                            ] * bra_value;
                                        if (env_value == 0.0) {
                                            continue;
                                        }
                                        double* output_row =
                                            output +
                                            (y * r_dim + r) * s_dim;
                                        const double* ket_row =
                                            ket +
                                            (j * q_dim + q) * s_dim;
                                        for (
                                            std::size_t s = 0;
                                            s < s_dim;
                                            ++s
                                        ) {
                                            output_row[s] +=
                                                env_value * ket_row[s];
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } else {
            const auto [y_dim, r_dim, s_dim, unused_parent] = parent_dims;
            const auto [i_dim, p_dim, bra_r, unused_bra] = bra_dims;
            const auto [j_dim, q_dim, ket_s, unused_ket] = ket_dims;
            const auto [x_dim, mpo_y, mpo_p, mpo_q] = mpo_dims;
            const auto [out_x, out_i, out_j, unused_output] = output_dims;
            static_cast<void>(unused_parent);
            static_cast<void>(unused_bra);
            static_cast<void>(unused_ket);
            static_cast<void>(unused_output);
            if (
                bra_r != r_dim || ket_s != s_dim ||
                mpo_y != y_dim || mpo_p != p_dim || mpo_q != q_dim ||
                out_x != x_dim || out_i != i_dim || out_j != j_dim
            ) {
                std::ostringstream message;
                message << "Right boundary update route dimensions are "
                    "inconsistent at route " << route_index
                    << ": parent=(" << y_dim << ',' << r_dim << ',' << s_dim
                    << "), bra=(" << i_dim << ',' << p_dim << ',' << bra_r
                    << "), ket=(" << j_dim << ',' << q_dim << ',' << ket_s
                    << "), mpo=(" << x_dim << ',' << mpo_y << ',' << mpo_p
                    << ',' << mpo_q << "), output=(" << out_x << ',' << out_i
                    << ',' << out_j << ").";
                throw std::invalid_argument(message.str());
            }
#ifdef __APPLE__
            if (p_dim == 1 && q_dim == 1) {
                std::size_t nonzero_coefficients = 0;
                for (std::size_t x = 0; x < x_dim; ++x)
                for (std::size_t y = 0; y < y_dim; ++y) {
                    nonzero_coefficients +=
                        mpo[x * y_dim + y] != 0.0;
                }
                const std::size_t contraction_work =
                    y_dim * i_dim * r_dim * s_dim
                    + nonzero_coefficients * i_dim * s_dim * j_dim;
                if (contraction_work >= 256) {
                    const std::size_t first_elements =
                        y_dim * i_dim * s_dim;
                    if (
                        cached_first_parent != parent_index
                        || cached_first_bra != bra_index
                        || cached_first_elements != first_elements
                    ) {
                        boundary_update_temporary_.resize(first_elements);
                        for (std::size_t y = 0; y < y_dim; ++y) {
                            cblas_dgemm(
                                101, 111, 111,
                                static_cast<int>(i_dim),
                                static_cast<int>(s_dim),
                                static_cast<int>(r_dim),
                                1.0,
                                bra,
                                static_cast<int>(r_dim),
                                boundary + y * r_dim * s_dim,
                                static_cast<int>(s_dim),
                                0.0,
                                boundary_update_temporary_.data()
                                    + y * i_dim * s_dim,
                                static_cast<int>(s_dim)
                            );
                        }
                        cached_first_parent = parent_index;
                        cached_first_bra = bra_index;
                        cached_first_elements = first_elements;
                    }
                    const std::size_t product_elements =
                        y_dim * i_dim * j_dim;
                    if (
                        cached_product_parent != parent_index
                        || cached_product_bra != bra_index
                        || cached_product_ket != ket_index
                        || cached_product_elements != product_elements
                    ) {
                        boundary_update_product_.resize(product_elements);
                        for (std::size_t y = 0; y < y_dim; ++y) {
                            cblas_dgemm(
                                101, 111, 112,
                                static_cast<int>(i_dim),
                                static_cast<int>(j_dim),
                                static_cast<int>(s_dim),
                                1.0,
                                boundary_update_temporary_.data()
                                    + y * i_dim * s_dim,
                                static_cast<int>(s_dim),
                                ket,
                                static_cast<int>(s_dim),
                                0.0,
                                boundary_update_product_.data()
                                    + y * i_dim * j_dim,
                                static_cast<int>(j_dim)
                            );
                        }
                        cached_product_parent = parent_index;
                        cached_product_bra = bra_index;
                        cached_product_ket = ket_index;
                        cached_product_elements = product_elements;
                    }
                    for (std::size_t y = 0; y < y_dim; ++y) {
                        const double* product =
                            boundary_update_product_.data()
                            + y * i_dim * j_dim;
                        for (std::size_t x = 0; x < x_dim; ++x) {
                            const double coefficient =
                                route_coefficient * mpo[x * y_dim + y];
                            if (coefficient == 0.0) {
                                continue;
                            }
                            cblas_daxpy(
                                static_cast<int>(i_dim * j_dim),
                                coefficient,
                                product,
                                1,
                                output + x * i_dim * j_dim,
                                1
                            );
                        }
                    }
                    continue;
                }
            }
#endif
            for (std::size_t x = 0; x < x_dim; ++x) {
                for (std::size_t y = 0; y < y_dim; ++y) {
                    for (std::size_t p = 0; p < p_dim; ++p) {
                        for (std::size_t q = 0; q < q_dim; ++q) {
                            const double coefficient =
                                route_coefficient *
                                mpo[((x * y_dim + y) * p_dim + p) * q_dim + q];
                            if (coefficient == 0.0) {
                                continue;
                            }
                            for (std::size_t i = 0; i < i_dim; ++i) {
                                for (std::size_t r = 0; r < r_dim; ++r) {
                                    const double bra_value =
                                        bra[(i * p_dim + p) * r_dim + r] *
                                        coefficient;
                                    if (bra_value == 0.0) {
                                        continue;
                                    }
                                    for (std::size_t s = 0; s < s_dim; ++s) {
                                        const double env_value =
                                            boundary[
                                                (y * r_dim + r) * s_dim + s
                                            ] * bra_value;
                                        if (env_value == 0.0) {
                                            continue;
                                        }
                                        const double* ket_column =
                                            ket + (q * s_dim + s);
                                        double* output_row =
                                            output +
                                            (x * i_dim + i) * j_dim;
                                        for (
                                            std::size_t j = 0;
                                            j < j_dim;
                                            ++j
                                        ) {
                                            output_row[j] +=
                                                env_value *
                                                ket_column[j * q_dim * s_dim];
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if (finalize_update) {
        ++boundary_numeric_refreshes_;
        ++boundary_update_calls_;
    }
    boundary_update_routes_ += n_routes;
    boundary_update_seconds_ += wall_seconds() - started;
    return same_topology;
}

bool MovingEnvironment::advance_boundary_complex(
    const std::string& side,
    std::int64_t parent_bond,
    std::int64_t child_bond,
    bool left,
    const std::int64_t* routes,
    std::size_t n_routes,
    const Complex* bra_values,
    std::size_t n_bra_values,
    const std::int64_t* bra_offsets,
    std::size_t n_bra_offsets,
    const std::int64_t* bra_shape_offsets,
    std::size_t n_bra_shape_offsets,
    const std::int64_t* bra_shapes,
    std::size_t n_bra_shapes,
    const Complex* ket_values,
    std::size_t n_ket_values,
    const std::int64_t* ket_offsets,
    std::size_t n_ket_offsets,
    const std::int64_t* ket_shape_offsets,
    std::size_t n_ket_shape_offsets,
    const std::int64_t* ket_shapes,
    std::size_t n_ket_shapes,
    const Complex* mpo_values,
    std::size_t n_mpo_values,
    const std::int64_t* mpo_offsets,
    std::size_t n_mpo_offsets,
    const std::int64_t* mpo_shape_offsets,
    std::size_t n_mpo_shape_offsets,
    const std::int64_t* mpo_shapes,
    std::size_t n_mpo_shapes,
    const std::int64_t* output_offsets,
    std::size_t n_output_offsets,
    const std::int64_t* output_shape_offsets,
    std::size_t n_output_shape_offsets,
    const std::int64_t* output_shapes,
    std::size_t n_output_shapes,
    const std::int64_t* output_labels,
    std::size_t n_output_labels,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision,
    const double* route_coefficients,
    bool metric_boundary
) {
    const double started = wall_seconds();
    if (side != (left ? "left" : "right") || parent_bond < 0 || child_bond < 0) {
        throw std::invalid_argument(
            "Complex boundary direction and bond metadata are inconsistent."
        );
    }
    if (
        (n_routes != 0 && routes == nullptr) || bra_values == nullptr ||
        ket_values == nullptr || mpo_values == nullptr || bra_offsets == nullptr ||
        ket_offsets == nullptr || mpo_offsets == nullptr ||
        bra_shape_offsets == nullptr || ket_shape_offsets == nullptr ||
        mpo_shape_offsets == nullptr || bra_shapes == nullptr ||
        ket_shapes == nullptr || mpo_shapes == nullptr ||
        output_offsets == nullptr || output_shape_offsets == nullptr ||
        output_shapes == nullptr || output_labels == nullptr
    ) {
        throw std::invalid_argument("Complex boundary update received a null buffer.");
    }

    const auto validate_pool = [](
        std::size_t n_values,
        const std::int64_t* offsets,
        std::size_t n_offsets,
        const std::int64_t* shape_offsets,
        std::size_t n_shape_offsets,
        std::size_t n_shapes,
        const char* name
    ) {
        if (
            n_offsets == 0 || n_shape_offsets != n_offsets ||
            offsets[0] != 0 || shape_offsets[0] != 0 ||
            offsets[n_offsets - 1] < 0 || shape_offsets[n_shape_offsets - 1] < 0 ||
            static_cast<std::size_t>(offsets[n_offsets - 1]) != n_values ||
            static_cast<std::size_t>(shape_offsets[n_shape_offsets - 1]) != n_shapes
        ) {
            throw std::invalid_argument(
                std::string("Complex boundary ") + name + " pool is inconsistent."
            );
        }
    };
    validate_pool(
        n_bra_values, bra_offsets, n_bra_offsets, bra_shape_offsets,
        n_bra_shape_offsets, n_bra_shapes, "bra"
    );
    validate_pool(
        n_ket_values, ket_offsets, n_ket_offsets, ket_shape_offsets,
        n_ket_shape_offsets, n_ket_shapes, "ket"
    );
    validate_pool(
        n_mpo_values, mpo_offsets, n_mpo_offsets, mpo_shape_offsets,
        n_mpo_shape_offsets, n_mpo_shapes, "MPO"
    );
    if (
        n_output_offsets == 0 || n_output_shape_offsets != n_output_offsets ||
        output_offsets[0] != 0 || output_shape_offsets[0] != 0 ||
        output_offsets[n_output_offsets - 1] < 0 ||
        output_shape_offsets[n_output_shape_offsets - 1] < 0 ||
        static_cast<std::size_t>(
            output_shape_offsets[n_output_shape_offsets - 1]
        ) != n_output_shapes
    ) {
        throw std::invalid_argument("Complex boundary output pool is inconsistent.");
    }

    auto& complex_store = metric_boundary
        ? complex_metric_boundaries_
        : complex_boundaries_;
    const auto& real_store = metric_boundary
        ? metric_boundaries_
        : boundaries_;
    const std::string parent_key = boundary_key(side, parent_bond);
    const auto complex_parent_it = complex_store.find(parent_key);
    const auto real_parent_it = real_store.find(parent_key);
    if (complex_parent_it == complex_store.end() && real_parent_it == real_store.end()) {
        throw std::invalid_argument(
            "Complex boundary parent is not installed in the moving environment."
        );
    }
    const bool complex_parent = complex_parent_it != complex_store.end();
    const std::vector<std::int64_t>& parent_offsets = complex_parent
        ? complex_parent_it->second.offsets
        : real_parent_it->second.offsets;
    const std::vector<std::int64_t>& parent_shape_offsets = complex_parent
        ? complex_parent_it->second.shape_offsets
        : real_parent_it->second.shape_offsets;
    const std::vector<std::int64_t>& parent_shapes = complex_parent
        ? complex_parent_it->second.shapes
        : real_parent_it->second.shapes;
    const Complex* complex_parent_values = complex_parent
        && complex_parent_it->second.owned_values
        ? complex_parent_it->second.owned_values->data()
        : nullptr;
    const double* real_parent_values = complex_parent
        ? nullptr
        : real_parent_it->second.values;
    if (
        parent_offsets.empty() || parent_shape_offsets.size() != parent_offsets.size() ||
        (complex_parent && !complex_parent_it->second.owned_values) ||
        (!complex_parent && real_parent_values == nullptr)
    ) {
        throw std::invalid_argument("Complex boundary parent arena is incomplete.");
    }

    const std::string child_key = boundary_key(side, child_bond);
    ComplexPackedArena& child = complex_store[child_key];
    const bool same_topology =
        child.topology_revision == topology_revision &&
        child.offsets.size() == n_output_offsets &&
        child.labels.size() == n_output_labels &&
        std::equal(child.offsets.begin(), child.offsets.end(), output_offsets) &&
        std::equal(child.labels.begin(), child.labels.end(), output_labels);
    if (!same_topology) {
        child.offsets.assign(output_offsets, output_offsets + n_output_offsets);
        child.labels.assign(output_labels, output_labels + n_output_labels);
        child.shape_offsets.assign(
            output_shape_offsets, output_shape_offsets + n_output_shape_offsets
        );
        child.shapes.assign(output_shapes, output_shapes + n_output_shapes);
        child.topology_revision = topology_revision;
        ++boundary_topology_builds_;
        ++boundary_update_topology_builds_;
    }
    const std::size_t n_output_values =
        static_cast<std::size_t>(output_offsets[n_output_offsets - 1]);
    if (!child.owned_values || child.owned_values.use_count() != 1) {
        child.owned_values = std::make_shared<std::vector<Complex>>();
        ++boundary_reallocations_;
    } else if (child.owned_values->capacity() < n_output_values) {
        ++boundary_reallocations_;
    }
    child.owned_values->assign(n_output_values, Complex{});
    child.numeric_revision = numeric_revision;

    const auto dims = [](
        const std::int64_t* offsets,
        std::size_t n_offsets,
        const std::int64_t* shape_offsets,
        std::size_t n_shape_offsets,
        const std::int64_t* shapes,
        std::size_t n_shapes,
        std::int64_t index,
        std::size_t rank,
        const char* name
    ) {
        if (
            index < 0 || static_cast<std::size_t>(index + 1) >= n_offsets ||
            static_cast<std::size_t>(index + 1) >= n_shape_offsets
        ) {
            throw std::out_of_range(std::string(name) + " block index is out of range.");
        }
        const std::int64_t shape_start = shape_offsets[index];
        const std::int64_t shape_stop = shape_offsets[index + 1];
        if (
            shape_start < 0 || shape_stop - shape_start != static_cast<std::int64_t>(rank) ||
            static_cast<std::size_t>(shape_stop) > n_shapes
        ) {
            throw std::invalid_argument(std::string(name) + " block rank is inconsistent.");
        }
        std::array<std::size_t, 4> result{1, 1, 1, 1};
        std::size_t elements = 1;
        for (std::size_t axis = 0; axis < rank; ++axis) {
            const auto extent = shapes[static_cast<std::size_t>(shape_start) + axis];
            if (extent <= 0) {
                throw std::invalid_argument(std::string(name) + " block extent is invalid.");
            }
            result[axis] = static_cast<std::size_t>(extent);
            elements *= result[axis];
        }
        if (
            offsets[index] < 0 || offsets[index + 1] - offsets[index] !=
                static_cast<std::int64_t>(elements)
        ) {
            throw std::invalid_argument(std::string(name) + " block size is inconsistent.");
        }
        return result;
    };

    for (std::size_t route_index = 0; route_index < n_routes; ++route_index) {
        const std::int64_t* route = routes + 5 * route_index;
        const std::int64_t parent_index = route[0];
        const std::int64_t bra_index = route[1];
        const std::int64_t ket_index = route[2];
        const std::int64_t mpo_index = route[3];
        const std::int64_t output_index = route[4];
        const auto parent_dims = dims(
            parent_offsets.data(), parent_offsets.size(),
            parent_shape_offsets.data(), parent_shape_offsets.size(),
            parent_shapes.data(), parent_shapes.size(), parent_index, 3, "parent"
        );
        const auto bra_dims = dims(
            bra_offsets, n_bra_offsets, bra_shape_offsets, n_bra_shape_offsets,
            bra_shapes, n_bra_shapes, bra_index, 3, "bra"
        );
        const auto ket_dims = dims(
            ket_offsets, n_ket_offsets, ket_shape_offsets, n_ket_shape_offsets,
            ket_shapes, n_ket_shapes, ket_index, 3, "ket"
        );
        const auto mpo_dims = dims(
            mpo_offsets, n_mpo_offsets, mpo_shape_offsets, n_mpo_shape_offsets,
            mpo_shapes, n_mpo_shapes, mpo_index, 4, "MPO"
        );
        const auto output_dims = dims(
            output_offsets, n_output_offsets, output_shape_offsets,
            n_output_shape_offsets, output_shapes, n_output_shapes,
            output_index, 3, "output"
        );
        const std::size_t parent_start =
            static_cast<std::size_t>(parent_offsets[parent_index]);
        const Complex* bra = bra_values + bra_offsets[bra_index];
        const Complex* ket = ket_values + ket_offsets[ket_index];
        const Complex* mpo = mpo_values + mpo_offsets[mpo_index];
        Complex* output = child.owned_values->data() + output_offsets[output_index];
        const double route_coefficient = route_coefficients == nullptr
            ? 1.0
            : route_coefficients[route_index];
        const auto parent_value = [&](std::size_t index) {
            return complex_parent
                ? complex_parent_values[parent_start + index]
                : Complex(real_parent_values[parent_start + index], 0.0);
        };

        if (left) {
            const auto [x_dim, i_dim, j_dim, unused_parent] = parent_dims;
            const auto [bra_i, p_dim, r_dim, unused_bra] = bra_dims;
            const auto [ket_j, q_dim, s_dim, unused_ket] = ket_dims;
            const auto [mpo_x, y_dim, mpo_p, mpo_q] = mpo_dims;
            const auto [out_y, out_r, out_s, unused_output] = output_dims;
            static_cast<void>(unused_parent); static_cast<void>(unused_bra);
            static_cast<void>(unused_ket); static_cast<void>(unused_output);
            if (
                bra_i != i_dim || ket_j != j_dim || mpo_x != x_dim ||
                mpo_p != p_dim || mpo_q != q_dim || out_y != y_dim ||
                out_r != r_dim || out_s != s_dim
            ) {
                throw std::invalid_argument("Complex left boundary route dimensions disagree.");
            }
            for (std::size_t x = 0; x < x_dim; ++x)
            for (std::size_t y = 0; y < y_dim; ++y)
            for (std::size_t p = 0; p < p_dim; ++p)
            for (std::size_t q = 0; q < q_dim; ++q) {
                const Complex coefficient = route_coefficient *
                    mpo[((x * y_dim + y) * p_dim + p) * q_dim + q];
                if (coefficient == Complex{}) continue;
                for (std::size_t i = 0; i < i_dim; ++i)
                for (std::size_t r = 0; r < r_dim; ++r) {
                    const Complex bra_value =
                        std::conj(bra[(i * p_dim + p) * r_dim + r]) * coefficient;
                    if (bra_value == Complex{}) continue;
                    for (std::size_t j = 0; j < j_dim; ++j) {
                        const Complex value =
                            parent_value((x * i_dim + i) * j_dim + j) * bra_value;
                        if (value == Complex{}) continue;
                        Complex* output_row = output + (y * r_dim + r) * s_dim;
                        const Complex* ket_row = ket + (j * q_dim + q) * s_dim;
                        for (std::size_t s = 0; s < s_dim; ++s)
                            output_row[s] += value * ket_row[s];
                    }
                }
            }
        } else {
            const auto [y_dim, r_dim, s_dim, unused_parent] = parent_dims;
            const auto [i_dim, p_dim, bra_r, unused_bra] = bra_dims;
            const auto [j_dim, q_dim, ket_s, unused_ket] = ket_dims;
            const auto [x_dim, mpo_y, mpo_p, mpo_q] = mpo_dims;
            const auto [out_x, out_i, out_j, unused_output] = output_dims;
            static_cast<void>(unused_parent); static_cast<void>(unused_bra);
            static_cast<void>(unused_ket); static_cast<void>(unused_output);
            if (
                bra_r != r_dim || ket_s != s_dim || mpo_y != y_dim ||
                mpo_p != p_dim || mpo_q != q_dim || out_x != x_dim ||
                out_i != i_dim || out_j != j_dim
            ) {
                throw std::invalid_argument("Complex right boundary route dimensions disagree.");
            }
            for (std::size_t x = 0; x < x_dim; ++x)
            for (std::size_t y = 0; y < y_dim; ++y)
            for (std::size_t p = 0; p < p_dim; ++p)
            for (std::size_t q = 0; q < q_dim; ++q) {
                const Complex coefficient = route_coefficient *
                    mpo[((x * y_dim + y) * p_dim + p) * q_dim + q];
                if (coefficient == Complex{}) continue;
                for (std::size_t i = 0; i < i_dim; ++i)
                for (std::size_t r = 0; r < r_dim; ++r) {
                    const Complex bra_value =
                        std::conj(bra[(i * p_dim + p) * r_dim + r]) * coefficient;
                    if (bra_value == Complex{}) continue;
                    for (std::size_t s = 0; s < s_dim; ++s) {
                        const Complex value =
                            parent_value((y * r_dim + r) * s_dim + s) * bra_value;
                        if (value == Complex{}) continue;
                        const Complex* ket_column = ket + (q * s_dim + s);
                        Complex* output_row = output + (x * i_dim + i) * j_dim;
                        for (std::size_t j = 0; j < j_dim; ++j)
                            output_row[j] += value * ket_column[j * q_dim * s_dim];
                    }
                }
            }
        }
    }
    ++boundary_numeric_refreshes_;
    ++boundary_update_calls_;
    boundary_update_routes_ += n_routes;
    boundary_update_seconds_ += wall_seconds() - started;
    return same_topology;
}

bool MovingEnvironment::advance_normal_complementary_boundary(
    const std::string& side,
    std::int64_t parent_bond,
    std::int64_t child_bond,
    bool left,
    std::int64_t site,
    bool reduced_physical,
    bool dual_right_boundary,
    const std::int32_t* routes,
    std::size_t n_routes,
    const double* bra_values,
    std::size_t n_bra_values,
    const std::int64_t* bra_offsets,
    std::size_t n_bra_offsets,
    const std::int64_t* bra_shape_offsets,
    std::size_t n_bra_shape_offsets,
    const std::int64_t* bra_shapes,
    std::size_t n_bra_shapes,
    const double* ket_values,
    std::size_t n_ket_values,
    const std::int64_t* ket_offsets,
    std::size_t n_ket_offsets,
    const std::int64_t* ket_shape_offsets,
    std::size_t n_ket_shape_offsets,
    const std::int64_t* ket_shapes,
    std::size_t n_ket_shapes,
    const std::int64_t* output_offsets,
    std::size_t n_output_offsets,
    const std::int64_t* output_shape_offsets,
    std::size_t n_output_shape_offsets,
    const std::int64_t* output_shapes,
    std::size_t n_output_shapes,
    const std::int64_t* output_labels,
    std::size_t n_output_labels,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision,
    std::uint64_t route_topology_revision
) {
    constexpr std::size_t physical_charge_count =
        nc_physical_charge_count;
    constexpr std::size_t operator_count = nc_operator_count;
    constexpr std::size_t components_per_operator =
        nc_components_per_operator;
    const std::string action_key = boundary_key(side, child_bond);
    auto action_it = normal_complementary_boundary_actions_.find(action_key);
    const bool reuse_action = (
        n_routes == 0 &&
        action_it != normal_complementary_boundary_actions_.end() &&
        route_topology_revision != 0 &&
        action_it->second.route_topology_revision ==
            route_topology_revision &&
        action_it->second.parent_bond == parent_bond &&
        action_it->second.child_bond == child_bond &&
        action_it->second.site == site &&
        action_it->second.left == left &&
        action_it->second.reduced_physical == reduced_physical &&
        action_it->second.dual_right_boundary == dual_right_boundary
    );
    if (!reuse_action && (routes == nullptr || n_routes == 0)) {
        throw std::invalid_argument(
            "Direct normal/complementary boundary action received an "
            "invalid or stale route plan."
        );
    }
    const NormalComplementaryPlan& plan =
        system_->normal_complementary_plan(site);
    const double* primitive_components =
        system_->normal_complementary_primitives(site);
    if (plan.component_action_offsets.size() != plan.transitions.size() + 1) {
        throw std::logic_error(
            "Direct normal/complementary component offsets are incomplete."
        );
    }

    NormalComplementaryBoundaryAction& boundary_action =
        reuse_action
        ? action_it->second
        : normal_complementary_boundary_actions_[action_key];
    if (!reuse_action) {
        boundary_action.side = side;
        boundary_action.parent_bond = parent_bond;
        boundary_action.child_bond = child_bond;
        boundary_action.site = site;
        boundary_action.left = left;
        boundary_action.reduced_physical = reduced_physical;
        boundary_action.dual_right_boundary = dual_right_boundary;
        boundary_action.route_topology_revision = (
            route_topology_revision != 0
            ? route_topology_revision
            : topology_revision
        );
        boundary_action.output_topology_revision = topology_revision;
        boundary_action.output_offsets.assign(
            output_offsets,
            output_offsets + n_output_offsets
        );
        boundary_action.output_shape_offsets.assign(
            output_shape_offsets,
            output_shape_offsets + n_output_shape_offsets
        );
        boundary_action.output_shapes.assign(
            output_shapes,
            output_shapes + n_output_shapes
        );
        boundary_action.output_labels.assign(
            output_labels,
            output_labels + n_output_labels
        );
        boundary_action.compiled = false;
        boundary_action.mpo_values.clear();
        boundary_action.mpo_offsets.clear();
        boundary_action.mpo_shape_offsets.clear();
        boundary_action.mpo_shapes.clear();
        boundary_action.parent_block_dims.clear();
        boundary_action.bra_block_dims.clear();
        boundary_action.ket_block_dims.clear();
        boundary_action.mpo_block_dims.clear();
        boundary_action.output_block_dims.clear();
        boundary_action.routes.resize(n_routes);
        for (std::size_t index = 0; index < n_routes; ++index) {
            const std::int32_t* source = routes + 13 * index;
            auto compact_index = [source](std::size_t field) {
                const std::int64_t value = source[field];
                if (
                    value < 0 ||
                    value > std::numeric_limits<std::uint16_t>::max()
                ) {
                    throw std::overflow_error(
                        "Normal/complementary route index exceeds uint16."
                    );
                }
                return static_cast<std::uint16_t>(value);
            };
            auto compact_byte = [source](std::size_t field) {
                const std::int64_t value = source[field];
                if (
                    value < 0 ||
                    value > std::numeric_limits<std::uint8_t>::max()
                ) {
                    throw std::overflow_error(
                        "Normal/complementary route quantum number exceeds uint8."
                    );
                }
                return static_cast<std::uint8_t>(value);
            };
            NormalComplementaryBoundaryRoute& target =
                boundary_action.routes[index];
            target.parent = compact_index(0);
            target.bra = compact_index(1);
            target.ket = compact_index(2);
            target.output = compact_index(6);
            static_cast<void>(compact_index(3));
            static_cast<void>(compact_byte(4));
            static_cast<void>(compact_byte(5));
            for (std::size_t spin = 0; spin < 6; ++spin)
                static_cast<void>(compact_byte(7 + spin));
        }
    }
    n_routes = boundary_action.routes.size();

    using CoreKey = std::array<std::int64_t, 10>;
    struct CoreKeyHash {
        std::size_t operator()(const CoreKey& key) const noexcept {
            std::uint64_t hash = 1469598103934665603ULL;
            for (const std::int64_t value : key) {
                hash ^= static_cast<std::uint64_t>(value);
                hash *= 1099511628211ULL;
            }
            return static_cast<std::size_t>(hash);
        }
    };
    std::vector<double>& mpo_values = boundary_action.mpo_values;
    std::vector<std::int64_t>& mpo_offsets =
        boundary_action.mpo_offsets;
    std::vector<std::int64_t>& mpo_shape_offsets =
        boundary_action.mpo_shape_offsets;
    std::vector<std::int64_t>& mpo_shapes =
        boundary_action.mpo_shapes;
    std::unordered_map<CoreKey, std::int64_t, CoreKeyHash> core_ids;
    std::unordered_map<std::uint64_t, std::vector<std::uint32_t>>
        value_core_ids;
    if (!boundary_action.compiled) {
        mpo_values.clear();
        mpo_offsets.assign(1, 0);
        mpo_shape_offsets.assign(1, 0);
        mpo_shapes.clear();
        core_ids.reserve(n_routes);
        value_core_ids.reserve(n_routes);
    for (
        std::size_t route_index = 0;
        route_index < n_routes;
        ++route_index
    ) {
        NormalComplementaryBoundaryRoute& compact_route =
            boundary_action.routes[route_index];
        const std::int32_t* source = routes + 13 * route_index;
        const std::int64_t transition_index = source[3];
        const std::int64_t physical_out_charge = source[4];
        const std::int64_t physical_in_charge = source[5];
        if (
            static_cast<std::size_t>(transition_index) >=
                plan.transitions.size() ||
            physical_out_charge >=
                static_cast<std::int64_t>(physical_charge_count) ||
            physical_in_charge >=
                static_cast<std::int64_t>(physical_charge_count)
        ) {
            throw std::out_of_range(
                "Direct normal/complementary route metadata is out of range."
            );
        }
        CoreKey key{
            transition_index,
            physical_out_charge,
            physical_in_charge,
            0,
            0,
            0,
            0,
            0,
            0,
            0,
        };
        if (reduced_physical) {
            key[3] = 1;
            for (std::size_t spin = 0; spin < 6; ++spin) {
                key[4 + spin] = source[7 + spin];
            }
        }
        auto found = core_ids.find(key);
        std::int64_t core_id = 0;
        if (found == core_ids.end()) {
            const NormalComplementaryTransition& transition =
                plan.transitions[
                    static_cast<std::size_t>(transition_index)
                ];
            const NormalComplementaryChannel& source_channel =
                plan.left_channel_quantum_numbers[
                    static_cast<std::size_t>(transition.source)
                ];
            const NormalComplementaryChannel& target_channel =
                plan.right_channel_quantum_numbers[
                    static_cast<std::size_t>(transition.target)
                ];
            const std::int32_t operator_two_j =
                local_operator_two_j(transition.local_operator);
            const std::size_t source_dimension =
                static_cast<std::size_t>(
                    source_channel.two_j + 1
                );
            const std::size_t target_dimension =
                static_cast<std::size_t>(
                    target_channel.two_j + 1
                );
            const std::size_t physical_output_dimension =
                reduced_physical
                ? 1
                : static_cast<std::size_t>(
                    physical_two_j(physical_out_charge) + 1
                );
            const std::size_t physical_input_dimension =
                reduced_physical
                ? 1
                : static_cast<std::size_t>(
                    physical_two_j(physical_in_charge) + 1
                );
            const std::size_t core_start = mpo_values.size();
            mpo_values.resize(
                core_start +
                    source_dimension *
                    target_dimension *
                    physical_output_dimension *
                    physical_input_dimension,
                0.0
            );
            const std::size_t action_start = static_cast<std::size_t>(
                plan.component_action_offsets[
                    static_cast<std::size_t>(transition_index)
                ]
            );
            const std::size_t action_stop = static_cast<std::size_t>(
                plan.component_action_offsets[
                    static_cast<std::size_t>(transition_index + 1)
                ]
            );
            for (
                std::size_t action_index = action_start;
                action_index < action_stop;
                ++action_index
            ) {
                const NormalComplementaryComponentAction& action =
                    plan.component_actions[action_index];
                const std::int32_t local_index = action.local_two_m + 2;
                if (local_index < 0 || local_index >= 5) {
                    throw std::logic_error(
                        "Direct normal/complementary component is invalid."
                    );
                }
                const std::size_t primitive_index =
                    (
                        (
                            static_cast<std::size_t>(physical_out_charge) *
                                physical_charge_count +
                            static_cast<std::size_t>(physical_in_charge)
                        ) *
                            operator_count +
                        static_cast<std::size_t>(transition.local_operator)
                    ) *
                        components_per_operator +
                    static_cast<std::size_t>(local_index);
                double primitive_value =
                    primitive_components[primitive_index];
                if (
                    std::abs(target_channel.charge) % 2 == 1 &&
                    physical_in_charge % 2 == 1
                ) {
                    primitive_value = -primitive_value;
                }
                if (reduced_physical) {
                    const std::int32_t source_two_m =
                        source_channel.two_j -
                        2 * action.source_component;
                    const std::int32_t target_two_m =
                        target_channel.two_j -
                        2 * action.target_component;
                    double dual_factor = (
                        target_channel.two_j == 0 &&
                        source_channel.two_j == operator_two_j &&
                        operator_two_j != 0
                    ) ? -static_cast<double>(operator_two_j + 1) : 1.0;
                    if (
                        operator_two_j == 1 &&
                        source_channel.two_j == 1 &&
                        target_channel.two_j == 0
                    ) {
                        dual_factor = -1.0;
                    }
                    const double recoupling =
                        reduced_environment_recoupling_impl(
                            left,
                            physical_out_charge,
                            physical_in_charge,
                            source[7],
                            source[8],
                            source[9],
                            source[10],
                            source[11],
                            source[12],
                            source_channel.two_j,
                            target_channel.two_j,
                            operator_two_j,
                            source_two_m,
                            target_two_m,
                            action.local_two_m,
                            !left && dual_right_boundary
                        );
                    mpo_values[
                        core_start +
                        static_cast<std::size_t>(
                            action.source_component
                        ) * target_dimension +
                        static_cast<std::size_t>(
                            action.target_component
                        )
                    ] += (
                        action.coefficient *
                        primitive_value *
                        dual_factor *
                        recoupling
                    );
                    continue;
                }
                for (
                    std::size_t physical_output_component = 0;
                    physical_output_component < physical_output_dimension;
                    ++physical_output_component
                ) {
                    for (
                        std::size_t physical_input_component = 0;
                        physical_input_component < physical_input_dimension;
                        ++physical_input_component
                    ) {
                        const double physical_coefficient =
                            physical_component_coefficient(
                                physical_out_charge,
                                physical_in_charge,
                                operator_two_j,
                                action.local_two_m,
                                static_cast<std::int32_t>(
                                    physical_output_component
                                ),
                                static_cast<std::int32_t>(
                                    physical_input_component
                                )
                            );
                        if (physical_coefficient == 0.0) {
                            continue;
                        }
                        mpo_values[
                            core_start +
                            (
                                (
                                    static_cast<std::size_t>(
                                        action.source_component
                                    ) * target_dimension +
                                    static_cast<std::size_t>(
                                        action.target_component
                                    )
                                ) * physical_output_dimension +
                                physical_output_component
                            ) * physical_input_dimension +
                            physical_input_component
                        ] += (
                            action.coefficient *
                            primitive_value *
                            physical_coefficient
                        );
                    }
                }
            }
            std::uint64_t value_hash = 1469598103934665603ULL;
            value_hash = fingerprint_word(value_hash, source_dimension);
            value_hash = fingerprint_word(value_hash, target_dimension);
            value_hash = fingerprint_word(
                value_hash,
                physical_output_dimension
            );
            value_hash = fingerprint_word(
                value_hash,
                physical_input_dimension
            );
            for (
                std::size_t index = core_start;
                index < mpo_values.size();
                ++index
            ) {
                value_hash = fingerprint_double(
                    value_hash,
                    mpo_values[index]
                );
            }
            const auto duplicate_candidates =
                value_core_ids.find(value_hash);
            bool duplicate = false;
            if (duplicate_candidates != value_core_ids.end()) {
                for (
                    const std::uint32_t candidate :
                    duplicate_candidates->second
                ) {
                    const std::size_t candidate_index =
                        static_cast<std::size_t>(candidate);
                    const std::size_t candidate_start =
                        static_cast<std::size_t>(
                            mpo_offsets[candidate_index]
                        );
                    const std::size_t candidate_stop =
                        static_cast<std::size_t>(
                            mpo_offsets[candidate_index + 1]
                        );
                    const std::size_t shape_start = 4 * candidate_index;
                    if (
                        candidate_stop - candidate_start
                            != mpo_values.size() - core_start
                        || mpo_shapes[shape_start]
                            != static_cast<std::int64_t>(source_dimension)
                        || mpo_shapes[shape_start + 1]
                            != static_cast<std::int64_t>(target_dimension)
                        || mpo_shapes[shape_start + 2]
                            != static_cast<std::int64_t>(
                                physical_output_dimension
                            )
                        || mpo_shapes[shape_start + 3]
                            != static_cast<std::int64_t>(
                                physical_input_dimension
                            )
                        || !std::equal(
                            mpo_values.begin()
                                + static_cast<std::ptrdiff_t>(
                                    candidate_start
                                ),
                            mpo_values.begin()
                                + static_cast<std::ptrdiff_t>(
                                    candidate_stop
                                ),
                            mpo_values.begin()
                                + static_cast<std::ptrdiff_t>(core_start)
                        )
                    ) {
                        continue;
                    }
                    core_id = candidate;
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) {
                mpo_values.resize(core_start);
            } else {
                core_id = static_cast<std::int64_t>(
                    mpo_offsets.size() - 1
                );
                mpo_offsets.push_back(
                    static_cast<std::int64_t>(mpo_values.size())
                );
                mpo_shapes.insert(
                    mpo_shapes.end(),
                    {
                        static_cast<std::int64_t>(source_dimension),
                        static_cast<std::int64_t>(target_dimension),
                        static_cast<std::int64_t>(
                            physical_output_dimension
                        ),
                        static_cast<std::int64_t>(
                            physical_input_dimension
                        ),
                    }
                );
                mpo_shape_offsets.push_back(
                    static_cast<std::int64_t>(mpo_shapes.size())
                );
                value_core_ids[value_hash].push_back(
                    static_cast<std::uint32_t>(core_id)
                );
            }
            core_ids.emplace(key, core_id);
        } else {
            core_id = found->second;
        }
        if (
            core_id < 0
            || core_id >
                static_cast<std::int64_t>(
                    std::numeric_limits<std::uint32_t>::max()
                )
        ) {
            throw std::overflow_error(
                "Normal/complementary compiled core exceeds uint32."
            );
        }
        compact_route.core = static_cast<std::uint32_t>(core_id);
    }
        std::stable_sort(
            boundary_action.routes.begin(),
            boundary_action.routes.end(),
            [](const NormalComplementaryBoundaryRoute& first,
               const NormalComplementaryBoundaryRoute& second) {
                return std::tie(
                    first.parent,
                    first.bra,
                    first.ket,
                    first.output,
                    first.core
                ) < std::tie(
                    second.parent,
                    second.bra,
                    second.ket,
                    second.output,
                    second.core
                );
            }
        );
        std::vector<NormalComplementaryBoundaryRoute> combined_routes;
        combined_routes.reserve(boundary_action.routes.size());
        std::vector<double> combined_values;
        std::vector<std::int64_t> combined_offsets(1, 0);
        std::vector<std::int64_t> combined_shape_offsets(1, 0);
        std::vector<std::int64_t> combined_shapes;
        std::unordered_map<std::uint64_t, std::vector<std::uint32_t>>
            combined_core_ids;
        std::vector<double> combined_core;
        std::size_t route_cursor = 0;
        while (route_cursor < boundary_action.routes.size()) {
            const NormalComplementaryBoundaryRoute& first =
                boundary_action.routes[route_cursor];
            std::size_t route_stop = route_cursor + 1;
            while (route_stop < boundary_action.routes.size()) {
                const NormalComplementaryBoundaryRoute& candidate =
                    boundary_action.routes[route_stop];
                if (
                    std::tie(
                        candidate.parent,
                        candidate.bra,
                        candidate.ket,
                        candidate.output
                    ) != std::tie(
                        first.parent,
                        first.bra,
                        first.ket,
                        first.output
                    )
                ) {
                    break;
                }
                ++route_stop;
            }
            const std::size_t first_core = first.core;
            const std::size_t first_shape_start =
                static_cast<std::size_t>(mpo_shape_offsets[first_core]);
            const std::size_t first_shape_stop =
                static_cast<std::size_t>(mpo_shape_offsets[first_core + 1]);
            const std::size_t first_value_start =
                static_cast<std::size_t>(mpo_offsets[first_core]);
            const std::size_t first_value_stop =
                static_cast<std::size_t>(mpo_offsets[first_core + 1]);
            if (first_shape_stop - first_shape_start != 4) {
                throw std::logic_error(
                    "Compiled boundary core rank changed during coalescing."
                );
            }
            combined_core.assign(
                first_value_stop - first_value_start,
                0.0
            );
            for (
                std::size_t route_index = route_cursor;
                route_index < route_stop;
                ++route_index
            ) {
                const std::size_t core =
                    boundary_action.routes[route_index].core;
                const std::size_t shape_start =
                    static_cast<std::size_t>(mpo_shape_offsets[core]);
                const std::size_t shape_stop =
                    static_cast<std::size_t>(mpo_shape_offsets[core + 1]);
                const std::size_t value_start =
                    static_cast<std::size_t>(mpo_offsets[core]);
                const std::size_t value_stop =
                    static_cast<std::size_t>(mpo_offsets[core + 1]);
                if (
                    shape_stop - shape_start != 4
                    || value_stop - value_start != combined_core.size()
                    || !std::equal(
                        mpo_shapes.begin()
                            + static_cast<std::ptrdiff_t>(shape_start),
                        mpo_shapes.begin()
                            + static_cast<std::ptrdiff_t>(shape_stop),
                        mpo_shapes.begin()
                            + static_cast<std::ptrdiff_t>(first_shape_start)
                    )
                ) {
                    throw std::logic_error(
                        "Coalesced boundary core shapes disagree."
                    );
                }
                for (
                    std::size_t index = 0;
                    index < combined_core.size();
                    ++index
                ) {
                    combined_core[index] += mpo_values[value_start + index];
                }
            }
            if (std::all_of(
                combined_core.begin(),
                combined_core.end(),
                [](double value) { return value == 0.0; }
            )) {
                route_cursor = route_stop;
                continue;
            }
            std::uint64_t value_hash = 1469598103934665603ULL;
            for (
                std::size_t index = first_shape_start;
                index < first_shape_stop;
                ++index
            ) {
                value_hash = fingerprint_word(
                    value_hash,
                    static_cast<std::uint64_t>(mpo_shapes[index])
                );
            }
            for (const double value : combined_core) {
                value_hash = fingerprint_double(value_hash, value);
            }
            std::uint32_t combined_core_id =
                std::numeric_limits<std::uint32_t>::max();
            const auto duplicate = combined_core_ids.find(value_hash);
            if (duplicate != combined_core_ids.end()) {
                for (const std::uint32_t candidate : duplicate->second) {
                    const std::size_t value_start =
                        static_cast<std::size_t>(combined_offsets[candidate]);
                    const std::size_t value_stop =
                        static_cast<std::size_t>(combined_offsets[candidate + 1]);
                    const std::size_t shape_start =
                        static_cast<std::size_t>(
                            combined_shape_offsets[candidate]
                        );
                    const std::size_t shape_stop =
                        static_cast<std::size_t>(
                            combined_shape_offsets[candidate + 1]
                        );
                    if (
                        value_stop - value_start == combined_core.size()
                        && shape_stop - shape_start == 4
                        && std::equal(
                            combined_core.begin(),
                            combined_core.end(),
                            combined_values.begin()
                                + static_cast<std::ptrdiff_t>(value_start)
                        )
                        && std::equal(
                            mpo_shapes.begin()
                                + static_cast<std::ptrdiff_t>(
                                    first_shape_start
                                ),
                            mpo_shapes.begin()
                                + static_cast<std::ptrdiff_t>(
                                    first_shape_stop
                                ),
                            combined_shapes.begin()
                                + static_cast<std::ptrdiff_t>(shape_start)
                        )
                    ) {
                        combined_core_id = candidate;
                        break;
                    }
                }
            }
            if (
                combined_core_id
                == std::numeric_limits<std::uint32_t>::max()
            ) {
                if (
                    combined_offsets.size() - 1
                    >= std::numeric_limits<std::uint32_t>::max()
                ) {
                    throw std::overflow_error(
                        "Coalesced boundary core table exceeds uint32."
                    );
                }
                combined_core_id = static_cast<std::uint32_t>(
                    combined_offsets.size() - 1
                );
                combined_values.insert(
                    combined_values.end(),
                    combined_core.begin(),
                    combined_core.end()
                );
                combined_offsets.push_back(
                    static_cast<std::int64_t>(combined_values.size())
                );
                combined_shapes.insert(
                    combined_shapes.end(),
                    mpo_shapes.begin()
                        + static_cast<std::ptrdiff_t>(first_shape_start),
                    mpo_shapes.begin()
                        + static_cast<std::ptrdiff_t>(first_shape_stop)
                );
                combined_shape_offsets.push_back(
                    static_cast<std::int64_t>(combined_shapes.size())
                );
                combined_core_ids[value_hash].push_back(combined_core_id);
            }
            NormalComplementaryBoundaryRoute route = first;
            route.core = combined_core_id;
            combined_routes.push_back(route);
            route_cursor = route_stop;
        }
        boundary_action.routes = std::move(combined_routes);
        mpo_values = std::move(combined_values);
        mpo_offsets = std::move(combined_offsets);
        mpo_shape_offsets = std::move(combined_shape_offsets);
        mpo_shapes = std::move(combined_shapes);
        const auto parent_found = boundaries_.find(
            boundary_key(side, parent_bond)
        );
        if (parent_found == boundaries_.end()) {
            throw std::logic_error(
                "Compiled normal/complementary boundary parent is missing."
            );
        }
        const PackedArena& parent = parent_found->second;
        boundary_action.parent_block_dims =
            compile_boundary_block_dims<3>(
                parent.offsets.data(),
                parent.offsets.size(),
                parent.shape_offsets.data(),
                parent.shape_offsets.size(),
                parent.shapes.data(),
                parent.shapes.size(),
                "parent"
            );
        boundary_action.bra_block_dims = compile_boundary_block_dims<3>(
            bra_offsets,
            n_bra_offsets,
            bra_shape_offsets,
            n_bra_shape_offsets,
            bra_shapes,
            n_bra_shapes,
            "bra"
        );
        boundary_action.ket_block_dims = compile_boundary_block_dims<3>(
            ket_offsets,
            n_ket_offsets,
            ket_shape_offsets,
            n_ket_shape_offsets,
            ket_shapes,
            n_ket_shapes,
            "ket"
        );
        boundary_action.mpo_block_dims = compile_boundary_block_dims<4>(
            mpo_offsets.data(),
            mpo_offsets.size(),
            mpo_shape_offsets.data(),
            mpo_shape_offsets.size(),
            mpo_shapes.data(),
            mpo_shapes.size(),
            "MPO"
        );
        boundary_action.output_block_dims =
            compile_boundary_block_dims<3>(
                output_offsets,
                n_output_offsets,
                output_shape_offsets,
                n_output_shape_offsets,
                output_shapes,
                n_output_shapes,
                "output"
            );
        mpo_values.shrink_to_fit();
        mpo_offsets.shrink_to_fit();
        mpo_shape_offsets.shrink_to_fit();
        mpo_shapes.shrink_to_fit();
        boundary_action.compiled = true;
    }

    return advance_boundary(
        side,
        parent_bond,
        child_bond,
        left,
        nullptr,
        boundary_action.routes.size(),
        bra_values,
        n_bra_values,
        bra_offsets,
        n_bra_offsets,
        bra_shape_offsets,
        n_bra_shape_offsets,
        bra_shapes,
        n_bra_shapes,
        ket_values,
        n_ket_values,
        ket_offsets,
        n_ket_offsets,
        ket_shape_offsets,
        n_ket_shape_offsets,
        ket_shapes,
        n_ket_shapes,
        mpo_values.data(),
        mpo_values.size(),
        mpo_offsets.data(),
        mpo_offsets.size(),
        mpo_shape_offsets.data(),
        mpo_shape_offsets.size(),
        mpo_shapes.data(),
        mpo_shapes.size(),
        output_offsets,
        n_output_offsets,
        output_shape_offsets,
        n_output_shape_offsets,
        output_shapes,
        n_output_shapes,
        output_labels,
        n_output_labels,
        topology_revision,
        numeric_revision,
        nullptr,
        false,
        false,
        true,
        &boundary_action
    );
}

bool MovingEnvironment::install_split_site(
    std::int64_t site,
    std::vector<double>& values,
    std::vector<std::int64_t>& offsets,
    std::vector<std::int64_t>& labels,
    std::vector<std::int64_t>& shape_offsets,
    std::vector<std::int64_t>& shapes,
    std::vector<std::int64_t>& leg_sector_offsets,
    std::vector<std::int64_t>& leg_sector_labels,
    std::vector<std::int64_t>& leg_sector_dims,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision
) {
    if (
        site < 0 ||
        offsets.empty() ||
        shape_offsets.size() != offsets.size() ||
        labels.size() != 6 * (offsets.size() - 1) ||
        leg_sector_offsets.size() != 4 ||
        leg_sector_offsets.front() != 0 ||
        leg_sector_offsets.back() < 0 ||
        static_cast<std::size_t>(leg_sector_offsets.back())
            != leg_sector_dims.size() ||
        leg_sector_labels.size() != 2 * leg_sector_dims.size() ||
        offsets.front() != 0 ||
        shape_offsets.front() != 0 ||
        offsets.back() < 0 ||
        shape_offsets.back() < 0 ||
        static_cast<std::size_t>(offsets.back()) != values.size() ||
        static_cast<std::size_t>(shape_offsets.back()) != shapes.size()
    ) {
        throw std::invalid_argument(
            "Packed split-site topology does not cover its value arena."
        );
    }
    for (std::size_t block = 0; block + 1 < offsets.size(); ++block) {
        if (
            offsets[block + 1] < offsets[block] ||
            shape_offsets[block + 1] < shape_offsets[block]
        ) {
            throw std::invalid_argument(
                "Packed split-site offsets must be monotone."
            );
        }
        std::size_t elements = 1;
        for (
            std::int64_t pos = shape_offsets[block];
            pos < shape_offsets[block + 1];
            ++pos
        ) {
            const std::int64_t extent = shapes[static_cast<std::size_t>(pos)];
            if (extent < 0) {
                throw std::invalid_argument(
                    "Packed split-site shapes must be nonnegative."
                );
            }
            elements *= static_cast<std::size_t>(extent);
        }
        if (
            elements != static_cast<std::size_t>(
                offsets[block + 1] - offsets[block]
            )
        ) {
            throw std::invalid_argument(
                "Packed split-site block shape disagrees with its offsets."
            );
        }
    }

    PackedArena& arena = split_sites_[site];
    const bool same_topology =
        arena.topology_revision == topology_revision &&
        arena.offsets == offsets &&
        arena.labels == labels &&
        arena.shape_offsets == shape_offsets &&
        arena.shapes == shapes &&
        arena.leg_sector_offsets == leg_sector_offsets &&
        arena.leg_sector_labels == leg_sector_labels &&
        arena.leg_sector_dims == leg_sector_dims;
    if (!same_topology) {
        arena.offsets.swap(offsets);
        arena.labels.swap(labels);
        arena.shape_offsets.swap(shape_offsets);
        arena.shapes.swap(shapes);
        arena.leg_sector_offsets.swap(leg_sector_offsets);
        arena.leg_sector_labels.swap(leg_sector_labels);
        arena.leg_sector_dims.swap(leg_sector_dims);
        arena.topology_revision = topology_revision;
        ++split_site_topology_builds_;
    }
    auto owned_values = std::make_shared<std::vector<double>>();
    owned_values->swap(values);
    arena.owned_values = std::move(owned_values);
    arena.values = arena.owned_values->data();
    arena.n_values = arena.owned_values->size();
    arena.numeric_revision = numeric_revision;
    arena.owns_values = true;
    arena.symbolic_identity = false;
    ++split_site_installs_;
    return same_topology;
}

void MovingEnvironment::configure_state_average(
    const double* weights,
    std::size_t nroots,
    std::int64_t center_site
) {
    if (
        weights == nullptr
        || nroots < 2
        || center_site < 0
    ) {
        throw std::invalid_argument(
            "State averaging requires at least two weighted center tensors."
        );
    }
    double total = 0.0;
    state_average_weights_.assign(weights, weights + nroots);
    for (const double weight : state_average_weights_) {
        if (!std::isfinite(weight) || weight < 0.0) {
            throw std::invalid_argument(
                "State-average weights must be finite and nonnegative."
            );
        }
        total += weight;
    }
    if (total <= 0.0) {
        throw std::invalid_argument(
            "State-average weights must have a positive sum."
        );
    }
    for (double& weight : state_average_weights_) {
        weight /= total;
    }
    state_average_center_values_.assign(nroots, {});
    state_average_center_site_ = center_site;
    active_bond_root_solutions_.clear();
}

void MovingEnvironment::install_state_average_center(
    std::size_t root,
    const double* values,
    std::size_t n_values
) {
    if (
        root >= state_average_center_values_.size()
        || values == nullptr
    ) {
        throw std::invalid_argument(
            "State-average center root is outside the configured bundle."
        );
    }
    const auto common = split_sites_.find(state_average_center_site_);
    if (
        common == split_sites_.end()
        || common->second.n_values != n_values
    ) {
        throw std::invalid_argument(
            "State-average center does not match the shared site topology."
        );
    }
    state_average_center_values_[root].assign(values, values + n_values);
}

bool MovingEnvironment::state_average_installed() const noexcept {
    if (
        state_average_weights_.size() < 2
        || state_average_center_values_.size()
            != state_average_weights_.size()
        || state_average_center_site_ < 0
    ) {
        return false;
    }
    const auto common = split_sites_.find(state_average_center_site_);
    if (common == split_sites_.end()) {
        return false;
    }
    for (const auto& values : state_average_center_values_) {
        if (values.size() != common->second.n_values) {
            return false;
        }
    }
    return true;
}

std::size_t MovingEnvironment::state_average_roots() const noexcept {
    return state_average_installed()
        ? state_average_weights_.size()
        : 0;
}

std::int64_t MovingEnvironment::state_average_center_site() const noexcept {
    return state_average_installed() ? state_average_center_site_ : -1;
}

const std::vector<std::vector<double>>&
MovingEnvironment::state_average_center_values() const noexcept {
    return state_average_center_values_;
}

bool MovingEnvironment::split_site_installed(
    std::int64_t site,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision
) const noexcept {
    const auto found = split_sites_.find(site);
    return (
        found != split_sites_.end() &&
        found->second.owns_values &&
        found->second.topology_revision == topology_revision &&
        found->second.numeric_revision == numeric_revision
    );
}

void MovingEnvironment::merge_active_bond() {
    if (active_bond_ < 0) {
        throw std::logic_error(
            "An active C++ bond is required before merging sites."
        );
    }
    const auto left_found = split_sites_.find(active_bond_);
    const auto right_found = split_sites_.find(active_bond_ + 1);
    if (
        left_found == split_sites_.end() ||
        right_found == split_sites_.end()
    ) {
        throw std::logic_error(
            "Both packed MPS sites must be installed before merging."
        );
    }
    const PackedArena& left = left_found->second;
    const PackedArena& right = right_found->second;
    const auto valid_site = [](const PackedArena& site) {
        return (
            site.values != nullptr &&
            site.offsets.size() >= 2 &&
            site.shape_offsets.size() == site.offsets.size() &&
            site.labels.size() == 6 * (site.offsets.size() - 1) &&
            site.leg_sector_offsets.size() == 4 &&
            site.leg_sector_labels.size()
                == 2 * site.leg_sector_dims.size()
        );
    };
    if (!valid_site(left) || !valid_site(right)) {
        throw std::logic_error(
            "Packed MPS site topology is incomplete."
        );
    }

    const double started = wall_seconds();
    ++site_merge_calls_;
    merged_site_.values.clear();
    merged_site_.offsets.assign(1, 0);
    merged_site_.labels.clear();
    merged_site_.shape_offsets.assign(1, 0);
    merged_site_.shapes.clear();
    merged_channel_site_.values.clear();
    merged_channel_site_.offsets.assign(1, 0);
    merged_channel_site_.labels.clear();
    merged_channel_site_.shape_offsets.assign(1, 0);
    merged_channel_site_.shapes.clear();

    std::map<std::array<std::int64_t, 8>, std::size_t> merged_lookup;
    std::map<std::array<std::int64_t, 10>, std::size_t> channel_lookup;
    using SectorKey = std::array<std::int64_t, 2>;
    std::map<SectorKey, std::int64_t> left_dims;
    std::map<SectorKey, std::int64_t> left_physical_dims;
    std::map<SectorKey, std::int64_t> right_physical_dims;
    std::map<SectorKey, std::int64_t> right_dims;
    auto record_dim = [](
        std::map<SectorKey, std::int64_t>& dimensions,
        const SectorKey& sector,
        std::int64_t dimension
    ) {
        const auto inserted = dimensions.emplace(sector, dimension);
        if (!inserted.second && inserted.first->second != dimension) {
            throw std::logic_error(
                "Packed MPS sector has inconsistent multiplicity dimensions."
            );
        }
    };
    for (
        std::size_t block = 0;
        block + 1 < left.offsets.size();
        ++block
    ) {
        const std::size_t shape_start = static_cast<std::size_t>(
            left.shape_offsets[block]
        );
        const std::int64_t* label = left.labels.data() + 6 * block;
        record_dim(
            left_dims,
            SectorKey{label[0], label[1]},
            left.shapes[shape_start]
        );
        record_dim(
            left_physical_dims,
            SectorKey{label[2], label[3]},
            left.shapes[shape_start + 1]
        );
    }
    auto record_leg = [&record_dim](
        const PackedArena& site,
        std::size_t leg,
        std::map<SectorKey, std::int64_t>& dimensions
    ) {
        const std::size_t start = static_cast<std::size_t>(
            site.leg_sector_offsets[leg]
        );
        const std::size_t stop = static_cast<std::size_t>(
            site.leg_sector_offsets[leg + 1]
        );
        if (
            stop < start ||
            stop > site.leg_sector_dims.size()
        ) {
            throw std::logic_error(
                "Packed MPS leg-sector offsets are inconsistent."
            );
        }
        for (std::size_t index = start; index < stop; ++index) {
            record_dim(
                dimensions,
                SectorKey{
                    site.leg_sector_labels[2 * index],
                    site.leg_sector_labels[2 * index + 1],
                },
                site.leg_sector_dims[index]
            );
        }
    };
    record_leg(left, 0, left_dims);
    record_leg(left, 1, left_physical_dims);
    record_leg(right, 1, right_physical_dims);
    record_leg(right, 2, right_dims);
    for (
        std::size_t block = 0;
        block + 1 < right.offsets.size();
        ++block
    ) {
        const std::size_t shape_start = static_cast<std::size_t>(
            right.shape_offsets[block]
        );
        const std::int64_t* label = right.labels.data() + 6 * block;
        record_dim(
            right_physical_dims,
            SectorKey{label[2], label[3]},
            right.shapes[shape_start + 1]
        );
        record_dim(
            right_dims,
            SectorKey{label[4], label[5]},
            right.shapes[shape_start + 2]
        );
    }
    auto append_merged = [&](
        const std::array<std::int64_t, 8>& key,
        const std::array<std::int64_t, 4>& shape,
        const double* values,
        std::size_t count
    ) {
        const auto found = merged_lookup.find(key);
        if (found != merged_lookup.end()) {
            const std::size_t block = found->second;
            const std::size_t start = static_cast<std::size_t>(
                merged_site_.offsets[block]
            );
            const std::size_t stop = static_cast<std::size_t>(
                merged_site_.offsets[block + 1]
            );
            if (stop - start != count) {
                throw std::logic_error(
                    "Merged MPS block shape changed within one sector."
                );
            }
            for (std::size_t index = 0; index < count; ++index) {
                merged_site_.values[start + index] += values[index];
            }
            return;
        }
        const std::size_t block = merged_site_.offsets.size() - 1;
        merged_lookup.emplace(key, block);
        merged_site_.labels.insert(
            merged_site_.labels.end(),
            key.begin(),
            key.end()
        );
        merged_site_.shapes.insert(
            merged_site_.shapes.end(),
            shape.begin(),
            shape.end()
        );
        merged_site_.shape_offsets.push_back(
            static_cast<std::int64_t>(merged_site_.shapes.size())
        );
        merged_site_.values.insert(
            merged_site_.values.end(),
            values,
            values + count
        );
        merged_site_.offsets.push_back(
            static_cast<std::int64_t>(merged_site_.values.size())
        );
    };
    auto append_channel = [&](
        const std::array<std::int64_t, 10>& key,
        const std::array<std::int64_t, 4>& shape,
        const double* values,
        std::size_t count
    ) {
        const auto found = channel_lookup.find(key);
        if (found != channel_lookup.end()) {
            const std::size_t block = found->second;
            const std::size_t start = static_cast<std::size_t>(
                merged_channel_site_.offsets[block]
            );
            const std::size_t stop = static_cast<std::size_t>(
                merged_channel_site_.offsets[block + 1]
            );
            if (stop - start != count) {
                throw std::logic_error(
                    "Merged channel block shape changed within one sector."
                );
            }
            for (std::size_t index = 0; index < count; ++index) {
                merged_channel_site_.values[start + index] += values[index];
            }
            return;
        }
        const std::size_t block =
            merged_channel_site_.offsets.size() - 1;
        channel_lookup.emplace(key, block);
        merged_channel_site_.labels.insert(
            merged_channel_site_.labels.end(),
            key.begin(),
            key.end()
        );
        merged_channel_site_.shapes.insert(
            merged_channel_site_.shapes.end(),
            shape.begin(),
            shape.end()
        );
        merged_channel_site_.shape_offsets.push_back(
            static_cast<std::int64_t>(
                merged_channel_site_.shapes.size()
            )
        );
        merged_channel_site_.values.insert(
            merged_channel_site_.values.end(),
            values,
            values + count
        );
        merged_channel_site_.offsets.push_back(
            static_cast<std::int64_t>(
                merged_channel_site_.values.size()
            )
        );
    };

    for (
        std::size_t left_block = 0;
        left_block + 1 < left.offsets.size();
        ++left_block
    ) {
        const std::int64_t left_shape_start =
            left.shape_offsets[left_block];
        if (
            left.shape_offsets[left_block + 1] - left_shape_start != 3
        ) {
            throw std::logic_error(
                "Packed left MPS block is not rank three."
            );
        }
        const std::int64_t l = left.shapes[
            static_cast<std::size_t>(left_shape_start)
        ];
        const std::int64_t p = left.shapes[
            static_cast<std::size_t>(left_shape_start + 1)
        ];
        const std::int64_t m = left.shapes[
            static_cast<std::size_t>(left_shape_start + 2)
        ];
        const std::int64_t* left_label =
            left.labels.data() + 6 * left_block;
        for (
            std::size_t right_block = 0;
            right_block + 1 < right.offsets.size();
            ++right_block
        ) {
            const std::int64_t* right_label =
                right.labels.data() + 6 * right_block;
            if (
                left_label[4] != right_label[0] ||
                left_label[5] != right_label[1]
            ) {
                continue;
            }
            const std::int64_t right_shape_start =
                right.shape_offsets[right_block];
            if (
                right.shape_offsets[right_block + 1]
                    - right_shape_start != 3
            ) {
                throw std::logic_error(
                    "Packed right MPS block is not rank three."
                );
            }
            const std::int64_t right_middle = right.shapes[
                static_cast<std::size_t>(right_shape_start)
            ];
            const std::int64_t q = right.shapes[
                static_cast<std::size_t>(right_shape_start + 1)
            ];
            const std::int64_t r = right.shapes[
                static_cast<std::size_t>(right_shape_start + 2)
            ];
            if (m != right_middle) {
                throw std::logic_error(
                    "Adjacent packed MPS multiplicity dimensions differ."
                );
            }
            const std::int64_t rows = l * p;
            const std::int64_t cols = q * r;
            raw_temporary_real_.resize(
                static_cast<std::size_t>(rows * cols)
            );
            const double* left_values =
                left.values + left.offsets[left_block];
            const double* right_values =
                right.values + right.offsets[right_block];
#ifdef __APPLE__
            cblas_dgemm(
                101,
                111,
                111,
                static_cast<int>(rows),
                static_cast<int>(cols),
                static_cast<int>(m),
                1.0,
                left_values,
                static_cast<int>(m),
                right_values,
                static_cast<int>(cols),
                0.0,
                raw_temporary_real_.data(),
                static_cast<int>(cols)
            );
#else
            for (std::int64_t row = 0; row < rows; ++row)
            for (std::int64_t column = 0; column < cols; ++column) {
                double value = 0.0;
                for (std::int64_t middle = 0; middle < m; ++middle) {
                    value +=
                        left_values[row * m + middle] *
                        right_values[middle * cols + column];
                }
                raw_temporary_real_[
                    static_cast<std::size_t>(row * cols + column)
                ] = value;
            }
#endif
            const std::array<std::int64_t, 4> shape{l, p, q, r};
            const std::array<std::int64_t, 8> merged_key{
                left_label[0],
                left_label[1],
                left_label[2],
                left_label[3],
                right_label[2],
                right_label[3],
                right_label[4],
                right_label[5],
            };
            const std::array<std::int64_t, 10> channel_key{
                left_label[0],
                left_label[1],
                left_label[2],
                left_label[3],
                left_label[4],
                left_label[5],
                right_label[2],
                right_label[3],
                right_label[4],
                right_label[5],
            };
            const std::size_t count =
                static_cast<std::size_t>(rows * cols);
            append_merged(
                merged_key,
                shape,
                raw_temporary_real_.data(),
                count
            );
            append_channel(
                channel_key,
                shape,
                raw_temporary_real_.data(),
                count
            );
            ++site_merge_blocks_;
        }
    }

    // Mirror the reduced support expansion used by the reference path.  The
    // direct complementary-family executor needs the complete channel basis,
    // including symmetry-allowed zero blocks that seed later variational
    // growth.
    for (const auto& left_item : left_dims)
    for (const auto& physical_left_item : left_physical_dims) {
        const SectorKey& q_left = left_item.first;
        const SectorKey& q_phys_left = physical_left_item.first;
        const std::int64_t middle_charge =
            q_left[0] + q_phys_left[0];
        const std::int64_t middle_min =
            std::llabs(q_left[1] - q_phys_left[1]);
        const std::int64_t middle_max =
            q_left[1] + q_phys_left[1];
        for (
            std::int64_t middle_two_j = middle_min;
            middle_two_j <= middle_max;
            middle_two_j += 2
        )
        for (const auto& physical_right_item : right_physical_dims)
        for (const auto& right_item : right_dims) {
            const SectorKey& q_phys_right = physical_right_item.first;
            const SectorKey& q_right = right_item.first;
            if (
                q_right[0] != middle_charge + q_phys_right[0] ||
                q_right[1] <
                    std::llabs(middle_two_j - q_phys_right[1]) ||
                q_right[1] > middle_two_j + q_phys_right[1] ||
                (
                    q_right[1]
                    - std::llabs(middle_two_j - q_phys_right[1])
                ) % 2 != 0
            ) {
                continue;
            }
            const std::array<std::int64_t, 4> shape{
                left_item.second,
                physical_left_item.second,
                physical_right_item.second,
                right_item.second,
            };
            const std::size_t count = static_cast<std::size_t>(
                shape[0] * shape[1] * shape[2] * shape[3]
            );
            raw_temporary_real_.assign(count, 0.0);
            const std::array<std::int64_t, 8> merged_key{
                q_left[0],
                q_left[1],
                q_phys_left[0],
                q_phys_left[1],
                q_phys_right[0],
                q_phys_right[1],
                q_right[0],
                q_right[1],
            };
            if (merged_lookup.find(merged_key) == merged_lookup.end()) {
                append_merged(
                    merged_key,
                    shape,
                    raw_temporary_real_.data(),
                    count
                );
            }
            const std::array<std::int64_t, 10> channel_key{
                q_left[0],
                q_left[1],
                q_phys_left[0],
                q_phys_left[1],
                middle_charge,
                middle_two_j,
                q_phys_right[0],
                q_phys_right[1],
                q_right[0],
                q_right[1],
            };
            if (channel_lookup.find(channel_key) == channel_lookup.end()) {
                append_channel(
                    channel_key,
                    shape,
                    raw_temporary_real_.data(),
                    count
                );
            }
        }
    }
    site_merge_seconds_ += wall_seconds() - started;
}

const PackedSiteTensor& MovingEnvironment::merged_site() const noexcept {
    return merged_site_;
}

const PackedSiteTensor&
MovingEnvironment::merged_channel_site() const noexcept {
    return merged_channel_site_;
}

namespace {

using OwnedBoundarySector = std::array<std::int64_t, 2>;
using OwnedBoundaryOutputKey = std::array<std::int64_t, 5>;
using ContextualBoundaryIdentity = std::array<std::int64_t, 5>;
using OwnedBoundarySpecMap = std::unordered_map<
    OwnedBoundaryOutputKey,
    std::array<std::int64_t, 3>,
    IntegerArrayHash<5>
>;

struct OwnedBoundaryView {
    const std::int64_t* ket_sector_ids = nullptr;
    std::size_t n_ket_sector_ids = 0;
    const std::int64_t* entry_offsets = nullptr;
    std::size_t n_entry_offsets = 0;
    const std::int64_t* out_sector_ids = nullptr;
    std::size_t n_out_sector_ids = 0;
    const std::int64_t* channel_offsets = nullptr;
    std::size_t n_channel_offsets = 0;
    const std::int64_t* channel_ids = nullptr;
    std::size_t n_channel_ids = 0;
    std::vector<OwnedBoundarySector> sectors;
};

OwnedBoundaryView owned_boundary_view(
    const std::int64_t* labels,
    std::size_t n_labels
) {
    if (n_labels < 7) {
        throw std::logic_error("Owned boundary topology header is missing.");
    }
    std::array<std::size_t, 7> sizes{};
    std::size_t cursor = 7;
    for (std::size_t field = 0; field < sizes.size(); ++field) {
        if (labels[field] < 0) {
            throw std::logic_error("Owned boundary topology size is negative.");
        }
        sizes[field] = static_cast<std::size_t>(labels[field]);
        if (sizes[field] > n_labels - cursor) {
            throw std::logic_error("Owned boundary topology is truncated.");
        }
        cursor += sizes[field];
    }
    if (
        sizes[1] != sizes[0] + 1
        || sizes[3] != sizes[2] + 1
        || (n_labels - cursor) % 2 != 0
    ) {
        throw std::logic_error("Owned boundary topology offsets are invalid.");
    }
    OwnedBoundaryView view;
    cursor = 7;
    view.ket_sector_ids = labels + cursor;
    view.n_ket_sector_ids = sizes[0];
    cursor += sizes[0];
    view.entry_offsets = labels + cursor;
    view.n_entry_offsets = sizes[1];
    cursor += sizes[1];
    view.out_sector_ids = labels + cursor;
    view.n_out_sector_ids = sizes[2];
    cursor += sizes[2];
    view.channel_offsets = labels + cursor;
    view.n_channel_offsets = sizes[3];
    cursor += sizes[3];
    view.channel_ids = labels + cursor;
    view.n_channel_ids = sizes[4];
    cursor += sizes[4] + sizes[5] + sizes[6];
    view.sectors.reserve((n_labels - cursor) / 2);
    while (cursor + 1 < n_labels) {
        view.sectors.push_back(
            OwnedBoundarySector{
                labels[cursor],
                labels[cursor + 1],
            }
        );
        cursor += 2;
    }
    return view;
}

OwnedBoundaryView owned_boundary_view(const PackedArena& arena) {
    return owned_boundary_view(arena.labels.data(), arena.labels.size());
}

OwnedBoundaryView owned_boundary_view(
    const std::vector<std::int64_t>& labels
) {
    return owned_boundary_view(labels.data(), labels.size());
}

std::vector<ContextualBoundaryIdentity>
contextual_boundary_identities(const OwnedBoundaryView& view) {
    std::vector<ContextualBoundaryIdentity> result(
        view.n_channel_ids
    );
    std::vector<std::uint8_t> assigned(view.n_channel_ids, 0);
    for (std::size_t row = 0; row < view.n_ket_sector_ids; ++row) {
        const std::int64_t ket_id = view.ket_sector_ids[row];
        if (
            ket_id < 0 ||
            static_cast<std::size_t>(ket_id) >= view.sectors.size()
        ) {
            throw std::logic_error(
                "Contextual boundary ket sector is invalid."
            );
        }
        const std::int64_t entry_start = view.entry_offsets[row];
        const std::int64_t entry_stop = view.entry_offsets[row + 1];
        if (
            entry_start < 0 || entry_stop < entry_start ||
            static_cast<std::size_t>(entry_stop) > view.n_out_sector_ids
        ) {
            throw std::logic_error(
                "Contextual boundary entry range is invalid."
            );
        }
        for (
            std::int64_t entry = entry_start;
            entry < entry_stop;
            ++entry
        ) {
            const std::int64_t out_id = view.out_sector_ids[entry];
            if (
                out_id < 0 ||
                static_cast<std::size_t>(out_id) >= view.sectors.size()
            ) {
                throw std::logic_error(
                    "Contextual boundary output sector is invalid."
                );
            }
            const std::int64_t channel_start =
                view.channel_offsets[entry];
            const std::int64_t channel_stop =
                view.channel_offsets[entry + 1];
            if (
                channel_start < 0 || channel_stop < channel_start ||
                static_cast<std::size_t>(channel_stop)
                    > view.n_channel_ids
            ) {
                throw std::logic_error(
                    "Contextual boundary channel range is invalid."
                );
            }
            for (
                std::int64_t position = channel_start;
                position < channel_stop;
                ++position
            ) {
                const OwnedBoundarySector& out =
                    view.sectors[static_cast<std::size_t>(out_id)];
                const OwnedBoundarySector& ket =
                    view.sectors[static_cast<std::size_t>(ket_id)];
                result[static_cast<std::size_t>(position)] = {
                    out[0],
                    out[1],
                    ket[0],
                    ket[1],
                    view.channel_ids[position],
                };
                assigned[static_cast<std::size_t>(position)] = 1;
            }
        }
    }
    if (std::find(assigned.begin(), assigned.end(), 0) != assigned.end()) {
        throw std::logic_error(
            "Contextual boundary contains an unowned channel block."
        );
    }
    return result;
}

std::vector<ContextualBoundaryIdentity>
contextual_boundary_identities(const PackedArena& arena) {
    return contextual_boundary_identities(owned_boundary_view(arena));
}

std::vector<ContextualBoundaryIdentity>
contextual_boundary_identities(const std::vector<std::int64_t>& labels) {
    return contextual_boundary_identities(owned_boundary_view(labels));
}

std::uint64_t owned_boundary_structure_revision(const PackedArena& arena) {
    const auto identities = contextual_boundary_identities(arena);
    std::uint64_t revision = 1469598103934665603ULL;
    revision = fingerprint_word(revision, identities.size());
    for (const ContextualBoundaryIdentity& identity : identities) {
        for (const std::int64_t value : identity) {
            revision = fingerprint_word(
                revision,
                static_cast<std::uint64_t>(value)
            );
        }
    }
    return revision == 0 ? 1 : revision;
}

std::uint64_t split_site_structure_revision(const PackedArena& arena) {
    std::uint64_t revision = 1469598103934665603ULL;
    revision = fingerprint_word(revision, arena.labels.size());
    for (const std::int64_t value : arena.labels) {
        revision = fingerprint_word(
            revision,
            static_cast<std::uint64_t>(value)
        );
    }
    return revision == 0 ? 1 : revision;
}

std::unordered_map<
    ContextualBoundaryIdentity,
    std::uint32_t,
    IntegerArrayHash<5>
>
contextual_boundary_identity_lookup(const PackedArena& arena) {
    const auto identities = contextual_boundary_identities(arena);
    std::unordered_map<
        ContextualBoundaryIdentity,
        std::uint32_t,
        IntegerArrayHash<5>
    > result;
    result.reserve(identities.size());
    for (std::size_t block = 0; block < identities.size(); ++block) {
        if (block > std::numeric_limits<std::uint32_t>::max()) {
            throw std::overflow_error(
                "Contextual boundary block exceeds uint32 storage."
            );
        }
        result.emplace(
            identities[block],
            static_cast<std::uint32_t>(block)
        );
    }
    return result;
}

struct OwnedBoundaryOutputTopology {
    std::vector<std::int64_t> offsets{0};
    std::vector<std::int64_t> shape_offsets{0};
    std::vector<std::int64_t> shapes;
    std::vector<std::int64_t> labels;
    std::unordered_map<
        OwnedBoundaryOutputKey,
        std::int64_t,
        IntegerArrayHash<5>
    > output_indices;
    std::uint64_t revision = 1;
};

OwnedBoundaryOutputTopology owned_boundary_output_topology(
    const OwnedBoundarySpecMap& specs
) {
    if (specs.empty()) {
        throw std::logic_error("Owned boundary action has no output blocks.");
    }
    std::set<OwnedBoundarySector> sector_set;
    for (const auto& [key, shape] : specs) {
        static_cast<void>(shape);
        sector_set.insert(OwnedBoundarySector{key[0], key[1]});
        sector_set.insert(OwnedBoundarySector{key[2], key[3]});
    }
    const std::vector<OwnedBoundarySector> sectors(
        sector_set.begin(),
        sector_set.end()
    );
    std::map<OwnedBoundarySector, std::int64_t> sector_ids;
    for (std::size_t index = 0; index < sectors.size(); ++index) {
        sector_ids.emplace(
            sectors[index],
            static_cast<std::int64_t>(index)
        );
    }

    using ChannelMap = std::map<
        std::int64_t,
        std::pair<
            OwnedBoundaryOutputKey,
            std::array<std::int64_t, 3>
        >
    >;
    std::map<
        OwnedBoundarySector,
        std::map<OwnedBoundarySector, ChannelMap>
    > grouped;
    for (const auto& [key, shape] : specs) {
        grouped[OwnedBoundarySector{key[0], key[1]}]
            [OwnedBoundarySector{key[2], key[3]}]
            [key[4]] = std::make_pair(key, shape);
    }

    std::vector<std::int64_t> ket_sector_ids;
    std::vector<std::int64_t> entry_offsets{0};
    std::vector<std::int64_t> out_sector_ids;
    std::vector<std::int64_t> channel_offsets{0};
    std::vector<std::int64_t> channel_ids;
    OwnedBoundaryOutputTopology output;
    output.output_indices.reserve(specs.size());
    for (const auto& [ket, out_map] : grouped) {
        ket_sector_ids.push_back(sector_ids.at(ket));
        for (const auto& [bra, channels] : out_map) {
            out_sector_ids.push_back(sector_ids.at(bra));
            for (const auto& [channel, item] : channels) {
                const auto& key = item.first;
                const auto& shape = item.second;
                const std::int64_t output_index =
                    static_cast<std::int64_t>(
                        output.output_indices.size()
                    );
                output.output_indices.emplace(key, output_index);
                channel_ids.push_back(channel);
                std::int64_t elements = 1;
                for (const std::int64_t dimension : shape) {
                    if (dimension <= 0) {
                        throw std::logic_error(
                            "Owned boundary output has invalid dimensions."
                        );
                    }
                    elements *= dimension;
                    output.shapes.push_back(dimension);
                }
                output.offsets.push_back(output.offsets.back() + elements);
                output.shape_offsets.push_back(
                    static_cast<std::int64_t>(output.shapes.size())
                );
            }
            channel_offsets.push_back(
                static_cast<std::int64_t>(channel_ids.size())
            );
        }
        entry_offsets.push_back(
            static_cast<std::int64_t>(out_sector_ids.size())
        );
    }

    const std::array<std::int64_t, 7> header{
        static_cast<std::int64_t>(ket_sector_ids.size()),
        static_cast<std::int64_t>(entry_offsets.size()),
        static_cast<std::int64_t>(out_sector_ids.size()),
        static_cast<std::int64_t>(channel_offsets.size()),
        static_cast<std::int64_t>(channel_ids.size()),
        static_cast<std::int64_t>(output.shape_offsets.size()),
        static_cast<std::int64_t>(output.shapes.size()),
    };
    output.labels.insert(output.labels.end(), header.begin(), header.end());
    const auto append = [&output](const std::vector<std::int64_t>& values) {
        output.labels.insert(
            output.labels.end(),
            values.begin(),
            values.end()
        );
    };
    append(ket_sector_ids);
    append(entry_offsets);
    append(out_sector_ids);
    append(channel_offsets);
    append(channel_ids);
    append(output.shape_offsets);
    append(output.shapes);
    for (const OwnedBoundarySector& sector : sectors) {
        output.labels.push_back(sector[0]);
        output.labels.push_back(sector[1]);
    }
    std::uint64_t revision = 1469598103934665603ULL;
    for (const std::int64_t value : output.labels) {
        revision = fingerprint_word(
            revision,
            static_cast<std::uint64_t>(value)
        );
    }
    output.revision = revision == 0 ? 1 : revision;
    return output;
}

struct OwnedBoundarySiteEntry {
    std::int64_t boundary_sector = -1;
    OwnedBoundarySector next_sector{};
    std::int64_t physical_charge = 0;
    std::int64_t physical_two_j = 0;
    std::int64_t boundary_two_j = 0;
    std::int64_t next_two_j = 0;
    std::int64_t next_dimension = 0;
    std::int64_t block = -1;
};

std::vector<OwnedBoundarySiteEntry> owned_boundary_site_entries(
    const PackedArena& site,
    const std::map<OwnedBoundarySector, std::int64_t>& parent_sector_ids,
    bool left
) {
    std::vector<OwnedBoundarySiteEntry> entries;
    const std::size_t blocks =
        site.offsets.empty() ? 0 : site.offsets.size() - 1;
    entries.reserve(blocks);
    for (std::size_t block = 0; block < blocks; ++block) {
        if (
            site.labels.size() < 6 * (block + 1)
            || site.shape_offsets.size() <= block + 1
            || site.shape_offsets[block + 1] - site.shape_offsets[block] != 3
        ) {
            throw std::logic_error("Owned split-site topology is incomplete.");
        }
        const std::int64_t* label = site.labels.data() + 6 * block;
        const std::size_t shape_start = static_cast<std::size_t>(
            site.shape_offsets[block]
        );
        const OwnedBoundarySector boundary{
            label[left ? 0 : 4],
            label[left ? 1 : 5],
        };
        const auto found = parent_sector_ids.find(boundary);
        if (found == parent_sector_ids.end()) {
            continue;
        }
        entries.push_back(
            OwnedBoundarySiteEntry{
                found->second,
                OwnedBoundarySector{
                    label[left ? 4 : 0],
                    label[left ? 5 : 1],
                },
                label[2],
                label[3],
                boundary[1],
                label[left ? 5 : 1],
                site.shapes[shape_start + (left ? 2 : 0)],
                static_cast<std::int64_t>(block),
            }
        );
    }
    return entries;
}

void refresh_normal_complementary_boundary_shapes(
    NormalComplementaryBoundaryAction& action,
    const PackedArena& parent,
    const PackedArena& site
) {
    const auto site_dims = compile_boundary_block_dims<3>(
        site.offsets.data(),
        site.offsets.size(),
        site.shape_offsets.data(),
        site.shape_offsets.size(),
        site.shapes.data(),
        site.shapes.size(),
        "split site"
    );
    std::map<OwnedBoundarySector, std::uint32_t> next_dimensions;
    for (std::size_t block = 0; block < site_dims.size(); ++block) {
        if (site.labels.size() < 6 * (block + 1)) {
            throw std::logic_error(
                "Owned split-site structural labels are incomplete."
            );
        }
        const std::int64_t* label = site.labels.data() + 6 * block;
        const OwnedBoundarySector next{
            label[action.left ? 4 : 0],
            label[action.left ? 5 : 1],
        };
        const std::uint32_t dimension =
            site_dims[block][action.left ? 2 : 0];
        const auto inserted = next_dimensions.emplace(next, dimension);
        if (!inserted.second && inserted.first->second != dimension) {
            throw std::logic_error(
                "Split-site blocks disagree on a bond-sector dimension."
            );
        }
    }

    const auto output_identities = contextual_boundary_identities(
        action.output_labels
    );
    if (
        action.output_offsets.size() != output_identities.size() + 1
        || action.output_shape_offsets.size()
            != output_identities.size() + 1
    ) {
        throw std::logic_error(
            "Cached complementary output topology is incomplete."
        );
    }
    action.output_offsets[0] = 0;
    for (std::size_t block = 0; block < output_identities.size(); ++block) {
        const std::size_t shape_start = static_cast<std::size_t>(
            action.output_shape_offsets[block]
        );
        const std::size_t shape_stop = static_cast<std::size_t>(
            action.output_shape_offsets[block + 1]
        );
        if (
            shape_stop - shape_start != 3
            || shape_stop > action.output_shapes.size()
        ) {
            throw std::logic_error(
                "Cached complementary output block is not rank three."
            );
        }
        const ContextualBoundaryIdentity& identity =
            output_identities[block];
        const auto bra = next_dimensions.find(
            OwnedBoundarySector{identity[0], identity[1]}
        );
        const auto ket = next_dimensions.find(
            OwnedBoundarySector{identity[2], identity[3]}
        );
        if (bra == next_dimensions.end() || ket == next_dimensions.end()) {
            throw std::logic_error(
                "Cached complementary output sector left the split site."
            );
        }
        action.output_shapes[shape_start + 1] = bra->second;
        action.output_shapes[shape_start + 2] = ket->second;
        const std::int64_t elements =
            action.output_shapes[shape_start]
            * action.output_shapes[shape_start + 1]
            * action.output_shapes[shape_start + 2];
        action.output_offsets[block + 1] =
            action.output_offsets[block] + elements;
    }

    if (action.output_labels.size() < 7) {
        throw std::logic_error(
            "Cached complementary output labels are incomplete."
        );
    }
    std::size_t shape_cursor = 7;
    for (std::size_t field = 0; field < 5; ++field) {
        if (action.output_labels[field] < 0) {
            throw std::logic_error(
                "Cached complementary output label size is invalid."
            );
        }
        shape_cursor += static_cast<std::size_t>(
            action.output_labels[field]
        );
    }
    const std::size_t stored_shape_offsets = static_cast<std::size_t>(
        action.output_labels[5]
    );
    const std::size_t stored_shapes = static_cast<std::size_t>(
        action.output_labels[6]
    );
    if (
        stored_shape_offsets != action.output_shape_offsets.size()
        || stored_shapes != action.output_shapes.size()
        || shape_cursor + stored_shape_offsets + stored_shapes
            > action.output_labels.size()
    ) {
        throw std::logic_error(
            "Cached complementary output shape labels are inconsistent."
        );
    }
    std::copy(
        action.output_shape_offsets.begin(),
        action.output_shape_offsets.end(),
        action.output_labels.begin()
            + static_cast<std::ptrdiff_t>(shape_cursor)
    );
    shape_cursor += stored_shape_offsets;
    std::copy(
        action.output_shapes.begin(),
        action.output_shapes.end(),
        action.output_labels.begin()
            + static_cast<std::ptrdiff_t>(shape_cursor)
    );
    std::uint64_t output_revision = 1469598103934665603ULL;
    for (const std::int64_t value : action.output_labels) {
        output_revision = fingerprint_word(
            output_revision,
            static_cast<std::uint64_t>(value)
        );
    }
    action.output_topology_revision =
        output_revision == 0 ? 1 : output_revision;

    action.parent_block_dims = compile_boundary_block_dims<3>(
        parent.offsets.data(),
        parent.offsets.size(),
        parent.shape_offsets.data(),
        parent.shape_offsets.size(),
        parent.shapes.data(),
        parent.shapes.size(),
        "parent"
    );
    action.bra_block_dims = site_dims;
    action.ket_block_dims = site_dims;
    action.output_block_dims = compile_boundary_block_dims<3>(
        action.output_offsets.data(),
        action.output_offsets.size(),
        action.output_shape_offsets.data(),
        action.output_shape_offsets.size(),
        action.output_shapes.data(),
        action.output_shapes.size(),
        "output"
    );
}

}  // namespace

void MovingEnvironment::rebuild_normal_complementary_boundary_from_split_site(
    const std::string& side,
    std::int64_t parent_bond,
    std::int64_t child_bond,
    std::int64_t site,
    std::uint64_t numeric_revision
) {
    const bool left = side == "left";
    if (!left && side != "right") {
        throw std::invalid_argument("Owned NC boundary side is invalid.");
    }
    const auto parent_found = boundaries_.find(
        boundary_key(side, parent_bond)
    );
    const auto site_found = split_sites_.find(site);
    if (
        parent_found == boundaries_.end()
        || site_found == split_sites_.end()
        || !site_found->second.owns_values
    ) {
        throw std::logic_error(
            "Owned NC boundary rebuild requires parent and split-site arenas."
        );
    }
    const std::string action_key = boundary_key(side, child_bond);
    const auto cached_action =
        normal_complementary_boundary_actions_.find(action_key);
    const bool same_action_structure = (
        cached_action != normal_complementary_boundary_actions_.end()
        && cached_action->second.parent_bond == parent_bond
        && cached_action->second.site == site
        && cached_action->second.left == left
    );
    if (
        same_action_structure
        && cached_action->second.parent_topology_revision
            == parent_found->second.topology_revision
        && cached_action->second.site_topology_revision
            == site_found->second.topology_revision
    ) {
        replay_normal_complementary_boundary_from_split_site(
            side,
            child_bond,
            numeric_revision
        );
        return;
    }
    const std::uint64_t parent_structure_revision =
        owned_boundary_structure_revision(parent_found->second);
    const std::uint64_t site_structure_revision =
        split_site_structure_revision(site_found->second);
    if (
        same_action_structure
        && cached_action->second.compiled
        && !cached_action->second.routes.empty()
        && cached_action->second.parent_structure_revision
            == parent_structure_revision
        && cached_action->second.site_structure_revision
            == site_structure_revision
    ) {
        NormalComplementaryBoundaryAction& action =
            normal_complementary_boundary_actions_.at(action_key);
        refresh_normal_complementary_boundary_shapes(
            action,
            parent_found->second,
            site_found->second
        );
        action.parent_topology_revision =
            parent_found->second.topology_revision;
        action.site_topology_revision = site_found->second.topology_revision;
        replay_normal_complementary_boundary_from_split_site(
            side,
            child_bond,
            numeric_revision
        );
        return;
    }
    const OwnedBoundaryView parent = owned_boundary_view(
        parent_found->second
    );
    std::map<OwnedBoundarySector, std::int64_t> parent_sector_ids;
    for (std::size_t index = 0; index < parent.sectors.size(); ++index) {
        parent_sector_ids.emplace(
            parent.sectors[index],
            static_cast<std::int64_t>(index)
        );
    }
    const auto entries = owned_boundary_site_entries(
        site_found->second,
        parent_sector_ids,
        left
    );
    std::vector<std::vector<std::size_t>> entries_by_boundary(
        parent.sectors.size()
    );
    for (std::size_t index = 0; index < entries.size(); ++index) {
        const std::int64_t boundary_sector = entries[index].boundary_sector;
        if (
            boundary_sector < 0
            || static_cast<std::size_t>(boundary_sector)
                >= entries_by_boundary.size()
        ) {
            throw std::logic_error(
                "Owned NC site entry has an invalid parent sector."
            );
        }
        entries_by_boundary[static_cast<std::size_t>(boundary_sector)]
            .push_back(index);
    }
    const NormalComplementaryPlan& plan =
        system_->normal_complementary_plan(site);
    const auto& output_channels = left
        ? plan.right_channel_quantum_numbers
        : plan.left_channel_quantum_numbers;
    struct PendingRoute {
        std::array<std::int32_t, 13> values{};
        std::uint32_t output_spec = 0;
    };
    std::vector<PendingRoute> pending;
    pending.reserve(parent.n_channel_ids);
    OwnedBoundarySpecMap specs;
    specs.reserve(parent.n_channel_ids * 2);
    std::unordered_map<
        OwnedBoundaryOutputKey,
        std::uint32_t,
        IntegerArrayHash<5>
    > output_spec_ids;
    output_spec_ids.reserve(parent.n_channel_ids * 2);
    const auto compact_route_value = [](std::int64_t value) {
        if (
            value < 0
            || value > std::numeric_limits<std::int32_t>::max()
        ) {
            throw std::overflow_error(
                "Owned NC route exceeds compact integer storage."
            );
        }
        return static_cast<std::int32_t>(value);
    };
    for (std::size_t row = 0; row < parent.n_ket_sector_ids; ++row) {
        const std::int64_t ket_sector = parent.ket_sector_ids[row];
        const std::int64_t entry_start = parent.entry_offsets[row];
        const std::int64_t entry_stop = parent.entry_offsets[row + 1];
        for (
            std::int64_t parent_entry = entry_start;
            parent_entry < entry_stop;
            ++parent_entry
        ) {
            const std::int64_t bra_sector =
                parent.out_sector_ids[parent_entry];
            if (
                bra_sector < 0
                || ket_sector < 0
                || static_cast<std::size_t>(bra_sector)
                    >= entries_by_boundary.size()
                || static_cast<std::size_t>(ket_sector)
                    >= entries_by_boundary.size()
            ) {
                continue;
            }
            const auto& bra_entries = entries_by_boundary[
                static_cast<std::size_t>(bra_sector)
            ];
            const auto& ket_entries = entries_by_boundary[
                static_cast<std::size_t>(ket_sector)
            ];
            for (const std::size_t bra_index : bra_entries) {
                const OwnedBoundarySiteEntry& bra = entries[bra_index];
                for (const std::size_t ket_index : ket_entries) {
                    const OwnedBoundarySiteEntry& ket = entries[ket_index];
                    if (
                        bra.physical_charge < 0
                        || bra.physical_charge >=
                            static_cast<std::int64_t>(
                                nc_physical_charge_count
                            )
                        || ket.physical_charge < 0
                        || ket.physical_charge >=
                            static_cast<std::int64_t>(
                                nc_physical_charge_count
                            )
                    ) {
                        continue;
                    }
                    const std::size_t physical_pair =
                        static_cast<std::size_t>(
                            bra.physical_charge
                                * nc_physical_charge_count
                            + ket.physical_charge
                        );
                    const auto& transition_offsets = left
                        ? plan.active_source_transition_offsets[physical_pair]
                        : plan.active_target_transition_offsets[physical_pair];
                    const auto& indexed_transitions = left
                        ? plan.active_source_transitions[physical_pair]
                        : plan.active_target_transitions[physical_pair];
                    for (
                        std::int64_t channel_position =
                            parent.channel_offsets[parent_entry];
                        channel_position <
                            parent.channel_offsets[parent_entry + 1];
                        ++channel_position
                    ) {
                        const std::int64_t parent_channel =
                            parent.channel_ids[channel_position];
                        if (
                            parent_channel < 0
                            || static_cast<std::size_t>(parent_channel + 1)
                                >= transition_offsets.size()
                        ) {
                            continue;
                        }
                        const std::size_t transition_start =
                            static_cast<std::size_t>(transition_offsets[
                                static_cast<std::size_t>(parent_channel)
                            ]);
                        const std::size_t transition_stop =
                            static_cast<std::size_t>(transition_offsets[
                                static_cast<std::size_t>(parent_channel) + 1
                            ]);
                        for (
                            std::size_t transition_position = transition_start;
                            transition_position < transition_stop;
                            ++transition_position
                        ) {
                            const std::int64_t transition_index =
                                indexed_transitions[transition_position];
                            const NormalComplementaryTransition& transition =
                                plan.transitions[
                                    static_cast<std::size_t>(
                                        transition_index
                                    )
                                ];
                            const std::int64_t output_channel = left
                                ? transition.target
                                : transition.source;
                            const OwnedBoundaryOutputKey output_key{
                                ket.next_sector[0],
                                ket.next_sector[1],
                                bra.next_sector[0],
                                bra.next_sector[1],
                                output_channel,
                            };
                            const std::array<std::int64_t, 3> shape{
                                static_cast<std::int64_t>(
                                    output_channels[
                                        static_cast<std::size_t>(
                                            output_channel
                                        )
                                    ].two_j
                                ) + 1,
                                bra.next_dimension,
                                ket.next_dimension,
                            };
                            const auto inserted = specs.emplace(
                                output_key,
                                shape
                            );
                            if (
                                !inserted.second
                                && inserted.first->second != shape
                            ) {
                                throw std::logic_error(
                                    "Owned NC routes disagree on output shape."
                                );
                            }
                            std::uint32_t output_spec = 0;
                            if (inserted.second) {
                                if (
                                    output_spec_ids.size()
                                    > std::numeric_limits<std::uint32_t>::max()
                                ) {
                                    throw std::overflow_error(
                                        "Owned NC output topology exceeds "
                                        "uint32 storage."
                                    );
                                }
                                output_spec = static_cast<std::uint32_t>(
                                    output_spec_ids.size()
                                );
                                output_spec_ids.emplace(
                                    output_key,
                                    output_spec
                                );
                            } else {
                                output_spec = output_spec_ids.at(output_key);
                            }
                            PendingRoute route;
                            const std::array<std::int64_t, 13> values{
                                channel_position,
                                bra.block,
                                ket.block,
                                transition_index,
                                bra.physical_charge,
                                ket.physical_charge,
                                0,
                                bra.boundary_two_j,
                                ket.boundary_two_j,
                                bra.physical_two_j,
                                ket.physical_two_j,
                                bra.next_two_j,
                                ket.next_two_j,
                            };
                            for (std::size_t field = 0; field < values.size();
                                 ++field) {
                                route.values[field] = compact_route_value(
                                    values[field]
                                );
                            }
                            route.output_spec = output_spec;
                            pending.push_back(std::move(route));
                        }
                    }
                }
            }
        }
    }
    const OwnedBoundaryOutputTopology output =
        owned_boundary_output_topology(specs);
    std::vector<std::int32_t> output_indices(specs.size(), -1);
    for (const auto& [key, output_index] : output.output_indices) {
        if (
            output_index < 0
            || output_index > std::numeric_limits<std::int32_t>::max()
        ) {
            throw std::overflow_error(
                "Owned NC output index exceeds compact integer storage."
            );
        }
        output_indices.at(output_spec_ids.at(key)) =
            static_cast<std::int32_t>(output_index);
    }
    std::vector<std::int32_t> routes;
    routes.reserve(13 * pending.size());
    for (PendingRoute& route : pending) {
        route.values[6] = output_indices.at(route.output_spec);
        routes.insert(
            routes.end(),
            route.values.begin(),
            route.values.end()
        );
    }
    std::uint64_t route_revision = 1469598103934665603ULL;
    route_revision = fingerprint_word(
        route_revision,
        parent_found->second.topology_revision
    );
    route_revision = fingerprint_word(
        route_revision,
        site_found->second.topology_revision
    );
    route_revision = fingerprint_word(
        route_revision,
        system_->revision()
    );
    route_revision = fingerprint_word(
        route_revision,
        static_cast<std::uint64_t>(site)
    );
    route_revision = fingerprint_word(
        route_revision,
        left ? std::uint64_t{1} : std::uint64_t{0}
    );
    advance_normal_complementary_boundary_from_split_site(
        side,
        parent_bond,
        child_bond,
        left,
        site,
        true,
        true,
        routes.data(),
        pending.size(),
        output.offsets.data(),
        output.offsets.size(),
        output.shape_offsets.data(),
        output.shape_offsets.size(),
        output.shapes.data(),
        output.shapes.size(),
        output.labels.data(),
        output.labels.size(),
        output.revision,
        numeric_revision,
        route_revision == 0 ? 1 : route_revision
    );
    normal_complementary_boundary_actions_[action_key]
        .parent_topology_revision =
            parent_found->second.topology_revision;
    normal_complementary_boundary_actions_[action_key]
        .parent_structure_revision = parent_structure_revision;
    normal_complementary_boundary_actions_[action_key]
        .site_structure_revision = site_structure_revision;
}

void MovingEnvironment::rebuild_metric_boundary_from_split_site(
    const std::string& side,
    std::int64_t parent_bond,
    std::int64_t child_bond,
    std::int64_t site,
    std::uint64_t numeric_revision
) {
    const bool left = side == "left";
    if (!left && side != "right") {
        throw std::invalid_argument("Owned metric boundary side is invalid.");
    }
    const auto parent_found = metric_boundaries_.find(
        boundary_key(side, parent_bond)
    );
    const auto site_found = split_sites_.find(site);
    if (
        parent_found == metric_boundaries_.end()
        || site_found == split_sites_.end()
        || !site_found->second.owns_values
    ) {
        throw std::logic_error(
            "Owned metric rebuild requires parent and split-site arenas."
        );
    }
    const std::string action_key = boundary_key(side, child_bond);
    const auto cached_action = metric_boundary_actions_.find(action_key);
    if (
        cached_action != metric_boundary_actions_.end()
        && cached_action->second.parent_bond == parent_bond
        && cached_action->second.site == site
        && cached_action->second.left == left
        && cached_action->second.parent_topology_revision
            == parent_found->second.topology_revision
        && cached_action->second.site_topology_revision
            == site_found->second.topology_revision
    ) {
        replay_metric_boundary_from_split_site(
            side,
            child_bond,
            numeric_revision
        );
        return;
    }
    const OwnedBoundaryView parent = owned_boundary_view(
        parent_found->second
    );
    std::map<OwnedBoundarySector, std::int64_t> parent_sector_ids;
    for (std::size_t index = 0; index < parent.sectors.size(); ++index) {
        parent_sector_ids.emplace(
            parent.sectors[index],
            static_cast<std::int64_t>(index)
        );
    }
    const auto entries = owned_boundary_site_entries(
        site_found->second,
        parent_sector_ids,
        left
    );
    struct PendingRoute {
        std::array<std::int64_t, 5> values{};
        OwnedBoundaryOutputKey output_key{};
        double coefficient = 1.0;
    };
    std::vector<PendingRoute> pending;
    OwnedBoundarySpecMap specs;
    for (std::size_t row = 0; row < parent.n_ket_sector_ids; ++row) {
        const std::int64_t ket_sector = parent.ket_sector_ids[row];
        for (
            std::int64_t parent_entry = parent.entry_offsets[row];
            parent_entry < parent.entry_offsets[row + 1];
            ++parent_entry
        ) {
            const std::int64_t bra_sector =
                parent.out_sector_ids[parent_entry];
            for (const OwnedBoundarySiteEntry& bra : entries) {
                if (bra.boundary_sector != bra_sector) continue;
                for (const OwnedBoundarySiteEntry& ket : entries) {
                    if (
                        ket.boundary_sector != ket_sector
                        || bra.physical_charge != ket.physical_charge
                        || bra.physical_two_j != ket.physical_two_j
                    ) {
                        continue;
                    }
                    for (
                        std::int64_t channel_position =
                            parent.channel_offsets[parent_entry];
                        channel_position <
                            parent.channel_offsets[parent_entry + 1];
                        ++channel_position
                    ) {
                        const std::int64_t channel =
                            parent.channel_ids[channel_position];
                        double coefficient =
                            reduced_environment_recoupling_coefficient(
                                left,
                                bra.physical_charge,
                                ket.physical_charge,
                                static_cast<std::int32_t>(
                                    bra.boundary_two_j
                                ),
                                static_cast<std::int32_t>(
                                    ket.boundary_two_j
                                ),
                                static_cast<std::int32_t>(
                                    bra.physical_two_j
                                ),
                                static_cast<std::int32_t>(
                                    ket.physical_two_j
                                ),
                                static_cast<std::int32_t>(
                                    bra.next_two_j
                                ),
                                static_cast<std::int32_t>(
                                    ket.next_two_j
                                ),
                                0,
                                0,
                                0,
                                0,
                                0,
                                0
                            );
                        if (std::abs(coefficient) <= 1.0e-14) {
                            continue;
                        }
                        const OwnedBoundaryOutputKey output_key{
                            ket.next_sector[0],
                            ket.next_sector[1],
                            bra.next_sector[0],
                            bra.next_sector[1],
                            channel,
                        };
                        const std::array<std::int64_t, 3> shape{
                            1,
                            bra.next_dimension,
                            ket.next_dimension,
                        };
                        const auto existing = specs.find(output_key);
                        if (
                            existing != specs.end()
                            && existing->second != shape
                        ) {
                            throw std::logic_error(
                                "Owned metric routes disagree on output shape."
                            );
                        }
                        specs.emplace(output_key, shape);
                        pending.push_back(
                            PendingRoute{
                                {
                                    channel_position,
                                    bra.block,
                                    ket.block,
                                    0,
                                    -1,
                                },
                                output_key,
                                coefficient,
                            }
                        );
                    }
                }
            }
        }
    }
    const OwnedBoundaryOutputTopology output =
        owned_boundary_output_topology(specs);
    std::vector<std::int64_t> routes;
    std::vector<double> coefficients;
    routes.reserve(5 * pending.size());
    coefficients.reserve(pending.size());
    for (PendingRoute& route : pending) {
        route.values[4] = output.output_indices.at(route.output_key);
        routes.insert(
            routes.end(),
            route.values.begin(),
            route.values.end()
        );
        coefficients.push_back(route.coefficient);
    }
    const std::array<double, 1> mpo_values{1.0};
    const std::array<std::int64_t, 2> mpo_offsets{0, 1};
    const std::array<std::int64_t, 2> mpo_shape_offsets{0, 4};
    const std::array<std::int64_t, 4> mpo_shapes{1, 1, 1, 1};
    std::uint64_t route_revision = 1469598103934665603ULL;
    for (const std::int64_t value : routes) {
        route_revision = fingerprint_word(
            route_revision,
            static_cast<std::uint64_t>(value)
        );
    }
    advance_metric_boundary_from_split_site(
        side,
        parent_bond,
        child_bond,
        left,
        site,
        routes.data(),
        pending.size(),
        coefficients.data(),
        coefficients.size(),
        mpo_values.data(),
        mpo_values.size(),
        mpo_offsets.data(),
        mpo_offsets.size(),
        mpo_shape_offsets.data(),
        mpo_shape_offsets.size(),
        mpo_shapes.data(),
        mpo_shapes.size(),
        output.offsets.data(),
        output.offsets.size(),
        output.shape_offsets.data(),
        output.shape_offsets.size(),
        output.shapes.data(),
        output.shapes.size(),
        output.labels.data(),
        output.labels.size(),
        output.revision,
        numeric_revision,
        route_revision == 0 ? 1 : route_revision
    );
    metric_boundary_actions_[action_key].parent_topology_revision =
        parent_found->second.topology_revision;
}

void MovingEnvironment::install_canonical_metric_boundary_from_split_site(
    const std::string& side,
    std::int64_t child_bond,
    std::int64_t site,
    std::uint64_t numeric_revision
) {
    const bool left = side == "left";
    if (!left && side != "right") {
        throw std::invalid_argument(
            "Canonical metric boundary side is invalid."
        );
    }
    const auto site_found = split_sites_.find(site);
    if (
        site_found == split_sites_.end()
        || !site_found->second.owns_values
    ) {
        throw std::logic_error(
            "Canonical metric boundary requires an owned split site."
        );
    }
    const PackedArena& split = site_found->second;
    if (
        split.leg_sector_offsets.size() != 4
        || split.leg_sector_labels.size()
            != 2 * split.leg_sector_dims.size()
    ) {
        throw std::logic_error(
            "Canonical metric boundary requires rank-three leg sectors."
        );
    }
    const std::size_t leg = left ? 2 : 0;
    const std::int64_t begin_raw = split.leg_sector_offsets[leg];
    const std::int64_t end_raw = split.leg_sector_offsets[leg + 1];
    if (
        begin_raw < 0
        || end_raw <= begin_raw
        || static_cast<std::size_t>(end_raw)
            > split.leg_sector_dims.size()
    ) {
        throw std::logic_error(
            "Canonical metric boundary leg sector range is invalid."
        );
    }

    OwnedBoundarySpecMap specs;
    for (std::int64_t index = begin_raw; index < end_raw; ++index) {
        const std::size_t position = static_cast<std::size_t>(index);
        const std::int64_t charge =
            split.leg_sector_labels[2 * position];
        const std::int64_t two_j =
            split.leg_sector_labels[2 * position + 1];
        const std::int64_t dimension = split.leg_sector_dims[position];
        if (dimension <= 0) {
            throw std::logic_error(
                "Canonical metric boundary has an empty reduced sector."
            );
        }
        const OwnedBoundaryOutputKey key{
            charge,
            two_j,
            charge,
            two_j,
            0,
        };
        const auto inserted = specs.emplace(
            key,
            std::array<std::int64_t, 3>{
                1,
                dimension,
                dimension,
            }
        );
        if (
            !inserted.second
            && inserted.first->second
                != std::array<std::int64_t, 3>{
                    1,
                    dimension,
                    dimension,
                }
        ) {
            throw std::logic_error(
                "Canonical metric boundary sector dimensions disagree."
            );
        }
    }
    const OwnedBoundaryOutputTopology output =
        owned_boundary_output_topology(specs);
    const std::string key = boundary_key(side, child_bond);
    PackedArena& arena = metric_boundaries_[key];
    const bool same_topology =
        arena.topology_revision == output.revision
        && arena.offsets == output.offsets
        && arena.labels == output.labels;
    if (!same_topology) {
        arena.offsets = output.offsets;
        arena.labels = output.labels;
        arena.shape_offsets = output.shape_offsets;
        arena.shapes = output.shapes;
        arena.topology_revision = output.revision;
        ++boundary_topology_builds_;
    }
    arena.owned_values.reset();
    arena.values = nullptr;
    arena.n_values = static_cast<std::size_t>(output.offsets.back());
    arena.numeric_revision = numeric_revision;
    arena.owns_values = true;
    arena.symbolic_identity = true;
    ++boundary_numeric_refreshes_;
    metric_boundary_actions_.erase(key);
}

bool MovingEnvironment::advance_normal_complementary_boundary_from_split_site(
    const std::string& side,
    std::int64_t parent_bond,
    std::int64_t child_bond,
    bool left,
    std::int64_t site,
    bool reduced_physical,
    bool dual_right_boundary,
    const std::int32_t* routes,
    std::size_t n_routes,
    const std::int64_t* output_offsets,
    std::size_t n_output_offsets,
    const std::int64_t* output_shape_offsets,
    std::size_t n_output_shape_offsets,
    const std::int64_t* output_shapes,
    std::size_t n_output_shapes,
    const std::int64_t* output_labels,
    std::size_t n_output_labels,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision,
    std::uint64_t route_topology_revision
) {
    const auto found = split_sites_.find(site);
    if (found == split_sites_.end() || !found->second.owns_values) {
        throw std::logic_error(
            "The requested packed split-site arena is not installed."
        );
    }
    const PackedArena& arena = found->second;
    ++split_site_boundary_uses_;
    const bool same_topology = advance_normal_complementary_boundary(
        side,
        parent_bond,
        child_bond,
        left,
        site,
        reduced_physical,
        dual_right_boundary,
        routes,
        n_routes,
        arena.values,
        arena.n_values,
        arena.offsets.data(),
        arena.offsets.size(),
        arena.shape_offsets.data(),
        arena.shape_offsets.size(),
        arena.shapes.data(),
        arena.shapes.size(),
        arena.values,
        arena.n_values,
        arena.offsets.data(),
        arena.offsets.size(),
        arena.shape_offsets.data(),
        arena.shape_offsets.size(),
        arena.shapes.data(),
        arena.shapes.size(),
        output_offsets,
        n_output_offsets,
        output_shape_offsets,
        n_output_shape_offsets,
        output_shapes,
        n_output_shapes,
        output_labels,
        n_output_labels,
        topology_revision,
        numeric_revision,
        route_topology_revision
    );
    normal_complementary_boundary_actions_[
        boundary_key(side, child_bond)
    ].site_topology_revision = arena.topology_revision;
    return same_topology;
}

bool MovingEnvironment::cached_normal_complementary_boundary_ready(
    const std::string& side,
    std::int64_t child_bond,
    std::int64_t site,
    std::uint64_t output_topology_revision,
    std::uint64_t route_topology_revision
) const noexcept {
    if (side != "left" && side != "right") {
        return false;
    }
    const auto action = normal_complementary_boundary_actions_.find(
        side + ":" + std::to_string(child_bond)
    );
    const auto split = split_sites_.find(site);
    return (
        action != normal_complementary_boundary_actions_.end()
        && split != split_sites_.end()
        && action->second.site == site
        && action->second.output_topology_revision
            == output_topology_revision
        && action->second.route_topology_revision
            == route_topology_revision
        && action->second.site_topology_revision
            == split->second.topology_revision
        && !action->second.routes.empty()
        && action->second.compiled
        && !action->second.mpo_offsets.empty()
        && !action->second.mpo_shape_offsets.empty()
        && !action->second.output_offsets.empty()
        && !action->second.output_shape_offsets.empty()
    );
}

bool MovingEnvironment::replay_normal_complementary_boundary_from_split_site(
    const std::string& side,
    std::int64_t child_bond,
    std::uint64_t numeric_revision
) {
    const std::string key = boundary_key(side, child_bond);
    const auto action_found =
        normal_complementary_boundary_actions_.find(key);
    if (action_found == normal_complementary_boundary_actions_.end()) {
        throw std::logic_error(
            "No cached normal/complementary boundary action is available."
        );
    }
    const NormalComplementaryBoundaryAction& action =
        action_found->second;
    const auto site_found = split_sites_.find(action.site);
    if (
        site_found == split_sites_.end()
        || !site_found->second.owns_values
        || action.site_topology_revision == 0
        || action.site_topology_revision
            != site_found->second.topology_revision
    ) {
        throw std::logic_error(
            "The cached boundary action has stale split-site topology."
        );
    }
    const PackedArena& arena = site_found->second;
    ++split_site_boundary_uses_;
    ++cached_boundary_replays_;
    return advance_normal_complementary_boundary(
        action.side,
        action.parent_bond,
        action.child_bond,
        action.left,
        action.site,
        action.reduced_physical,
        action.dual_right_boundary,
        nullptr,
        0,
        arena.values,
        arena.n_values,
        arena.offsets.data(),
        arena.offsets.size(),
        arena.shape_offsets.data(),
        arena.shape_offsets.size(),
        arena.shapes.data(),
        arena.shapes.size(),
        arena.values,
        arena.n_values,
        arena.offsets.data(),
        arena.offsets.size(),
        arena.shape_offsets.data(),
        arena.shape_offsets.size(),
        arena.shapes.data(),
        arena.shapes.size(),
        action.output_offsets.data(),
        action.output_offsets.size(),
        action.output_shape_offsets.data(),
        action.output_shape_offsets.size(),
        action.output_shapes.data(),
        action.output_shapes.size(),
        action.output_labels.data(),
        action.output_labels.size(),
        action.output_topology_revision,
        numeric_revision,
        action.route_topology_revision
    );
}

bool MovingEnvironment::advance_metric_boundary_from_split_site(
    const std::string& side,
    std::int64_t parent_bond,
    std::int64_t child_bond,
    bool left,
    std::int64_t site,
    const std::int64_t* routes,
    std::size_t n_routes,
    const double* route_coefficients,
    std::size_t n_route_coefficients,
    const double* mpo_values,
    std::size_t n_mpo_values,
    const std::int64_t* mpo_offsets,
    std::size_t n_mpo_offsets,
    const std::int64_t* mpo_shape_offsets,
    std::size_t n_mpo_shape_offsets,
    const std::int64_t* mpo_shapes,
    std::size_t n_mpo_shapes,
    const std::int64_t* output_offsets,
    std::size_t n_output_offsets,
    const std::int64_t* output_shape_offsets,
    std::size_t n_output_shape_offsets,
    const std::int64_t* output_shapes,
    std::size_t n_output_shapes,
    const std::int64_t* output_labels,
    std::size_t n_output_labels,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision,
    std::uint64_t route_topology_revision
) {
    const std::string key = boundary_key(side, child_bond);
    auto found = metric_boundary_actions_.find(key);
    const auto site_found = split_sites_.find(site);
    if (
        site_found == split_sites_.end()
        || !site_found->second.owns_values
    ) {
        throw std::logic_error(
            "Metric boundary replay requires an owned split site."
        );
    }
    const bool reuse = (
        n_routes == 0
        && found != metric_boundary_actions_.end()
        && found->second.site == site
        && found->second.route_topology_revision
            == route_topology_revision
        && found->second.output_topology_revision == topology_revision
        && found->second.site_topology_revision
            == site_found->second.topology_revision
    );
    if (!reuse) {
        if (
            routes == nullptr || n_routes == 0
            || route_coefficients == nullptr
            || n_route_coefficients != n_routes
            || mpo_values == nullptr || mpo_offsets == nullptr
            || mpo_shape_offsets == nullptr || mpo_shapes == nullptr
            || output_offsets == nullptr
            || output_shape_offsets == nullptr
            || output_shapes == nullptr || output_labels == nullptr
        ) {
            throw std::invalid_argument(
                "Metric boundary action received incomplete topology."
            );
        }
        MetricBoundaryAction& action = metric_boundary_actions_[key];
        action.side = side;
        action.parent_bond = parent_bond;
        action.child_bond = child_bond;
        action.site = site;
        action.left = left;
        action.route_topology_revision = route_topology_revision;
        action.output_topology_revision = topology_revision;
        action.site_topology_revision =
            site_found->second.topology_revision;
        action.routes.assign(routes, routes + 5 * n_routes);
        action.route_coefficients.assign(
            route_coefficients,
            route_coefficients + n_route_coefficients
        );
        action.mpo_values.assign(
            mpo_values,
            mpo_values + n_mpo_values
        );
        action.mpo_offsets.assign(
            mpo_offsets,
            mpo_offsets + n_mpo_offsets
        );
        action.mpo_shape_offsets.assign(
            mpo_shape_offsets,
            mpo_shape_offsets + n_mpo_shape_offsets
        );
        action.mpo_shapes.assign(
            mpo_shapes,
            mpo_shapes + n_mpo_shapes
        );
        action.output_offsets.assign(
            output_offsets,
            output_offsets + n_output_offsets
        );
        action.output_shape_offsets.assign(
            output_shape_offsets,
            output_shape_offsets + n_output_shape_offsets
        );
        action.output_shapes.assign(
            output_shapes,
            output_shapes + n_output_shapes
        );
        action.output_labels.assign(
            output_labels,
            output_labels + n_output_labels
        );
        found = metric_boundary_actions_.find(key);
    }
    if (found == metric_boundary_actions_.end()) {
        throw std::logic_error(
            "Metric boundary action cache insertion failed."
        );
    }
    if (reuse) {
        ++cached_boundary_replays_;
    }
    const MetricBoundaryAction& action = found->second;
    const PackedArena& arena = site_found->second;
    ++split_site_boundary_uses_;
    return advance_boundary(
        action.side,
        action.parent_bond,
        action.child_bond,
        action.left,
        action.routes.data(),
        action.routes.size() / 5,
        arena.values,
        arena.n_values,
        arena.offsets.data(),
        arena.offsets.size(),
        arena.shape_offsets.data(),
        arena.shape_offsets.size(),
        arena.shapes.data(),
        arena.shapes.size(),
        arena.values,
        arena.n_values,
        arena.offsets.data(),
        arena.offsets.size(),
        arena.shape_offsets.data(),
        arena.shape_offsets.size(),
        arena.shapes.data(),
        arena.shapes.size(),
        action.mpo_values.data(),
        action.mpo_values.size(),
        action.mpo_offsets.data(),
        action.mpo_offsets.size(),
        action.mpo_shape_offsets.data(),
        action.mpo_shape_offsets.size(),
        action.mpo_shapes.data(),
        action.mpo_shapes.size(),
        action.output_offsets.data(),
        action.output_offsets.size(),
        action.output_shape_offsets.data(),
        action.output_shape_offsets.size(),
        action.output_shapes.data(),
        action.output_shapes.size(),
        action.output_labels.data(),
        action.output_labels.size(),
        action.output_topology_revision,
        numeric_revision,
        action.route_coefficients.data(),
        true
    );
}

bool MovingEnvironment::replay_metric_boundary_from_split_site(
    const std::string& side,
    std::int64_t child_bond,
    std::uint64_t numeric_revision
) {
    const auto found = metric_boundary_actions_.find(
        boundary_key(side, child_bond)
    );
    if (found == metric_boundary_actions_.end()) {
        throw std::logic_error(
            "No cached metric boundary action is available."
        );
    }
    return advance_metric_boundary_from_split_site(
        found->second.side,
        found->second.parent_bond,
        found->second.child_bond,
        found->second.left,
        found->second.site,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        nullptr,
        0,
        found->second.output_topology_revision,
        numeric_revision,
        found->second.route_topology_revision
    );
}

std::vector<ContextualCoreBlock> MovingEnvironment::contextual_core(
    std::int64_t site,
    std::int64_t physical_output_charge,
    std::int64_t physical_input_charge,
    std::int32_t boundary_bra_two_j,
    std::int32_t boundary_ket_two_j,
    std::int32_t physical_bra_two_j,
    std::int32_t physical_ket_two_j,
    std::int32_t next_bra_two_j,
    std::int32_t next_ket_two_j,
    bool left,
    bool dual_right_basis
) const {
    std::vector<ContextualCoreBlock> transient;
    return *contextual_core_view(
        site,
        physical_output_charge,
        physical_input_charge,
        boundary_bra_two_j,
        boundary_ket_two_j,
        physical_bra_two_j,
        physical_ket_two_j,
        next_bra_two_j,
        next_ket_two_j,
        left,
        dual_right_basis,
        transient
    );
}

void MovingEnvironment::refresh_normal_complementary_numerics() {
    clear_factor_routes();
    contextual_route_plans_.clear();
    active_reduced_contextual_execution_schedule_.reset();
    contextual_action_fragments_.clear();
    contextual_action_fragment_bytes_ = 0;
    contextual_route_skeletons_.clear();
    contextual_route_skeleton_bytes_ = 0;
    std::vector<std::array<std::int64_t, 11>> keys;
    keys.reserve(
        contextual_core_cache_.size() + contextual_zero_core_cache_.size()
    );
    for (const auto& item : contextual_core_cache_) {
        keys.push_back(item.first);
    }
    for (const auto& key : contextual_zero_core_cache_) {
        keys.push_back(key);
    }
    contextual_core_cache_.clear();
    contextual_zero_core_cache_.clear();
    contextual_core_cache_elements_ = 0;
    contextual_core_cache_blocks_ = 0;
    normal_complementary_boundary_actions_.clear();
    for (const auto& key : keys) {
        std::vector<ContextualCoreBlock> transient;
        contextual_core_view(
            key[0],
            key[1],
            key[2],
            static_cast<std::int32_t>(key[3]),
            static_cast<std::int32_t>(key[4]),
            static_cast<std::int32_t>(key[5]),
            static_cast<std::int32_t>(key[6]),
            static_cast<std::int32_t>(key[7]),
            static_cast<std::int32_t>(key[8]),
            key[9] != 0,
            key[10] != 0,
            transient
        );
    }
}

const std::vector<ContextualCoreBlock>*
MovingEnvironment::contextual_core_view(
    std::int64_t site,
    std::int64_t physical_output_charge,
    std::int64_t physical_input_charge,
    std::int32_t boundary_bra_two_j,
    std::int32_t boundary_ket_two_j,
    std::int32_t physical_bra_two_j,
    std::int32_t physical_ket_two_j,
    std::int32_t next_bra_two_j,
    std::int32_t next_ket_two_j,
    bool left,
    bool dual_right_basis,
    std::vector<ContextualCoreBlock>& transient
) const {
    transient.clear();
    if (
        physical_output_charge < 0 ||
        physical_output_charge >=
            static_cast<std::int64_t>(nc_physical_charge_count) ||
        physical_input_charge < 0 ||
        physical_input_charge >=
            static_cast<std::int64_t>(nc_physical_charge_count) ||
        boundary_bra_two_j < 0 || boundary_ket_two_j < 0 ||
        physical_bra_two_j < 0 || physical_ket_two_j < 0 ||
        next_bra_two_j < 0 || next_ket_two_j < 0
    ) {
        throw std::invalid_argument(
            "Contextual normal/complementary core quantum numbers are invalid."
        );
    }
    const std::array<std::int64_t, 11> cache_key{
        site,
        physical_output_charge,
        physical_input_charge,
        static_cast<std::int64_t>(boundary_bra_two_j),
        static_cast<std::int64_t>(boundary_ket_two_j),
        static_cast<std::int64_t>(physical_bra_two_j),
        static_cast<std::int64_t>(physical_ket_two_j),
        static_cast<std::int64_t>(next_bra_two_j),
        static_cast<std::int64_t>(next_ket_two_j),
        left ? std::int64_t{1} : std::int64_t{0},
        dual_right_basis ? std::int64_t{1} : std::int64_t{0},
    };
    if (const auto* cached_core = cached_contextual_core(cache_key)) {
        return cached_core;
    }
    if (
        contextual_zero_core_cache_.find(cache_key)
        != contextual_zero_core_cache_.end()
    ) {
        ++contextual_zero_core_cache_hits_;
        return &transient;
    }
    const NormalComplementaryPlan& plan =
        system_->normal_complementary_plan(site);
    const double* primitives =
        system_->normal_complementary_primitives(site);
    const std::size_t physical_pair = static_cast<std::size_t>(
        physical_output_charge * nc_physical_charge_count
        + physical_input_charge
    );
    const auto& active_transitions =
        plan.active_transitions_by_physical_pair[physical_pair];
    const auto& transition_block_ids =
        plan.active_transition_block_ids[physical_pair];
    const auto& block_channels =
        plan.active_block_channels[physical_pair];
    if (transition_block_ids.size() != active_transitions.size()) {
        throw std::logic_error(
            "Contextual core transition template is inconsistent."
        );
    }
    transient.resize(block_channels.size());
    for (std::size_t index = 0; index < block_channels.size(); ++index) {
        ContextualCoreBlock& block = transient[index];
        block.left_channel = block_channels[index][0];
        block.right_channel = block_channels[index][1];
        const NormalComplementaryChannel& source =
            plan.left_channel_quantum_numbers[
                static_cast<std::size_t>(block.left_channel)
            ];
        const NormalComplementaryChannel& target =
            plan.right_channel_quantum_numbers[
                static_cast<std::size_t>(block.right_channel)
            ];
        block.rows = source.two_j + 1;
        block.cols = target.two_j + 1;
        block.values.assign(
            static_cast<std::size_t>(block.rows * block.cols),
            0.0
        );
    }
    for (
        std::size_t active_position = 0;
        active_position < active_transitions.size();
        ++active_position
    ) {
        const std::int64_t active_index =
            active_transitions[active_position];
        const std::size_t transition_index =
            static_cast<std::size_t>(active_index);
        const NormalComplementaryTransition& transition =
            plan.transitions[transition_index];
        const NormalComplementaryChannel& source =
            plan.left_channel_quantum_numbers[
                static_cast<std::size_t>(transition.source)
            ];
        const NormalComplementaryChannel& target =
            plan.right_channel_quantum_numbers[
                static_cast<std::size_t>(transition.target)
            ];
        const std::int32_t operator_two_j =
            local_operator_two_j(transition.local_operator);
        const std::int32_t block_id =
            transition_block_ids[active_position];
        if (
            block_id < 0 ||
            static_cast<std::size_t>(block_id) >= transient.size()
        ) {
            throw std::logic_error(
                "Contextual core block template is inconsistent."
            );
        }
        ContextualCoreBlock& block =
            transient[static_cast<std::size_t>(block_id)];
        const std::size_t action_start = static_cast<std::size_t>(
            plan.component_action_offsets[transition_index]
        );
        const std::size_t action_stop = static_cast<std::size_t>(
            plan.component_action_offsets[transition_index + 1]
        );
        for (
            std::size_t action_index = action_start;
            action_index < action_stop;
            ++action_index
        ) {
            const NormalComplementaryComponentAction& action =
                plan.component_actions[action_index];
            const std::int32_t local_index = action.local_two_m + 2;
            if (local_index < 0 || local_index >= 5) {
                continue;
            }
            const std::size_t primitive_index =
                (
                    (
                        static_cast<std::size_t>(physical_output_charge) *
                            nc_physical_charge_count +
                        static_cast<std::size_t>(physical_input_charge)
                    ) *
                        nc_operator_count +
                    static_cast<std::size_t>(transition.local_operator)
                ) *
                    nc_components_per_operator +
                static_cast<std::size_t>(local_index);
            double primitive = primitives[primitive_index];
            if (
                std::abs(target.charge) % 2 == 1 &&
                physical_input_charge % 2 == 1
            ) {
                primitive = -primitive;
            }
            if (primitive == 0.0) {
                continue;
            }
            const std::int32_t source_two_m =
                source.two_j - 2 * action.source_component;
            const std::int32_t target_two_m =
                target.two_j - 2 * action.target_component;
            double dual_factor = (
                target.two_j == 0 &&
                source.two_j == operator_two_j &&
                operator_two_j != 0
            ) ? -static_cast<double>(operator_two_j + 1) : 1.0;
            if (
                operator_two_j == 1 &&
                source.two_j == 1 &&
                target.two_j == 0
            ) {
                dual_factor = -1.0;
            }
            const double recoupling = cached_contextual_recoupling(
                ContextualRecouplingKey{
                    left ? 1 : 0,
                    static_cast<std::int32_t>(
                        physical_output_charge
                    ),
                    static_cast<std::int32_t>(
                        physical_input_charge
                    ),
                    boundary_bra_two_j,
                    boundary_ket_two_j,
                    physical_bra_two_j,
                    physical_ket_two_j,
                    next_bra_two_j,
                    next_ket_two_j,
                    source.two_j,
                    target.two_j,
                    operator_two_j,
                    source_two_m,
                    target_two_m,
                    action.local_two_m,
                    dual_right_basis ? 1 : 0,
                }
            );
            const double connection_metric = (
                left
                ? 1.0
                : component_basis_norm(
                    next_bra_two_j,
                    next_ket_two_j,
                    source.two_j,
                    source_two_m
                )
            );
            block.values[
                static_cast<std::size_t>(
                    action.source_component * block.cols +
                    action.target_component
                )
            ] += (
                action.coefficient *
                primitive *
                dual_factor *
                recoupling *
                connection_metric
            );
        }
    }
    transient.erase(
        std::remove_if(
            transient.begin(),
            transient.end(),
            [](const ContextualCoreBlock& block) {
                return std::none_of(
                    block.values.begin(),
                    block.values.end(),
                    [](double value) { return value != 0.0; }
                );
            }
        ),
        transient.end()
    );
    if (transient.empty()) {
        contextual_zero_core_cache_.insert(cache_key);
        return &transient;
    }
    std::size_t result_elements = 0;
    for (const ContextualCoreBlock& block : transient) {
        result_elements += block.values.size();
    }
    const std::size_t cache_budget_elements =
        contextual_core_cache_element_budget();
    const std::size_t cache_budget_blocks =
        20'000 * std::max<std::size_t>(
            1,
            cache_budget_elements / 250'000
        );
    if (
        contextual_core_cache_elements_ <= cache_budget_elements &&
        result_elements <=
            cache_budget_elements - contextual_core_cache_elements_ &&
        contextual_core_cache_blocks_ <= cache_budget_blocks &&
        transient.size() <=
            cache_budget_blocks - contextual_core_cache_blocks_
    ) {
        contextual_core_cache_elements_ += result_elements;
        contextual_core_cache_blocks_ += transient.size();
        return &contextual_core_cache_.emplace(
            cache_key,
            std::move(transient)
        ).first->second;
    }
    return &transient;
}

const std::vector<ContextualCoreBlock>*
MovingEnvironment::cached_contextual_core(
    const std::array<std::int64_t, 11>& key
) const noexcept {
    const auto cached = contextual_core_cache_.find(key);
    if (cached == contextual_core_cache_.end()) {
        return nullptr;
    }
    ++contextual_core_cache_hits_;
    return &cached->second;
}

double MovingEnvironment::cached_contextual_recoupling(
    const ContextualRecouplingKey& key
) const {
    const auto cached = contextual_recoupling_cache_.find(key);
    if (cached != contextual_recoupling_cache_.end()) {
        ++contextual_recoupling_cache_hits_;
        return cached->second;
    }
    const double value = reduced_environment_recoupling_impl(
        key[0] != 0,
        key[1],
        key[2],
        key[3],
        key[4],
        key[5],
        key[6],
        key[7],
        key[8],
        key[9],
        key[10],
        key[11],
        key[12],
        key[13],
        key[14],
        key[15] != 0
    );
    constexpr std::size_t recoupling_cache_limit = 250'000;
    if (contextual_recoupling_cache_.size() < recoupling_cache_limit) {
        if (contextual_recoupling_cache_.empty()) {
            contextual_recoupling_cache_.reserve(32'768);
        }
        contextual_recoupling_cache_.emplace(key, value);
    }
    return value;
}

std::size_t MovingEnvironment::boundary_value_count(
    const std::string& side,
    std::int64_t bond
) const {
    const auto it = boundaries_.find(boundary_key(side, bond));
    if (it == boundaries_.end()) {
        throw std::out_of_range("Requested boundary is not installed.");
    }
    return it->second.n_values;
}

void MovingEnvironment::copy_boundary_values(
    const std::string& side,
    std::int64_t bond,
    double* output,
    std::size_t n_values
) const {
    const auto it = boundaries_.find(boundary_key(side, bond));
    if (
        it == boundaries_.end() ||
        it->second.values == nullptr ||
        output == nullptr ||
        n_values != it->second.n_values
    ) {
        throw std::invalid_argument(
            "Requested boundary output buffer is inconsistent."
        );
    }
    std::copy(
        it->second.values,
        it->second.values + it->second.n_values,
        output
    );
}

std::size_t MovingEnvironment::metric_boundary_value_count(
    const std::string& side,
    std::int64_t bond
) const {
    const auto it = metric_boundaries_.find(boundary_key(side, bond));
    if (it == metric_boundaries_.end()) {
        throw std::out_of_range(
            "Requested metric boundary is not installed."
        );
    }
    return it->second.n_values;
}

namespace {

std::shared_ptr<std::vector<double>> materialize_symbolic_identity(
    const PackedArena& arena
) {
    if (!arena.symbolic_identity) {
        return arena.owned_values;
    }
    auto values = std::make_shared<std::vector<double>>(
        arena.n_values,
        0.0
    );
    if (
        arena.offsets.size() != arena.shape_offsets.size()
        || arena.offsets.empty()
    ) {
        throw std::logic_error(
            "Symbolic metric identity topology is inconsistent."
        );
    }
    for (std::size_t block = 0; block + 1 < arena.offsets.size(); ++block) {
        const std::int64_t shape_start = arena.shape_offsets[block];
        const std::int64_t shape_stop = arena.shape_offsets[block + 1];
        const std::int64_t value_start = arena.offsets[block];
        const std::int64_t value_stop = arena.offsets[block + 1];
        if (
            shape_start < 0
            || shape_stop - shape_start != 3
            || static_cast<std::size_t>(shape_stop) > arena.shapes.size()
            || value_start < 0
            || value_stop < value_start
            || static_cast<std::size_t>(value_stop) > arena.n_values
        ) {
            throw std::logic_error(
                "Symbolic metric identity block is inconsistent."
            );
        }
        const std::int64_t components = arena.shapes[shape_start];
        const std::int64_t rows = arena.shapes[shape_start + 1];
        const std::int64_t cols = arena.shapes[shape_start + 2];
        if (
            components != 1
            || rows <= 0
            || rows != cols
            || value_stop - value_start != rows * cols
        ) {
            throw std::logic_error(
                "Symbolic metric block is not an identity matrix."
            );
        }
        for (std::int64_t index = 0; index < rows; ++index) {
            (*values)[static_cast<std::size_t>(
                value_start + index * cols + index
            )] = 1.0;
        }
    }
    return values;
}

}  // namespace

void MovingEnvironment::copy_metric_boundary_values(
    const std::string& side,
    std::int64_t bond,
    double* output,
    std::size_t n_values
) const {
    const auto it = metric_boundaries_.find(boundary_key(side, bond));
    if (
        it == metric_boundaries_.end()
        || output == nullptr
        || n_values != it->second.n_values
        || (
            !it->second.symbolic_identity
            && it->second.values == nullptr
        )
    ) {
        throw std::invalid_argument(
            "Requested metric boundary output buffer is inconsistent."
        );
    }
    if (it->second.symbolic_identity) {
        const auto values = materialize_symbolic_identity(it->second);
        std::copy(values->begin(), values->end(), output);
    } else {
        std::copy(
            it->second.values,
            it->second.values + it->second.n_values,
            output
        );
    }
}

BoundaryBufferHandle* MovingEnvironment::retain_boundary_buffer(
    const std::string& side,
    std::int64_t bond
) const {
    const auto it = boundaries_.find(boundary_key(side, bond));
    if (
        it == boundaries_.end() ||
        !it->second.owns_values ||
        !it->second.owned_values
    ) {
        throw std::invalid_argument(
            "Requested boundary does not own a numerical buffer."
        );
    }
    return new BoundaryBufferHandle{it->second.owned_values};
}

BoundaryBufferHandle* MovingEnvironment::retain_metric_boundary_buffer(
    const std::string& side,
    std::int64_t bond
) const {
    const auto it = metric_boundaries_.find(boundary_key(side, bond));
    if (
        it == metric_boundaries_.end()
        || !it->second.owns_values
        || (
            !it->second.symbolic_identity
            && !it->second.owned_values
        )
    ) {
        throw std::invalid_argument(
            "Requested metric boundary does not own a numerical buffer."
        );
    }
    return new BoundaryBufferHandle{
        materialize_symbolic_identity(it->second)
    };
}

ComplexBoundaryBufferHandle* MovingEnvironment::retain_complex_boundary_buffer(
    const std::string& side,
    std::int64_t bond,
    bool metric_boundary
) const {
    const auto& store = metric_boundary
        ? complex_metric_boundaries_
        : complex_boundaries_;
    const auto it = store.find(boundary_key(side, bond));
    if (it == store.end() || !it->second.owned_values) {
        throw std::invalid_argument(
            "Requested complex boundary does not own a numerical buffer."
        );
    }
    return new ComplexBoundaryBufferHandle{it->second.owned_values};
}

bool MovingEnvironment::install_local_operator(
    const std::string& key,
    const Complex* values,
    std::size_t n_values,
    const std::int64_t* value_offsets,
    const std::int64_t* rows,
    const std::int64_t* cols,
    const std::int64_t* input_starts,
    const std::int64_t* output_starts,
    std::size_t n_blocks,
    std::size_t dimension,
    std::uint64_t topology_revision,
    std::uint64_t numeric_revision
) {
    if (key.empty() || dimension == 0) {
        throw std::invalid_argument("Local operator key and dimension are required.");
    }
    if (
        values == nullptr || value_offsets == nullptr || rows == nullptr ||
        cols == nullptr || input_starts == nullptr || output_starts == nullptr
    ) {
        throw std::invalid_argument("Local operator received a null buffer.");
    }
    if (value_offsets[0] != 0 ||
        static_cast<std::size_t>(value_offsets[n_blocks]) != n_values) {
        throw std::invalid_argument("Local block offsets do not cover the arena.");
    }
    const bool same_topology =
        key == local_key_ &&
        dimension == local_dimension_ &&
        topology_revision == local_topology_revision_ &&
        n_blocks == local_blocks_.size();
    if (!same_topology) {
        local_blocks_.resize(n_blocks);
        local_key_ = key;
        local_dimension_ = dimension;
        local_topology_revision_ = topology_revision;
        ++local_topology_builds_;
    }
    for (std::size_t block = 0; block < n_blocks; ++block) {
        const std::int64_t nrows = rows[block];
        const std::int64_t ncols = cols[block];
        const std::int64_t start = value_offsets[block];
        const std::int64_t stop = value_offsets[block + 1];
        if (
            nrows < 0 || ncols < 0 || start < 0 || stop < start ||
            stop - start != nrows * ncols ||
            input_starts[block] < 0 || output_starts[block] < 0 ||
            input_starts[block] + ncols > static_cast<std::int64_t>(dimension) ||
            output_starts[block] + nrows > static_cast<std::int64_t>(dimension)
        ) {
            throw std::invalid_argument("Local block metadata is inconsistent.");
        }
        local_blocks_[block] = {
            values + start,
            nrows,
            ncols,
            input_starts[block],
            output_starts[block],
        };
    }
    local_borrowed_elements_ = n_values;
    peak_borrowed_local_operator_bytes_ = std::max(
        peak_borrowed_local_operator_bytes_,
        borrowed_local_operator_bytes()
    );
    local_numeric_revision_ = numeric_revision;
    ++local_numeric_refreshes_;
    return same_topology;
}

void MovingEnvironment::clear_local_operator() {
    local_key_.clear();
    local_blocks_.clear();
    local_dimension_ = 0;
    local_borrowed_elements_ = 0;
    local_topology_revision_ = 0;
    local_numeric_revision_ = 0;
}

void MovingEnvironment::require_local_key(
    const std::string& key,
    std::size_t dimension
) const {
    if (key != local_key_ || dimension != local_dimension_) {
        throw std::invalid_argument("Requested local operator is not installed.");
    }
}

void MovingEnvironment::local_matvec(
    const std::string& key,
    const Complex* input,
    Complex* output,
    std::size_t dimension
) {
    require_local_key(key, dimension);
    if (input == nullptr || output == nullptr) {
        throw std::invalid_argument("Local matvec received a null vector.");
    }
    std::fill(output, output + dimension, Complex{0.0, 0.0});
    for (const LocalBlock& block : local_blocks_) {
        for (std::int64_t row = 0; row < block.rows; ++row) {
            Complex value = 0.0;
            const Complex* matrix_row = block.values + row * block.cols;
            for (std::int64_t col = 0; col < block.cols; ++col) {
                value += matrix_row[col] * input[block.input_start + col];
            }
            output[block.output_start + row] += value;
        }
    }
    ++local_matvec_calls_;
}

void MovingEnvironment::local_diagonal(
    const std::string& key,
    Complex* output,
    std::size_t dimension
) const {
    require_local_key(key, dimension);
    if (output == nullptr) {
        throw std::invalid_argument("Local diagonal received a null vector.");
    }
    std::fill(output, output + dimension, Complex{0.0, 0.0});
    for (const LocalBlock& block : local_blocks_) {
        const std::int64_t first =
            std::max(block.input_start, block.output_start);
        const std::int64_t last = std::min(
            block.input_start + block.cols,
            block.output_start + block.rows
        );
        for (std::int64_t global = first; global < last; ++global) {
            output[global] += block.values[
                (global - block.output_start) * block.cols
                + global - block.input_start
            ];
        }
    }
}

pyqed::dmrg::DavidsonResult MovingEnvironment::local_davidson(
    const std::string& key,
    const Complex* diagonal,
    const Complex* guess,
    std::size_t dimension,
    double tolerance,
    int max_iterations,
    int restart_dimension,
    bool accept_unconverged
) {
    require_local_key(key, dimension);
    if (diagonal == nullptr || guess == nullptr) {
        throw std::invalid_argument("Local Davidson received a null vector.");
    }
    generalized_davidson_workspace_ =
        pyqed::dmrg::GeneralizedDavidsonWorkspace{};
    real_generalized_davidson_workspace_ =
        pyqed::dmrg::RealGeneralizedDavidsonWorkspace{};
    std::vector<Complex> diagonal_vector(diagonal, diagonal + dimension);
    std::vector<Complex> guess_vector(guess, guess + dimension);
    auto result = pyqed::dmrg::davidson(
        diagonal_vector,
        std::move(guess_vector),
        tolerance,
        max_iterations,
        restart_dimension,
        accept_unconverged,
        davidson_workspace_,
        [this, &key, dimension](const std::vector<Complex>& input) {
            std::vector<Complex> output(dimension);
            local_matvec(key, input.data(), output.data(), dimension);
            return output;
        }
    );
    ++local_davidson_calls_;
    if (result.workspace_reused) {
        ++local_davidson_workspace_reuses_;
    }
    return result;
}

void MovingEnvironment::clear_raw_factor_source(RawFactorSource& source) {
    source = RawFactorSource{};
}

std::size_t MovingEnvironment::raw_factor_source_bytes(
    const RawFactorSource& source
) noexcept {
    return (source.n_boundary_data + source.n_w_data) * sizeof(double);
}

std::int64_t MovingEnvironment::raw_boundary_id(
    const RawFactorSource& source,
    std::size_t factor
) {
    if (factor >= source.n_factors) {
        throw std::out_of_range("Raw boundary factor index is out of range.");
    }
    return source.compact_contextual
        ? static_cast<std::int64_t>(source.compact_boundary_ids[factor])
        : source.boundary_ids[factor];
}

std::int64_t MovingEnvironment::raw_w_id(
    const RawFactorSource& source,
    std::size_t factor
) {
    if (factor >= source.n_factors) {
        throw std::out_of_range("Raw core factor index is out of range.");
    }
    return source.compact_contextual
        ? static_cast<std::int64_t>(source.compact_w_ids[factor])
        : source.w_ids[factor];
}

std::int64_t MovingEnvironment::raw_w_offset(
    const RawFactorSource& source,
    std::size_t w_id
) {
    if (w_id > source.n_w_arrays) {
        throw std::out_of_range("Raw core offset index is out of range.");
    }
    return source.compact_contextual
        ? static_cast<std::int64_t>(source.compact_w_offsets[w_id])
        : source.w_offsets[w_id];
}

std::array<std::int64_t, 4> MovingEnvironment::raw_w_shape(
    const RawFactorSource& source,
    std::size_t w_id
) {
    if (w_id >= source.n_w_arrays) {
        throw std::out_of_range("Raw core shape index is out of range.");
    }
    if (source.compact_contextual) {
        return {
            static_cast<std::int64_t>(source.compact_w_rows[w_id]),
            static_cast<std::int64_t>(source.compact_w_cols[w_id]),
            1,
            1,
        };
    }
    const std::int64_t shape_start = source.w_shape_offsets[w_id];
    const std::int64_t shape_stop = source.w_shape_offsets[w_id + 1];
    if (
        shape_start < 0 || shape_stop - shape_start != 4 ||
        static_cast<std::size_t>(shape_stop) > source.n_w_shape_values
    ) {
        throw std::invalid_argument("Raw core shape metadata is invalid.");
    }
    return {
        source.w_shapes[shape_start],
        source.w_shapes[shape_start + 1],
        source.w_shapes[shape_start + 2],
        source.w_shapes[shape_start + 3],
    };
}

std::array<std::int64_t, 5> MovingEnvironment::raw_factor_shape(
    const RawFactorSource& source,
    std::int64_t factor,
    bool left
) const {
    if (
        factor < 0 || static_cast<std::size_t>(factor) >= source.n_factors
    ) {
        throw std::out_of_range("Raw factor index is out of range.");
    }
    const std::int64_t boundary_id = raw_boundary_id(
        source,
        static_cast<std::size_t>(factor)
    );
    const std::int64_t w_id = raw_w_id(
        source,
        static_cast<std::size_t>(factor)
    );
    if (
        boundary_id < 0 || w_id < 0 ||
        static_cast<std::size_t>(boundary_id) >= source.n_boundary_arrays ||
        static_cast<std::size_t>(w_id) >= source.n_w_arrays
    ) {
        throw std::out_of_range("Raw factor source id is out of range.");
    }
    const std::int64_t boundary_shape =
        source.boundary_shape_offsets[boundary_id];
    const std::int64_t boundary_shape_stop =
        source.boundary_shape_offsets[boundary_id + 1];
    if (
        boundary_shape < 0 ||
        boundary_shape_stop - boundary_shape != 3 ||
        static_cast<std::size_t>(boundary_shape_stop)
            > source.n_boundary_shape_values
    ) {
        std::ostringstream message;
        message
            << "Raw factor source shape metadata is invalid for factor "
            << factor << " (" << (left ? "left" : "right")
            << "): boundary id " << boundary_id << " spans "
            << boundary_shape << ':' << boundary_shape_stop
            << ", MPO id " << w_id << '.';
        throw std::invalid_argument(message.str());
    }
    const std::int64_t* boundary =
        source.boundary_shapes + boundary_shape;
    const auto w = raw_w_shape(
        source,
        static_cast<std::size_t>(w_id)
    );
    for (int axis = 0; axis < 3; ++axis) {
        if (boundary[axis] <= 0) {
            throw std::invalid_argument("Raw boundary shape is not positive.");
        }
    }
    for (int axis = 0; axis < 4; ++axis) {
        if (w[static_cast<std::size_t>(axis)] <= 0) {
            throw std::invalid_argument("Raw MPO shape is not positive.");
        }
    }
    if (left) {
        if (boundary[0] != w[0]) {
            std::ostringstream message;
            message
                << "Left raw boundary and MPO channels do not match for "
                << "factor " << factor << " (boundary " << boundary_id
                << " has " << boundary[0] << " components, core " << w_id
                << " has " << w[0] << ").";
            throw std::invalid_argument(message.str());
        }
        return {boundary[1], boundary[2], w[1], w[2], w[3]};
    }
    if (boundary[0] != w[1]) {
        std::ostringstream message;
        message
            << "Right raw boundary and MPO channels do not match for "
            << "factor " << factor << " (boundary " << boundary_id
            << " has " << boundary[0] << " components, core " << w_id
            << " has " << w[1] << ").";
        throw std::invalid_argument(message.str());
    }
    return {w[0], boundary[1], boundary[2], w[2], w[3]};
}

RawFactorView MovingEnvironment::raw_factor(
    RawFactorSource& source,
    std::int64_t factor,
    bool left
) {
    const std::size_t factor_index = static_cast<std::size_t>(factor);
    if (
        factor >= 0
        && factor_index < source.cache_valid.size()
        && source.cache_valid[factor_index]
    ) {
        ++source.cache_hits;
        ++raw_factor_cache_hits_;
        const std::int64_t start = source.cache_starts[factor_index];
        const std::int64_t size = source.cache_sizes[factor_index];
        return RawFactorView{
            source.cache_data + start,
            static_cast<std::size_t>(size),
        };
    }
    if (
        source.transient_factor == factor
        && !source.transient.empty()
    ) {
        ++source.cache_hits;
        ++raw_factor_cache_hits_;
        return RawFactorView{
            source.transient.data(),
            source.transient.size(),
        };
    }
    ++source.cache_misses;
    ++raw_factor_cache_misses_;
    const double started = wall_seconds();
    const std::int64_t boundary_id = raw_boundary_id(
        source,
        factor_index
    );
    const std::int64_t w_id = raw_w_id(source, factor_index);
    const std::int64_t boundary_shape =
        source.boundary_shape_offsets[boundary_id];
    const std::int64_t* bshape =
        source.boundary_shapes + boundary_shape;
    const auto wshape = raw_w_shape(
        source,
        static_cast<std::size_t>(w_id)
    );
    const std::int64_t boundary_start =
        source.boundary_offsets[boundary_id];
    const std::int64_t boundary_stop =
        source.boundary_offsets[boundary_id + 1];
    const std::int64_t w_start = raw_w_offset(
        source,
        static_cast<std::size_t>(w_id)
    );
    const std::int64_t w_stop = raw_w_offset(
        source,
        static_cast<std::size_t>(w_id + 1)
    );
    if (
        boundary_start < 0 || w_start < 0 ||
        boundary_stop < boundary_start || w_stop < w_start ||
        static_cast<std::size_t>(boundary_stop) > source.n_boundary_data ||
        static_cast<std::size_t>(w_stop) > source.n_w_data
    ) {
        throw std::invalid_argument("Raw factor source offsets are invalid.");
    }
    const double* boundary = source.boundary_data + boundary_start;
    const double* wdata = source.w_data + w_start;
    const auto shape = raw_factor_shape(source, factor, left);
    std::size_t elements = 1;
    for (const std::int64_t dimension : shape) {
        elements *= static_cast<std::size_t>(dimension);
    }
    const bool cacheable = (
        factor >= 0
        && factor_index < source.cache_starts.size()
        && source.cache_starts[factor_index] >= 0
    );
    double* values = nullptr;
    if (cacheable) {
        if (
            static_cast<std::size_t>(source.cache_sizes[factor_index])
            != elements
        ) {
            throw std::logic_error("Raw factor cache shape changed.");
        }
        values = source.cache_data + source.cache_starts[factor_index];
        std::fill(values, values + elements, 0.0);
    } else {
        source.transient.assign(elements, 0.0);
        values = source.transient.data();
    }
    if (left) {
        const std::int64_t xdim = bshape[0];
        const std::int64_t ldim = bshape[1];
        const std::int64_t kdim = bshape[2];
        const std::int64_t wdim = wshape[1];
        const std::int64_t adim = wshape[2];
        const std::int64_t bdim = wshape[3];
        if (
            boundary_stop - boundary_start != xdim * ldim * kdim ||
            w_stop - w_start != xdim * wdim * adim * bdim
        ) {
            throw std::invalid_argument("Left raw factor sizes are inconsistent.");
        }
#ifdef __APPLE__
        static constexpr std::size_t direct_contraction_flops = 4096;
        if (
            elements * static_cast<std::size_t>(xdim)
            <= direct_contraction_flops
        ) {
            for (std::int64_t l = 0; l < ldim; ++l)
            for (std::int64_t k = 0; k < kdim; ++k)
            for (std::int64_t w = 0; w < wdim; ++w)
            for (std::int64_t a = 0; a < adim; ++a)
            for (std::int64_t b = 0; b < bdim; ++b) {
                double value = 0.0;
                for (std::int64_t x = 0; x < xdim; ++x) {
                    value += boundary[(x * ldim + l) * kdim + k]
                        * wdata[
                            ((x * wdim + w) * adim + a) * bdim + b
                        ];
                }
                values[((((l * adim + a) * wdim + w) * kdim + k)
                    * bdim + b)] = value;
            }
        } else {
            source.build_scratch.assign(elements, 0.0);
            std::vector<double>& natural = source.build_scratch;
            cblas_dgemm(
                101,
                112,
                111,
                static_cast<int>(ldim * kdim),
                static_cast<int>(wdim * adim * bdim),
                static_cast<int>(xdim),
                1.0,
                boundary,
                static_cast<int>(ldim * kdim),
                wdata,
                static_cast<int>(wdim * adim * bdim),
                0.0,
                natural.data(),
                static_cast<int>(wdim * adim * bdim)
            );
            ++raw_factor_gemm_calls_;
            for (std::int64_t l = 0; l < ldim; ++l)
            for (std::int64_t k = 0; k < kdim; ++k)
            for (std::int64_t w = 0; w < wdim; ++w)
            for (std::int64_t a = 0; a < adim; ++a)
            for (std::int64_t b = 0; b < bdim; ++b) {
                values[((((l * adim + a) * wdim + w) * kdim + k)
                    * bdim + b)] =
                    natural[((((l * kdim + k) * wdim + w) * adim + a)
                        * bdim + b)];
            }
        }
#else
        for (std::int64_t l = 0; l < ldim; ++l)
        for (std::int64_t k = 0; k < kdim; ++k)
        for (std::int64_t w = 0; w < wdim; ++w)
        for (std::int64_t a = 0; a < adim; ++a)
        for (std::int64_t b = 0; b < bdim; ++b) {
            double value = 0.0;
            for (std::int64_t x = 0; x < xdim; ++x) {
                value += boundary[(x * ldim + l) * kdim + k]
                    * wdata[((x * wdim + w) * adim + a) * bdim + b];
            }
            values[((((l * adim + a) * wdim + w) * kdim + k)
                * bdim + b)] = value;
        }
#endif
    } else {
        const std::int64_t wdim = wshape[0];
        const std::int64_t ydim = wshape[1];
        const std::int64_t ddim = wshape[2];
        const std::int64_t cdim = wshape[3];
        const std::int64_t qdim = bshape[1];
        const std::int64_t rdim = bshape[2];
        if (
            boundary_stop - boundary_start != ydim * qdim * rdim ||
            w_stop - w_start != wdim * ydim * ddim * cdim
        ) {
            throw std::invalid_argument("Right raw factor sizes are inconsistent.");
        }
#ifdef __APPLE__
        static constexpr std::size_t direct_contraction_flops = 4096;
        if (
            elements * static_cast<std::size_t>(ydim)
            <= direct_contraction_flops
        ) {
            for (std::int64_t w = 0; w < wdim; ++w)
            for (std::int64_t q = 0; q < qdim; ++q)
            for (std::int64_t r = 0; r < rdim; ++r)
            for (std::int64_t d = 0; d < ddim; ++d)
            for (std::int64_t c = 0; c < cdim; ++c) {
                double value = 0.0;
                for (std::int64_t y = 0; y < ydim; ++y) {
                    value +=
                        wdata[((w * ydim + y) * ddim + d) * cdim + c]
                        * boundary[(y * qdim + q) * rdim + r];
                }
                values[((((w * rdim + r) * cdim + c) * ddim + d)
                    * qdim + q)] = value;
            }
        } else {
            const std::size_t natural_elements = static_cast<std::size_t>(
                qdim * rdim * ddim * cdim
            );
            source.build_scratch.resize(natural_elements);
            std::vector<double>& natural = source.build_scratch;
            for (std::int64_t w = 0; w < wdim; ++w) {
                std::fill(natural.begin(), natural.end(), 0.0);
                cblas_dgemm(
                    101,
                    112,
                    111,
                    static_cast<int>(qdim * rdim),
                    static_cast<int>(ddim * cdim),
                    static_cast<int>(ydim),
                    1.0,
                    boundary,
                    static_cast<int>(qdim * rdim),
                    wdata + static_cast<std::size_t>(
                        w * ydim * ddim * cdim
                    ),
                    static_cast<int>(ddim * cdim),
                    0.0,
                    natural.data(),
                    static_cast<int>(ddim * cdim)
                );
                ++raw_factor_gemm_calls_;
                for (std::int64_t q = 0; q < qdim; ++q)
                for (std::int64_t r = 0; r < rdim; ++r)
                for (std::int64_t d = 0; d < ddim; ++d)
                for (std::int64_t c = 0; c < cdim; ++c) {
                    values[((((w * rdim + r) * cdim + c) * ddim + d)
                        * qdim + q)] =
                        natural[
                            ((q * rdim + r) * ddim + d) * cdim + c
                        ];
                }
            }
        }
#else
        for (std::int64_t w = 0; w < wdim; ++w)
        for (std::int64_t q = 0; q < qdim; ++q)
        for (std::int64_t r = 0; r < rdim; ++r)
        for (std::int64_t d = 0; d < ddim; ++d)
        for (std::int64_t c = 0; c < cdim; ++c) {
            double value = 0.0;
            for (std::int64_t y = 0; y < ydim; ++y) {
                value += wdata[((w * ydim + y) * ddim + d) * cdim + c]
                    * boundary[(y * qdim + q) * rdim + r];
            }
            values[((((w * rdim + r) * cdim + c) * ddim + d)
                * qdim + q)] = value;
        }
#endif
    }
    const double build_seconds = wall_seconds() - started;
    source.build_seconds += build_seconds;
    raw_factor_build_seconds_ += build_seconds;
    if (!cacheable) {
        source.transient_factor = factor;
        peak_raw_factor_cache_bytes_ = std::max(
            peak_raw_factor_cache_bytes_,
            raw_factor_cache_bytes()
        );
        return RawFactorView{
            source.transient.data(),
            source.transient.size(),
        };
    }
    source.cache_valid[factor_index] = 1;
    peak_raw_factor_cache_bytes_ = std::max(
        peak_raw_factor_cache_bytes_,
        raw_factor_cache_bytes()
    );
    return RawFactorView{values, elements};
}

bool MovingEnvironment::load_direct_source_factor(
    const RawFactorSource& source,
    std::int64_t factor,
    bool left,
    std::size_t count,
    std::size_t local,
    double* target,
    bool add
) {
    if (
        target == nullptr || count == 0 || local >= count ||
        factor < 0 || static_cast<std::size_t>(factor) >= source.n_factors
    ) {
        return false;
    }
    const std::size_t factor_index = static_cast<std::size_t>(factor);
    if (
        factor_index < source.cache_starts.size()
        && source.cache_starts[factor_index] >= 0
    ) {
        return false;
    }
    const std::int64_t boundary_id = raw_boundary_id(
        source,
        factor_index
    );
    const std::int64_t w_id = raw_w_id(source, factor_index);
    const std::int64_t* boundary_shape =
        source.boundary_shapes + source.boundary_shape_offsets[boundary_id];
    const auto w_shape = raw_w_shape(
        source,
        static_cast<std::size_t>(w_id)
    );
    const double* boundary =
        source.boundary_data + source.boundary_offsets[boundary_id];
    const double* wdata = source.w_data + raw_w_offset(
        source,
        static_cast<std::size_t>(w_id)
    );
    if (left) {
        const std::int64_t xdim = boundary_shape[0];
        const std::int64_t ldim = boundary_shape[1];
        const std::int64_t kdim = boundary_shape[2];
        const std::int64_t wdim = w_shape[1];
        const std::int64_t adim = w_shape[2];
        const std::int64_t bdim = w_shape[3];
        if (xdim != w_shape[0]) {
            return false;
        }
        for (std::int64_t l = 0; l < ldim; ++l)
        for (std::int64_t a = 0; a < adim; ++a)
        for (std::int64_t w = 0; w < wdim; ++w)
        for (std::int64_t k = 0; k < kdim; ++k)
        for (std::int64_t b = 0; b < bdim; ++b) {
            const std::size_t position = static_cast<std::size_t>(
                (((((l * adim + a) * static_cast<std::int64_t>(count)
                    + static_cast<std::int64_t>(local)) * wdim + w)
                    * kdim + k) * bdim + b)
            );
            double value = 0.0;
            for (std::int64_t x = 0; x < xdim; ++x) {
                value += boundary[(x * ldim + l) * kdim + k]
                    * wdata[
                        ((x * wdim + w) * adim + a) * bdim + b
                    ];
            }
            if (add) {
                target[position] += value;
            } else {
                target[position] = value;
            }
        }
    } else {
        const std::int64_t wdim = w_shape[0];
        const std::int64_t ydim = boundary_shape[0];
        const std::int64_t qdim = boundary_shape[1];
        const std::int64_t rdim = boundary_shape[2];
        const std::int64_t ddim = w_shape[2];
        const std::int64_t cdim = w_shape[3];
        if (ydim != w_shape[1]) {
            return false;
        }
        const std::size_t base = local * static_cast<std::size_t>(
            wdim * rdim * cdim * ddim * qdim
        );
        for (std::int64_t w = 0; w < wdim; ++w)
        for (std::int64_t r = 0; r < rdim; ++r)
        for (std::int64_t c = 0; c < cdim; ++c)
        for (std::int64_t d = 0; d < ddim; ++d)
        for (std::int64_t q = 0; q < qdim; ++q) {
            const std::size_t position = base + static_cast<std::size_t>(
                ((((w * rdim + r) * cdim + c) * ddim + d) * qdim + q)
            );
            double value = 0.0;
            for (std::int64_t y = 0; y < ydim; ++y) {
                value +=
                    wdata[((w * ydim + y) * ddim + d) * cdim + c]
                    * boundary[(y * qdim + q) * rdim + r];
            }
            if (add) {
                target[position] += value;
            } else {
                target[position] = value;
            }
        }
    }
    ++direct_source_factor_loads_;
    return true;
}

bool MovingEnvironment::load_direct_source_factor_slice(
    const RawFactorSource& source,
    std::int64_t factor,
    bool left,
    std::int64_t total_w,
    std::int64_t w_offset,
    double* target,
    bool add
) {
    if (
        target == nullptr || total_w <= 0 || w_offset < 0 ||
        factor < 0 || static_cast<std::size_t>(factor) >= source.n_factors
    ) {
        return false;
    }
    const std::size_t factor_index = static_cast<std::size_t>(factor);
    if (
        factor_index < source.cache_starts.size()
        && source.cache_starts[factor_index] >= 0
    ) {
        return false;
    }
    const std::int64_t boundary_id = raw_boundary_id(
        source,
        factor_index
    );
    const std::int64_t w_id = raw_w_id(source, factor_index);
    const std::int64_t* boundary_shape =
        source.boundary_shapes + source.boundary_shape_offsets[boundary_id];
    const auto w_shape = raw_w_shape(
        source,
        static_cast<std::size_t>(w_id)
    );
    const double* boundary =
        source.boundary_data + source.boundary_offsets[boundary_id];
    const double* wdata = source.w_data + raw_w_offset(
        source,
        static_cast<std::size_t>(w_id)
    );
    if (left) {
        const std::int64_t xdim = boundary_shape[0];
        const std::int64_t ldim = boundary_shape[1];
        const std::int64_t kdim = boundary_shape[2];
        const std::int64_t wdim = w_shape[1];
        const std::int64_t adim = w_shape[2];
        const std::int64_t bdim = w_shape[3];
        if (xdim != w_shape[0] || w_offset + wdim > total_w) {
            return false;
        }
        for (std::int64_t l = 0; l < ldim; ++l)
        for (std::int64_t a = 0; a < adim; ++a)
        for (std::int64_t w = 0; w < wdim; ++w)
        for (std::int64_t k = 0; k < kdim; ++k)
        for (std::int64_t b = 0; b < bdim; ++b) {
            const std::size_t position = static_cast<std::size_t>(
                (((l * adim + a) * total_w + w_offset + w)
                    * kdim + k) * bdim + b
            );
            double value = 0.0;
            for (std::int64_t x = 0; x < xdim; ++x) {
                value += boundary[(x * ldim + l) * kdim + k]
                    * wdata[
                        ((x * wdim + w) * adim + a) * bdim + b
                    ];
            }
            if (add) {
                target[position] += value;
            } else {
                target[position] = value;
            }
        }
    } else {
        const std::int64_t wdim = w_shape[0];
        const std::int64_t ydim = boundary_shape[0];
        const std::int64_t qdim = boundary_shape[1];
        const std::int64_t rdim = boundary_shape[2];
        const std::int64_t ddim = w_shape[2];
        const std::int64_t cdim = w_shape[3];
        if (ydim != w_shape[1] || w_offset + wdim > total_w) {
            return false;
        }
        const std::size_t base = static_cast<std::size_t>(
            w_offset * rdim * cdim * ddim * qdim
        );
        for (std::int64_t w = 0; w < wdim; ++w)
        for (std::int64_t r = 0; r < rdim; ++r)
        for (std::int64_t c = 0; c < cdim; ++c)
        for (std::int64_t d = 0; d < ddim; ++d)
        for (std::int64_t q = 0; q < qdim; ++q) {
            const std::size_t position = base + static_cast<std::size_t>(
                ((((w * rdim + r) * cdim + c) * ddim + d) * qdim + q)
            );
            double value = 0.0;
            for (std::int64_t y = 0; y < ydim; ++y) {
                value +=
                    wdata[((w * ydim + y) * ddim + d) * cdim + c]
                    * boundary[(y * qdim + q) * rdim + r];
            }
            if (add) {
                target[position] += value;
            } else {
                target[position] = value;
            }
        }
    }
    ++direct_source_factor_loads_;
    return true;
}

void MovingEnvironment::apply_raw_factor_route(
    const FactorRoute& route,
    const Complex* input,
    Complex* output
) {
    const auto& left = raw_factor(
        left_raw_factor_source_,
        route.left_factor,
        true
    );
    const auto& right = raw_factor(
        right_raw_factor_source_,
        route.right_factor,
        false
    );
    const std::int64_t kb = route.k * route.b;
    const std::int64_t cr = route.c * route.r;
    const std::int64_t lwa = route.l * route.w * route.a;
    const std::int64_t la = route.l * route.a;
    const std::int64_t wrc = route.w * route.r * route.c;
    const std::int64_t dq = route.d * route.q;
    for (std::int64_t combined = 0; combined < kb; ++combined)
    for (std::int64_t c = 0; c < route.c; ++c)
    for (std::int64_t r = 0; r < route.r; ++r) {
        const Complex value = input[
            route.input_offset + (combined * route.c + c) * route.r + r
        ];
        const std::size_t target = static_cast<std::size_t>(
            (combined * route.r + r) * route.c + c
        );
        raw_input_real_[target] = value.real();
        raw_input_imag_[target] = value.imag();
    }
#ifdef __APPLE__
    cblas_dgemm(
        101, 111, 111,
        static_cast<int>(lwa),
        static_cast<int>(cr),
        static_cast<int>(kb),
        1.0,
        left.data(),
        static_cast<int>(kb),
        raw_input_real_.data(),
        static_cast<int>(cr),
        0.0,
        raw_temporary_real_.data(),
        static_cast<int>(cr)
    );
    cblas_dgemm(
        101, 111, 111,
        static_cast<int>(lwa),
        static_cast<int>(cr),
        static_cast<int>(kb),
        1.0,
        left.data(),
        static_cast<int>(kb),
        raw_input_imag_.data(),
        static_cast<int>(cr),
        0.0,
        raw_temporary_imag_.data(),
        static_cast<int>(cr)
    );
    cblas_dgemm(
        101, 111, 111,
        static_cast<int>(la),
        static_cast<int>(dq),
        static_cast<int>(wrc),
        1.0,
        raw_temporary_real_.data(),
        static_cast<int>(wrc),
        right.data(),
        static_cast<int>(dq),
        0.0,
        raw_output_real_.data(),
        static_cast<int>(dq)
    );
    cblas_dgemm(
        101, 111, 111,
        static_cast<int>(la),
        static_cast<int>(dq),
        static_cast<int>(wrc),
        1.0,
        raw_temporary_imag_.data(),
        static_cast<int>(wrc),
        right.data(),
        static_cast<int>(dq),
        0.0,
        raw_output_imag_.data(),
        static_cast<int>(dq)
    );
    raw_factor_gemm_calls_ += 4;
#else
    for (std::int64_t row = 0; row < lwa; ++row)
    for (std::int64_t col = 0; col < cr; ++col) {
        double real = 0.0;
        double imag = 0.0;
        for (std::int64_t inner = 0; inner < kb; ++inner) {
            const double factor = left[
                static_cast<std::size_t>(row * kb + inner)
            ];
            real += factor * raw_input_real_[inner * cr + col];
            imag += factor * raw_input_imag_[inner * cr + col];
        }
        raw_temporary_real_[row * cr + col] = real;
        raw_temporary_imag_[row * cr + col] = imag;
    }
    for (std::int64_t row = 0; row < la; ++row)
    for (std::int64_t col = 0; col < dq; ++col) {
        double real = 0.0;
        double imag = 0.0;
        for (std::int64_t inner = 0; inner < wrc; ++inner) {
            const double factor = right[
                static_cast<std::size_t>(inner * dq + col)
            ];
            real += factor * raw_temporary_real_[row * wrc + inner];
            imag += factor * raw_temporary_imag_[row * wrc + inner];
        }
        raw_output_real_[row * dq + col] = real;
        raw_output_imag_[row * dq + col] = imag;
    }
#endif
    for (std::int64_t index = 0; index < la * dq; ++index) {
        output[route.output_offset + index] += Complex{
            raw_output_real_[index],
            raw_output_imag_[index],
        };
    }
}

void MovingEnvironment::build_raw_route_groups() {
    fused_raw_route_groups_ = 0;
    fused_raw_routes_ = 0;
    std::vector<RawRouteGroup> scheduled;
    for (const RawRouteGroup& group : raw_route_groups_) {
        using Signature = std::vector<std::int64_t>;
        struct SignatureHash {
            std::size_t operator()(const Signature& values) const noexcept {
                std::size_t seed = values.size();
                for (const std::int64_t value : values) {
                    seed ^= std::hash<std::int64_t>{}(value)
                        + 0x9e3779b97f4a7c15ULL
                        + (seed << 6)
                        + (seed >> 2);
                }
                return seed;
            }
        };
        struct SignatureSummary {
            std::size_t primary_count = 0;
            std::size_t factor_count = 0;
        };
        struct SignatureRows {
            std::vector<std::int64_t> primary_factors;
            std::vector<RawFactorPair> factors;
        };
        auto schedule_score = [](
            const RawRouteGroup& source,
            bool transpose
        ) {
            std::unordered_map<std::int64_t, Signature> by_primary;
            by_primary.reserve(source.factors.size());
            for (const RawFactorPair& pair : source.factors) {
                by_primary[transpose ? pair.right : pair.left].push_back(
                    transpose ? pair.left : pair.right
                );
            }
            std::unordered_map<
                Signature,
                SignatureSummary,
                SignatureHash
            > rows;
            rows.reserve(by_primary.size());
            for (auto& [primary_factor, signature] : by_primary) {
                static_cast<void>(primary_factor);
                std::sort(signature.begin(), signature.end());
                SignatureSummary& row = rows[signature];
                ++row.primary_count;
                row.factor_count += signature.size();
            }
            std::size_t contractions = 0;
            std::size_t factor_loads = 0;
            std::size_t residual_factors = 0;
            for (const auto& [signature, row] : rows) {
                if (row.factor_count >= 2) {
                    ++contractions;
                    factor_loads += signature.size() + row.primary_count;
                } else {
                    residual_factors += row.factor_count;
                }
            }
            contractions += residual_factors;
            factor_loads += 2 * residual_factors;
            return std::pair<std::size_t, std::size_t>{
                contractions,
                factor_loads,
            };
        };
        auto make_schedule = [](
            const RawRouteGroup& source,
            bool transpose
        ) {
            std::unordered_map<
                std::int64_t,
                std::vector<RawFactorPair>
            > by_primary;
            by_primary.reserve(source.factors.size());
            for (const RawFactorPair& pair : source.factors) {
                by_primary[transpose ? pair.right : pair.left].push_back(pair);
            }
            std::vector<std::int64_t> primary_factors;
            primary_factors.reserve(by_primary.size());
            for (const auto& [primary_factor, factors] : by_primary) {
                static_cast<void>(factors);
                primary_factors.push_back(primary_factor);
            }
            std::sort(primary_factors.begin(), primary_factors.end());
            std::unordered_map<
                Signature,
                SignatureRows,
                SignatureHash
            > rows;
            rows.reserve(by_primary.size());
            for (const std::int64_t primary_factor : primary_factors) {
                const auto& factors = by_primary.at(primary_factor);
                Signature signature;
                signature.reserve(factors.size());
                for (const RawFactorPair& pair : factors) {
                    signature.push_back(
                        transpose ? pair.left : pair.right
                    );
                }
                std::sort(signature.begin(), signature.end());
                SignatureRows& row = rows[signature];
                row.primary_factors.push_back(primary_factor);
                row.factors.insert(
                    row.factors.end(),
                    factors.begin(),
                    factors.end()
                );
            }
            std::vector<
                std::pair<const Signature*, SignatureRows*>
            > ordered_rows;
            ordered_rows.reserve(rows.size());
            for (auto& [signature, row] : rows) {
                ordered_rows.emplace_back(&signature, &row);
            }
            std::sort(
                ordered_rows.begin(),
                ordered_rows.end(),
                [](const auto& left, const auto& right) {
                    return *left.first < *right.first;
                }
            );
            std::vector<RawRouteGroup> result;
            RawRouteGroup residual;
            residual.input_entry = source.input_entry;
            residual.output_entry = source.output_entry;
            residual.input_offset = source.input_offset;
            residual.output_offset = source.output_offset;
            residual.dims = source.dims;
            residual.diagonal = source.diagonal;
            for (const auto& entry : ordered_rows) {
                const Signature& signature = *entry.first;
                SignatureRows& row = *entry.second;
                if (row.factors.size() >= 2) {
                    RawRouteGroup fused;
                    fused.input_entry = source.input_entry;
                    fused.output_entry = source.output_entry;
                    fused.input_offset = source.input_offset;
                    fused.output_offset = source.output_offset;
                    fused.dims = source.dims;
                    fused.factors = std::move(row.factors);
                    if (transpose) {
                        fused.fused_left_factors = signature;
                        fused.fused_right_factors =
                            std::move(row.primary_factors);
                    } else {
                        fused.fused_left_factors =
                            std::move(row.primary_factors);
                        fused.fused_right_factors = signature;
                    }
                    fused.fused = true;
                    fused.diagonal = source.diagonal;
                    result.push_back(std::move(fused));
                } else {
                    residual.factors.insert(
                        residual.factors.end(),
                        row.factors.begin(),
                        row.factors.end()
                    );
                }
            }
            if (!residual.factors.empty()) {
                result.push_back(std::move(residual));
            }
            return result;
        };
        const auto row_score = schedule_score(group, false);
        const auto column_score = schedule_score(group, true);
        auto selected = make_schedule(
            group,
            column_score < row_score
        );
        for (RawRouteGroup& item : selected) {
            if (item.fused) {
                ++fused_raw_route_groups_;
                fused_raw_routes_ += item.factors.size();
            }
            scheduled.push_back(std::move(item));
        }
    }
    raw_route_groups_ = std::move(scheduled);
}

void MovingEnvironment::build_dense_pair_kernels() {
    dense_pair_kernels_.clear();
    dense_pair_executions_.clear();
    dense_pair_kernels_built_ = 0;
    dense_pair_kernel_elements_ = 0;
    dense_pair_routes_ = 0;
    dense_factor_pack_elements_ = 0;
    static constexpr std::size_t kernel_budget_elements = 4'000'000;
    static constexpr std::size_t factor_pack_budget_elements = 500'000;
    dense_factor_pack_arena_.resize(factor_pack_budget_elements);
    dense_left_factor_pack_starts_.assign(
        left_raw_factor_source_.cache_starts.size(),
        -1
    );
    dense_right_factor_pack_starts_.assign(
        right_raw_factor_source_.cache_starts.size(),
        -1
    );
    std::size_t factor_pack_elements = 0;
    struct Candidate {
        std::int64_t input_offset = 0;
        std::int64_t output_offset = 0;
        std::int64_t input_size = 0;
        std::int64_t output_size = 0;
        std::size_t route_count = 0;
        std::vector<std::size_t> groups;
    };
    using Key = std::array<std::int64_t, 4>;
    std::map<Key, Candidate> candidates;
    for (
        std::size_t group_index = 0;
        group_index < raw_route_groups_.size();
        ++group_index
    ) {
        const RawRouteGroup& group = raw_route_groups_[group_index];
        const std::int64_t input_size =
            group.dims[1] * group.dims[4]
            * group.dims[8] * group.dims[6];
        const std::int64_t output_size =
            group.dims[0] * group.dims[3]
            * group.dims[7] * group.dims[5];
        const Key key{
            group.input_offset,
            group.output_offset,
            input_size,
            output_size,
        };
        Candidate& candidate = candidates[key];
        candidate.input_offset = group.input_offset;
        candidate.output_offset = group.output_offset;
        candidate.input_size = input_size;
        candidate.output_size = output_size;
        candidate.route_count += group.factors.size();
        candidate.groups.push_back(group_index);
    }
    std::vector<Candidate*> ordered;
    for (auto& [key, candidate] : candidates) {
        const std::size_t elements = static_cast<std::size_t>(
            candidate.input_size * candidate.output_size
        );
        if (
            candidate.route_count >= 1
            && elements <= kernel_budget_elements
        ) {
            ordered.push_back(&candidate);
        }
    }
    std::sort(
        ordered.begin(),
        ordered.end(),
        [](const Candidate* left, const Candidate* right) {
            const double left_score =
                static_cast<double>(left->route_count)
                / static_cast<double>(
                    std::max<std::int64_t>(
                        1,
                        left->input_size * left->output_size
                    )
                );
            const double right_score =
                static_cast<double>(right->route_count)
                / static_cast<double>(
                    std::max<std::int64_t>(
                        1,
                        right->input_size * right->output_size
                    )
                );
            return left_score > right_score;
        }
    );
    for (Candidate* candidate : ordered) {
        const std::size_t elements = static_cast<std::size_t>(
            candidate->input_size * candidate->output_size
        );
        if (
            dense_pair_kernel_elements_ + elements
            > kernel_budget_elements
        ) {
            continue;
        }
        DensePairKernel kernel;
        kernel.input_offset = candidate->input_offset;
        kernel.output_offset = candidate->output_offset;
        kernel.input_size = candidate->input_size;
        kernel.output_size = candidate->output_size;
        kernel.values.assign(elements, 0.0);
        for (const std::size_t group_index : candidate->groups) {
            RawRouteGroup& group = raw_route_groups_[group_index];
            const std::int64_t l = group.dims[0];
            const std::int64_t k = group.dims[1];
            const std::int64_t w = group.dims[2];
            const std::int64_t a = group.dims[3];
            const std::int64_t b = group.dims[4];
            const std::int64_t q = group.dims[5];
            const std::int64_t r = group.dims[6];
            const std::int64_t d = group.dims[7];
            const std::int64_t c = group.dims[8];
            const std::int64_t kb = k * b;
            const std::int64_t cr = c * r;
            const std::int64_t la = l * a;
            const std::int64_t dq = d * q;
            const std::int64_t left_rows = la * kb;
            const std::int64_t right_cols = dq * cr;
            raw_batch_left_.resize(
                static_cast<std::size_t>(left_rows * w)
            );
            raw_batch_right_.resize(
                static_cast<std::size_t>(w * right_cols)
            );
            raw_batch_temporary_real_.assign(
                static_cast<std::size_t>(left_rows * right_cols),
                0.0
            );
            auto pack_left = [&](const auto& left, double* packed) {
                for (std::int64_t l_index = 0; l_index < l; ++l_index)
                for (std::int64_t a_index = 0; a_index < a; ++a_index)
                for (std::int64_t k_index = 0; k_index < k; ++k_index)
                for (std::int64_t b_index = 0; b_index < b; ++b_index)
                for (std::int64_t w_index = 0; w_index < w; ++w_index) {
                    const std::int64_t row =
                        ((l_index * a + a_index) * k + k_index) * b
                        + b_index;
                    packed[row * w + w_index] = left[
                        (((l_index * a + a_index) * w + w_index) * k
                            + k_index) * b + b_index
                    ];
                }
            };
            auto pack_right = [&](const auto& right, double* packed) {
                for (std::int64_t w_index = 0; w_index < w; ++w_index)
                for (std::int64_t d_index = 0; d_index < d; ++d_index)
                for (std::int64_t q_index = 0; q_index < q; ++q_index)
                for (std::int64_t c_index = 0; c_index < c; ++c_index)
                for (std::int64_t r_index = 0; r_index < r; ++r_index) {
                    const std::int64_t column =
                        (d_index * q + q_index) * cr + c_index * r
                        + r_index;
                    packed[w_index * right_cols + column] = right[
                        (((w_index * r + r_index) * c + c_index) * d
                            + d_index) * q + q_index
                    ];
                }
            };
            auto accumulate_packed = [&](
                const double* packed_left,
                const double* packed_right
            ) {
#ifdef __APPLE__
                cblas_dgemm(
                    101, 111, 111,
                    static_cast<int>(left_rows),
                    static_cast<int>(right_cols),
                    static_cast<int>(w),
                    1.0,
                    packed_left,
                    static_cast<int>(w),
                    packed_right,
                    static_cast<int>(right_cols),
                    1.0,
                    raw_batch_temporary_real_.data(),
                    static_cast<int>(right_cols)
                );
                ++raw_factor_gemm_calls_;
#else
                for (std::int64_t row = 0; row < left_rows; ++row)
                for (std::int64_t column = 0; column < right_cols; ++column)
                for (std::int64_t w_index = 0; w_index < w; ++w_index) {
                    raw_batch_temporary_real_[row * right_cols + column] +=
                        packed_left[row * w + w_index]
                        * packed_right[w_index * right_cols + column];
                }
#endif
            };
            if (group.fused) {
                raw_input_real_.assign(
                    static_cast<std::size_t>(l * a * w * k * b),
                    0.0
                );
                raw_output_real_.assign(
                    static_cast<std::size_t>(w * r * c * d * q),
                    0.0
                );
                for (
                    const std::int64_t factor :
                    group.fused_left_factors
                ) {
                    const auto& left = raw_factor(
                        left_raw_factor_source_,
                        factor,
                        true
                    );
                    for (
                        std::size_t position = 0;
                        position < raw_input_real_.size();
                        ++position
                    ) {
                        raw_input_real_[position] += left[position];
                    }
                }
                for (
                    const std::int64_t factor :
                    group.fused_right_factors
                ) {
                    const auto& right = raw_factor(
                        right_raw_factor_source_,
                        factor,
                        false
                    );
                    for (
                        std::size_t position = 0;
                        position < raw_output_real_.size();
                        ++position
                    ) {
                        raw_output_real_[position] += right[position];
                    }
                }
                pack_left(
                    raw_input_real_,
                    raw_batch_left_.data()
                );
                pack_right(
                    raw_output_real_,
                    raw_batch_right_.data()
                );
                accumulate_packed(
                    raw_batch_left_.data(),
                    raw_batch_right_.data()
                );
            } else {
                for (const RawFactorPair& pair : group.factors) {
                    const double* packed_left = nullptr;
                    const std::size_t left_elements =
                        static_cast<std::size_t>(left_rows * w);
                    if (
                        pair.left >= 0
                        && static_cast<std::size_t>(pair.left)
                            < dense_left_factor_pack_starts_.size()
                    ) {
                        std::int64_t& start =
                            dense_left_factor_pack_starts_[
                                static_cast<std::size_t>(pair.left)
                            ];
                        if (start < 0 && (
                            factor_pack_elements + left_elements
                            <= factor_pack_budget_elements
                        )) {
                            start = static_cast<std::int64_t>(
                                factor_pack_elements
                            );
                            factor_pack_elements += left_elements;
                            const auto left = raw_factor(
                                left_raw_factor_source_,
                                pair.left,
                                true
                            );
                            pack_left(
                                left,
                                dense_factor_pack_arena_.data() + start
                            );
                            ++dense_factor_pack_builds_;
                        } else if (start >= 0) {
                            ++dense_factor_pack_reuses_;
                        }
                        if (start >= 0) {
                            packed_left =
                                dense_factor_pack_arena_.data() + start;
                        }
                    }
                    if (packed_left == nullptr) {
                        const auto left = raw_factor(
                            left_raw_factor_source_,
                            pair.left,
                            true
                        );
                        pack_left(left, raw_batch_left_.data());
                        packed_left = raw_batch_left_.data();
                    }

                    const double* packed_right = nullptr;
                    const std::size_t right_elements =
                        static_cast<std::size_t>(w * right_cols);
                    if (
                        pair.right >= 0
                        && static_cast<std::size_t>(pair.right)
                            < dense_right_factor_pack_starts_.size()
                    ) {
                        std::int64_t& start =
                            dense_right_factor_pack_starts_[
                                static_cast<std::size_t>(pair.right)
                            ];
                        if (start < 0 && (
                            factor_pack_elements + right_elements
                            <= factor_pack_budget_elements
                        )) {
                            start = static_cast<std::int64_t>(
                                factor_pack_elements
                            );
                            factor_pack_elements += right_elements;
                            const auto right = raw_factor(
                                right_raw_factor_source_,
                                pair.right,
                                false
                            );
                            pack_right(
                                right,
                                dense_factor_pack_arena_.data() + start
                            );
                            ++dense_factor_pack_builds_;
                        } else if (start >= 0) {
                            ++dense_factor_pack_reuses_;
                        }
                        if (start >= 0) {
                            packed_right =
                                dense_factor_pack_arena_.data() + start;
                        }
                    }
                    if (packed_right == nullptr) {
                        const auto right = raw_factor(
                            right_raw_factor_source_,
                            pair.right,
                            false
                        );
                        pack_right(right, raw_batch_right_.data());
                        packed_right = raw_batch_right_.data();
                    }
                    accumulate_packed(packed_left, packed_right);
                }
            }
            for (std::int64_t la_index = 0; la_index < la; ++la_index)
            for (std::int64_t kb_index = 0; kb_index < kb; ++kb_index)
            for (std::int64_t dq_index = 0; dq_index < dq; ++dq_index)
            for (std::int64_t cr_index = 0; cr_index < cr; ++cr_index) {
                kernel.values[
                    (la_index * dq + dq_index) * kernel.input_size
                    + kb_index * cr + cr_index
                ] += raw_batch_temporary_real_[
                    (la_index * kb + kb_index) * right_cols
                    + dq_index * cr + cr_index
                ];
            }
        }
        const std::int64_t kernel_index =
            static_cast<std::int64_t>(dense_pair_kernels_.size());
        for (const std::size_t group_index : candidate->groups) {
            raw_route_groups_[group_index].dense_pair = kernel_index;
        }
        dense_pair_kernel_elements_ += elements;
        dense_pair_routes_ += candidate->route_count;
        dense_pair_kernels_.push_back(std::move(kernel));
    }
    dense_factor_pack_elements_ = factor_pack_elements;
    build_dense_pair_executions();
}

void MovingEnvironment::build_dense_pair_executions() {
    using Key = std::array<std::int64_t, 2>;
    std::map<Key, std::vector<std::size_t>> by_input;
    std::map<Key, std::vector<std::size_t>> by_output;
    for (
        std::size_t index = 0;
        index < dense_pair_kernels_.size();
        ++index
    ) {
        const DensePairKernel& kernel = dense_pair_kernels_[index];
        by_input[
            Key{kernel.input_offset, kernel.input_size}
        ].push_back(index);
        by_output[
            Key{kernel.output_offset, kernel.output_size}
        ].push_back(index);
    }
    const bool shared_input = by_input.size() <= by_output.size();
    const auto& groups = shared_input ? by_input : by_output;
    dense_pair_executions_.clear();
    dense_pair_executions_.reserve(groups.size());
    for (const auto& [key, indices] : groups) {
        DensePairExecution execution;
        execution.shared_input = shared_input;
        execution.common_offset = key[0];
        execution.common_size = key[1];
        execution.offsets.reserve(indices.size());
        execution.sizes.reserve(indices.size());
        std::int64_t combined_size = 0;
        for (const std::size_t index : indices) {
            const DensePairKernel& kernel = dense_pair_kernels_[index];
            execution.offsets.push_back(
                shared_input
                ? kernel.output_offset
                : kernel.input_offset
            );
            execution.sizes.push_back(
                shared_input
                ? kernel.output_size
                : kernel.input_size
            );
            combined_size += execution.sizes.back();
        }
        execution.rows = shared_input ? combined_size : key[1];
        execution.cols = shared_input ? key[1] : combined_size;
        if (indices.size() == 1) {
            DensePairKernel& kernel =
                dense_pair_kernels_[indices.front()];
            execution.values = std::move(kernel.values);
            dense_pair_executions_.push_back(std::move(execution));
            continue;
        }
        execution.values.resize(
            static_cast<std::size_t>(
                execution.rows * execution.cols
            )
        );
        if (shared_input) {
            std::size_t target = 0;
            for (const std::size_t index : indices) {
                auto& values = dense_pair_kernels_[index].values;
                std::copy(
                    values.begin(),
                    values.end(),
                    execution.values.begin() +
                        static_cast<std::ptrdiff_t>(target)
                );
                target += values.size();
                std::vector<double>().swap(values);
            }
        } else {
            std::int64_t column_offset = 0;
            for (const std::size_t index : indices) {
                DensePairKernel& kernel = dense_pair_kernels_[index];
                for (
                    std::int64_t row = 0;
                    row < execution.rows;
                    ++row
                ) {
                    std::copy(
                        kernel.values.begin() +
                            static_cast<std::ptrdiff_t>(
                                row * kernel.input_size
                            ),
                        kernel.values.begin() +
                            static_cast<std::ptrdiff_t>(
                                (row + 1) * kernel.input_size
                            ),
                        execution.values.begin() +
                            static_cast<std::ptrdiff_t>(
                                row * execution.cols + column_offset
                            )
                    );
                }
                column_offset += kernel.input_size;
                std::vector<double>().swap(kernel.values);
            }
        }
        dense_pair_executions_.push_back(std::move(execution));
    }
    dense_pair_kernels_built_ = dense_pair_kernels_.size();
    std::vector<DensePairKernel>().swap(dense_pair_kernels_);
}

void MovingEnvironment::build_fused_factor_aggregates() {
    static constexpr std::size_t aggregate_budget_elements = 2'000'000;
    struct Candidate {
        RawRouteGroup* group = nullptr;
        std::size_t elements = 0;
        std::size_t saved_loads = 0;
    };
    std::vector<Candidate> candidates;
    for (RawRouteGroup& group : raw_route_groups_) {
        if (!group.fused || group.dense_pair >= 0) {
            continue;
        }
        const std::size_t left_elements = static_cast<std::size_t>(
            group.dims[0] * group.dims[2] * group.dims[3]
            * group.dims[1] * group.dims[4]
        );
        const std::size_t right_elements = static_cast<std::size_t>(
            group.dims[2] * group.dims[6] * group.dims[8]
            * group.dims[7] * group.dims[5]
        );
        const std::size_t elements = left_elements + right_elements;
        const std::size_t saved_loads =
            (
                group.fused_left_factors.size() > 1
                ? (group.fused_left_factors.size() - 1) * left_elements
                : 0
            )
            + (
                group.fused_right_factors.size() > 1
                ? (group.fused_right_factors.size() - 1) * right_elements
                : 0
            );
        candidates.push_back(Candidate{&group, elements, saved_loads});
    }
    std::sort(
        candidates.begin(),
        candidates.end(),
        [](const Candidate& left, const Candidate& right) {
            const long double left_score =
                static_cast<long double>(left.saved_loads)
                / static_cast<long double>(std::max<std::size_t>(1, left.elements));
            const long double right_score =
                static_cast<long double>(right.saved_loads)
                / static_cast<long double>(std::max<std::size_t>(1, right.elements));
            if (left_score != right_score) {
                return left_score > right_score;
            }
            if (left.saved_loads != right.saved_loads) {
                return left.saved_loads > right.saved_loads;
            }
            return left.elements < right.elements;
        }
    );
    std::size_t used_elements = 0;
    for (const Candidate& candidate : candidates) {
        if (
            candidate.elements == 0
            || used_elements + candidate.elements > aggregate_budget_elements
        ) {
            continue;
        }
        RawRouteGroup& group = *candidate.group;
        const std::size_t left_elements = static_cast<std::size_t>(
            group.dims[0] * group.dims[2] * group.dims[3]
            * group.dims[1] * group.dims[4]
        );
        const std::size_t right_elements = candidate.elements - left_elements;
        group.fused_left_values.assign(left_elements, 0.0);
        group.fused_right_values.assign(right_elements, 0.0);
        for (const std::int64_t factor : group.fused_left_factors) {
            const auto& values = raw_factor(
                left_raw_factor_source_,
                factor,
                true
            );
            for (std::size_t index = 0; index < left_elements; ++index) {
                group.fused_left_values[index] += values[index];
            }
        }
        for (const std::int64_t factor : group.fused_right_factors) {
            const auto& values = raw_factor(
                right_raw_factor_source_,
                factor,
                false
            );
            for (std::size_t index = 0; index < right_elements; ++index) {
                group.fused_right_values[index] += values[index];
            }
        }
        used_elements += candidate.elements;
    }
}

void MovingEnvironment::build_raw_execution_groups() {
    raw_execution_groups_.clear();
    raw_execution_action_arena_.clear();
    raw_pointer_action_arena_.clear();
    raw_combined_left_terms_.clear();
    raw_execution_actions_ = 0;
    right_grouped_execution_actions_ = 0;
    using Key = std::array<std::int64_t, 10>;
    std::unordered_map<Key, std::size_t, IntegerArrayHash<10>> lookup;
    if (!complementary_local_actions_.empty()) {
        struct ComplementaryScheduleAction {
            std::uint32_t start = 0;
            std::uint32_t stop = 0;
            std::vector<std::uint32_t> combined_left_terms;
            bool right_grouped = false;
        };
        const auto scheduled_actions = [this](
            const ComplementaryLocalAction& action
        ) {
            std::vector<ComplementaryScheduleAction> rows;
            std::vector<std::int32_t> columns;
            const std::size_t term_count =
                action.term_stop - action.term_start;
            rows.reserve(term_count);
            columns.reserve(std::min<std::size_t>(term_count, 16));
            std::size_t start = action.term_start;
            while (start < action.term_stop) {
                std::size_t stop = start + 1;
                while (
                    stop < action.term_stop
                    && complementary_local_terms_[stop].left_matrix
                        == complementary_local_terms_[start].left_matrix
                ) {
                    ++stop;
                }
                rows.push_back(ComplementaryScheduleAction{
                    static_cast<std::uint32_t>(start),
                    static_cast<std::uint32_t>(stop),
                });
                for (std::size_t term = start; term < stop; ++term) {
                    const std::int32_t right_matrix =
                        complementary_local_terms_[term].right_matrix;
                    if (
                        std::find(
                            columns.begin(),
                            columns.end(),
                            right_matrix
                        ) == columns.end()
                    ) {
                        columns.push_back(right_matrix);
                    }
                }
                start = stop;
            }
            if (
                compare_shared_left_actions()
                || compare_shared_right_panels()
                || rows.size() <= columns.size()
            ) {
                return rows;
            }
            std::sort(columns.begin(), columns.end());
            std::vector<ComplementaryScheduleAction> result(
                columns.size()
            );
            for (std::size_t term = action.term_start;
                 term < action.term_stop;
                 ++term) {
                const auto column = std::lower_bound(
                    columns.begin(),
                    columns.end(),
                    complementary_local_terms_[term].right_matrix
                );
                result[static_cast<std::size_t>(column - columns.begin())]
                    .combined_left_terms.push_back(
                        static_cast<std::uint32_t>(term)
                    );
            }
            for (ComplementaryScheduleAction& scheduled : result) {
                const std::uint32_t first =
                    scheduled.combined_left_terms.front();
                scheduled.start = first;
                scheduled.stop = first + 1;
                scheduled.right_grouped = true;
            }
            return result;
        };
        lookup.reserve(complementary_local_actions_.size());
        const auto execution_key = [](
            const ComplementaryLocalAction& action
        ) {
            return Key{
                action.input_offset,
                action.output_offset,
                action.dims[0],
                action.dims[1],
                action.dims[3],
                action.dims[4],
                action.dims[5],
                action.dims[6],
                action.dims[7],
                action.dims[8],
            };
        };
        std::vector<std::vector<ComplementaryScheduleAction>>
            scheduled_by_action;
        scheduled_by_action.reserve(complementary_local_actions_.size());
        std::vector<std::uint32_t> execution_by_action;
        execution_by_action.reserve(complementary_local_actions_.size());
        for (
            std::size_t action_index = 0;
            action_index < complementary_local_actions_.size();
            ++action_index
        ) {
            const ComplementaryLocalAction& action =
                complementary_local_actions_[action_index];
            if (
                action_index >
                static_cast<std::size_t>(
                    std::numeric_limits<std::uint32_t>::max()
                )
            ) {
                throw std::overflow_error(
                    "Complementary local action index is too large."
                );
            }
            const Key key = execution_key(action);
            auto found = lookup.find(key);
            std::size_t execution_index = 0;
            if (found == lookup.end()) {
                execution_index = raw_execution_groups_.size();
                lookup.emplace(key, execution_index);
                RawExecutionGroup execution;
                execution.input_offset = action.input_offset;
                execution.output_offset = action.output_offset;
                execution.dims = {
                    action.dims[0],
                    action.dims[1],
                    action.dims[3],
                    action.dims[4],
                    action.dims[5],
                    action.dims[6],
                    action.dims[7],
                    action.dims[8],
                };
                raw_execution_groups_.push_back(std::move(execution));
            } else {
                execution_index = found->second;
            }
            if (
                execution_index >
                    static_cast<std::size_t>(
                        std::numeric_limits<std::uint32_t>::max()
                    )
            ) {
                throw std::overflow_error(
                    "Complementary execution group index is too large."
                );
            }
            execution_by_action.push_back(
                static_cast<std::uint32_t>(execution_index)
            );
            scheduled_by_action.push_back(scheduled_actions(action));
            const std::size_t count = scheduled_by_action.back().size();
            RawExecutionGroup& execution =
                raw_execution_groups_[execution_index];
            if (
                count >
                    static_cast<std::size_t>(
                        std::numeric_limits<std::uint32_t>::max()
                    ) - execution.action_stop
                || raw_execution_actions_ >
                    std::numeric_limits<std::uint32_t>::max() - count
            ) {
                throw std::overflow_error(
                    "Complementary execution arena exceeds uint32 storage."
                );
            }
            execution.action_stop += static_cast<std::uint32_t>(count);
            raw_execution_actions_ += count;
        }
        std::uint32_t cursor = 0;
        std::vector<std::uint32_t> positions;
        positions.reserve(raw_execution_groups_.size());
        for (RawExecutionGroup& execution : raw_execution_groups_) {
            const std::uint32_t count = execution.action_stop;
            execution.action_start = cursor;
            execution.action_stop = cursor + count;
            positions.push_back(cursor);
            cursor += count;
        }
        raw_execution_action_arena_.resize(raw_execution_actions_);
        for (
            std::size_t action_index = 0;
            action_index < complementary_local_actions_.size();
            ++action_index
        ) {
            std::uint32_t& position = positions[
                execution_by_action[action_index]
            ];
            for (const ComplementaryScheduleAction& scheduled :
                 scheduled_by_action[action_index]) {
                if (scheduled.start > static_cast<std::uint32_t>(
                    std::numeric_limits<std::int32_t>::max()
                )) {
                    throw std::overflow_error(
                        "Complementary term index exceeds int32 storage."
                    );
                }
                std::uint32_t combined_start = 0;
                std::uint32_t combined_stop = 0;
                if (!scheduled.combined_left_terms.empty()) {
                    if (
                        raw_combined_left_terms_.size()
                            > std::numeric_limits<std::uint32_t>::max()
                        || scheduled.combined_left_terms.size()
                            > std::numeric_limits<std::uint32_t>::max()
                                - raw_combined_left_terms_.size()
                    ) {
                        throw std::overflow_error(
                            "Combined complementary-left arena is too large."
                        );
                    }
                    combined_start = static_cast<std::uint32_t>(
                        raw_combined_left_terms_.size()
                    );
                    for (const std::uint32_t term :
                         scheduled.combined_left_terms) {
                        raw_combined_left_terms_.push_back(
                            term
                        );
                    }
                    combined_stop = static_cast<std::uint32_t>(
                        raw_combined_left_terms_.size()
                    );
                }
                raw_execution_action_arena_[position++] =
                    RawExecutionAction{
                        static_cast<std::uint32_t>(action_index),
                        static_cast<std::int32_t>(scheduled.start),
                        scheduled.stop,
                        combined_start,
                        combined_stop,
                        scheduled.right_grouped,
                    };
                right_grouped_execution_actions_ +=
                    scheduled.right_grouped;
            }
        }
        for (const RawExecutionGroup& execution : raw_execution_groups_) {
            std::stable_sort(
                raw_execution_action_arena_.begin() + execution.action_start,
                raw_execution_action_arena_.begin() + execution.action_stop,
                [this](
                    const RawExecutionAction& first,
                    const RawExecutionAction& second
                ) {
                    const auto key = [this](
                        const RawExecutionAction& action
                    ) {
                        const ComplementaryLocalAction& local =
                            complementary_local_actions_.at(action.group);
                        const ComplementaryLocalTerm& term =
                            complementary_local_terms_.at(
                                static_cast<std::size_t>(action.factor)
                            );
                        return std::array<std::int64_t, 4>{
                            term.left_matrix,
                            local.dims[2],
                            action.group,
                            action.factor,
                        };
                    };
                    return key(first) < key(second);
                }
            );
        }
        raw_pointer_action_arena_ = raw_execution_action_arena_;
        build_raw_input_superchannels();
        peak_raw_execution_groups_ = std::max(
            peak_raw_execution_groups_,
            raw_execution_groups_.size()
        );
        peak_raw_execution_actions_ = std::max(
            peak_raw_execution_actions_,
            raw_execution_actions_
        );
        peak_right_grouped_execution_actions_ = std::max(
            peak_right_grouped_execution_actions_,
            right_grouped_execution_actions_
        );
        peak_raw_input_superchannel_batches_ = std::max(
            peak_raw_input_superchannel_batches_,
            raw_input_superchannel_batches_
        );
        return;
    }
    lookup.reserve(raw_route_groups_.size());
    const auto execution_key = [](const RawRouteGroup& group) {
        return Key{
            group.input_offset,
            group.output_offset,
            group.dims[0],
            group.dims[1],
            group.dims[3],
            group.dims[4],
            group.dims[5],
            group.dims[6],
            group.dims[7],
            group.dims[8],
        };
    };
    for (
        std::size_t group_index = 0;
        group_index < raw_route_groups_.size();
        ++group_index
    ) {
        const RawRouteGroup& group = raw_route_groups_[group_index];
        if (group.dense_pair >= 0) {
            continue;
        }
        if (group_index > std::numeric_limits<std::uint32_t>::max()) {
            throw std::overflow_error("Raw execution group index is too large.");
        }
        const Key key = execution_key(group);
        const auto found = lookup.find(key);
        std::size_t execution_index = 0;
        if (found == lookup.end()) {
            execution_index = raw_execution_groups_.size();
            lookup.emplace(key, execution_index);
            RawExecutionGroup execution;
            execution.input_offset = group.input_offset;
            execution.output_offset = group.output_offset;
            execution.dims = {
                group.dims[0],
                group.dims[1],
                group.dims[3],
                group.dims[4],
                group.dims[5],
                group.dims[6],
                group.dims[7],
                group.dims[8],
            };
            raw_execution_groups_.push_back(std::move(execution));
        } else {
            execution_index = found->second;
        }
        RawExecutionGroup& execution =
            raw_execution_groups_[execution_index];
        if (
            group.factors.size()
            > static_cast<std::size_t>(
                std::numeric_limits<std::int32_t>::max()
            )
        ) {
            throw std::overflow_error("Raw factor group is too large.");
        }
        std::size_t count = 0;
        if (group.reduced_contextual) {
            std::int32_t previous_left =
                std::numeric_limits<std::int32_t>::min();
            for (const RawFactorPair& pair : group.factors) {
                if (count == 0 || pair.left != previous_left) {
                    ++count;
                    previous_left = pair.left;
                }
            }
        } else {
            count = group.fused ? 1 : group.factors.size();
        }
        if (
            count >
                static_cast<std::size_t>(
                    std::numeric_limits<std::uint32_t>::max()
                ) - execution.action_stop
            || raw_execution_actions_ >
                std::numeric_limits<std::uint32_t>::max() - count
        ) {
            throw std::overflow_error(
                "Raw execution action arena exceeds uint32 storage."
            );
        }
        execution.action_stop += static_cast<std::uint32_t>(count);
        raw_execution_actions_ += count;
    }
    std::uint32_t cursor = 0;
    std::vector<std::uint32_t> positions;
    positions.reserve(raw_execution_groups_.size());
    for (RawExecutionGroup& execution : raw_execution_groups_) {
        const std::uint32_t count = execution.action_stop;
        execution.action_start = cursor;
        execution.action_stop = cursor + count;
        positions.push_back(cursor);
        cursor += count;
    }
    raw_execution_action_arena_.resize(raw_execution_actions_);
    for (
        std::size_t group_index = 0;
        group_index < raw_route_groups_.size();
        ++group_index
    ) {
        const RawRouteGroup& group = raw_route_groups_[group_index];
        if (group.dense_pair >= 0) {
            continue;
        }
        const auto found = lookup.find(execution_key(group));
        if (found == lookup.end()) {
            throw std::logic_error(
                "Raw execution group disappeared during arena assembly."
            );
        }
        std::uint32_t& position = positions[found->second];
        if (group.reduced_contextual) {
            std::size_t start = 0;
            while (start < group.factors.size()) {
                std::size_t stop = start + 1;
                while (
                    stop < group.factors.size() &&
                    group.factors[stop].left ==
                        group.factors[start].left
                ) {
                    ++stop;
                }
                raw_execution_action_arena_[position++] =
                    RawExecutionAction{
                        static_cast<std::uint32_t>(group_index),
                        static_cast<std::int32_t>(start),
                        static_cast<std::uint32_t>(stop),
                    };
                start = stop;
            }
            continue;
        }
        if (group.fused) {
            raw_execution_action_arena_[position++] =
                RawExecutionAction{
                    static_cast<std::uint32_t>(group_index),
                    -1,
                    0,
                };
            continue;
        }
        for (
            std::size_t factor_index = 0;
            factor_index < group.factors.size();
            ++factor_index
        ) {
            raw_execution_action_arena_[position++] =
                RawExecutionAction{
                    static_cast<std::uint32_t>(group_index),
                    static_cast<std::int32_t>(factor_index),
                    static_cast<std::uint32_t>(factor_index + 1),
                };
        }
    }
    raw_pointer_action_arena_ = raw_execution_action_arena_;
    for (const RawExecutionGroup& execution : raw_execution_groups_) {
        std::stable_sort(
            raw_pointer_action_arena_.begin() + execution.action_start,
            raw_pointer_action_arena_.begin() + execution.action_stop,
            [this](
                const RawExecutionAction& first,
                const RawExecutionAction& second
            ) {
                const auto key = [this](
                    const RawExecutionAction& action
                ) {
                    if (action.factor < 0) {
                        return std::array<std::int64_t, 4>{
                            std::numeric_limits<std::int32_t>::max(),
                            std::numeric_limits<std::int32_t>::max(),
                            action.group,
                            -1,
                        };
                    }
                    const RawFactorPair& pair = raw_route_groups_[
                        action.group
                    ].factors[
                        static_cast<std::size_t>(action.factor)
                    ];
                    return std::array<std::int64_t, 4>{
                        pair.left,
                        pair.right,
                        action.group,
                        action.factor,
                    };
                };
                return key(first) < key(second);
            }
        );
    }
    build_raw_input_superchannels();
    peak_raw_execution_groups_ = std::max(
        peak_raw_execution_groups_,
        raw_execution_groups_.size()
    );
    peak_raw_execution_actions_ = std::max(
        peak_raw_execution_actions_,
        raw_execution_actions_
    );
    peak_raw_input_superchannel_batches_ = std::max(
        peak_raw_input_superchannel_batches_,
        raw_input_superchannel_batches_
    );
}

void MovingEnvironment::build_raw_input_superchannels() {
    const std::size_t target_batch_elements =
        complementary_batch_target_elements();
    using Key = std::array<std::int64_t, 3>;
    std::unordered_map<Key, std::size_t, IntegerArrayHash<3>> lookup;
    lookup.reserve(raw_execution_groups_.size());
    raw_input_superchannels_.clear();
    raw_input_superchannel_tiles_ = 0;
    raw_input_superchannel_batches_ = 0;
    for (
        std::size_t execution_index = 0;
        execution_index < raw_execution_groups_.size();
        ++execution_index
    ) {
        if (
            execution_index
            > static_cast<std::size_t>(
                std::numeric_limits<std::uint32_t>::max()
            )
        ) {
            throw std::overflow_error(
                "Raw execution superchannel index is too large."
            );
        }
        const RawExecutionGroup& execution =
            raw_execution_groups_[execution_index];
        const std::int64_t la =
            execution.dims[0] * execution.dims[2];
        const std::int64_t kb =
            execution.dims[1] * execution.dims[3];
        const std::int64_t dq =
            execution.dims[6] * execution.dims[4];
        const std::int64_t cr =
            execution.dims[5] * execution.dims[7];
        const std::size_t per_w = static_cast<std::size_t>(
            la * kb + cr * dq + la * cr
        );
        const std::int64_t max_batch_w = static_cast<std::int64_t>(
            std::max<std::size_t>(
                1,
                target_batch_elements /
                    std::max<std::size_t>(1, per_w)
            )
        );
        const Key key{execution.input_offset, kb, cr};
        const std::size_t candidate = raw_input_superchannels_.size();
        auto inserted = lookup.emplace(key, candidate);
        if (inserted.second) {
            RawInputSuperchannel channel;
            channel.input_offset = execution.input_offset;
            channel.kb = kb;
            channel.cr = cr;
            raw_input_superchannels_.push_back(std::move(channel));
        }
        RawInputSuperchannel& channel =
            raw_input_superchannels_[inserted.first->second];
        std::size_t start = execution.action_start;
        while (start < execution.action_stop) {
            std::size_t stop = start;
            std::int64_t total_w = 0;
            while (stop < execution.action_stop) {
                const RawExecutionAction& scheduled =
                    raw_execution_action_arena_[stop];
                const std::int64_t next_w = (
                    complementary_local_actions_.empty()
                    ? raw_route_groups_[scheduled.group].dims[2]
                    : complementary_local_actions_[scheduled.group]
                        .dims[2]
                );
                if (
                    stop > start
                    && total_w + next_w > max_batch_w
                ) {
                    break;
                }
                total_w += next_w;
                ++stop;
            }
            channel.tiles.push_back(
                RawExecutionTile{
                    static_cast<std::uint32_t>(execution_index),
                    static_cast<std::uint32_t>(start),
                    static_cast<std::uint32_t>(stop),
                    total_w,
                    static_cast<std::size_t>(
                        la * total_w * kb +
                        total_w * cr * dq +
                        la * total_w * cr
                    ),
                }
            );
            ++raw_input_superchannel_tiles_;
            start = stop;
        }
    }
    for (
        std::size_t channel_index = 0;
        channel_index < raw_input_superchannels_.size();
        ++channel_index
    ) {
        RawInputSuperchannel& channel =
            raw_input_superchannels_[channel_index];
        std::size_t start = 0;
        while (start < channel.tiles.size()) {
            std::size_t stop = start;
            std::size_t workspace_elements = 0;
            std::int64_t total_left_rows = 0;
            std::int64_t total_w = 0;
            std::int64_t batch_dq = 0;
            std::size_t total_right_elements = 0;
            while (stop < channel.tiles.size()) {
                const RawExecutionTile& tile = channel.tiles[stop];
                if (
                    stop > start
                    && workspace_elements + tile.workspace_elements
                        > target_batch_elements
                ) {
                    break;
                }
                const RawExecutionGroup& execution =
                    raw_execution_groups_[tile.execution];
                const std::int64_t la =
                    execution.dims[0] * execution.dims[2];
                const std::int64_t dq =
                    execution.dims[6] * execution.dims[4];
                if (batch_dq == 0) {
                    batch_dq = dq;
                } else if (batch_dq != dq) {
                    batch_dq = -1;
                }
                workspace_elements += tile.workspace_elements;
                total_left_rows += la * tile.total_w;
                total_w += tile.total_w;
                total_right_elements += static_cast<std::size_t>(
                    tile.total_w * channel.cr * dq
                );
                ++stop;
            }
            if (
                start > std::numeric_limits<std::uint32_t>::max()
                || stop > std::numeric_limits<std::uint32_t>::max()
            ) {
                throw std::overflow_error(
                    "Raw execution batch tile range is too large."
                );
            }
            channel.batches.push_back(RawExecutionBatch{
                static_cast<std::uint32_t>(start),
                static_cast<std::uint32_t>(stop),
                total_left_rows,
                total_left_rows,
                total_w,
                std::max<std::int64_t>(0, batch_dq),
                total_right_elements,
                workspace_elements,
                false,
            });
            RawExecutionBatch& batch = channel.batches.back();
            if (!complementary_local_actions_.empty()) {
                std::unordered_map<
                    std::array<std::int64_t, 3>,
                    std::int64_t,
                    IntegerArrayHash<3>
                >
                    left_row_offsets;
                std::int64_t packed_left_rows = 0;
                for (
                    std::size_t tile_index = start;
                    tile_index < stop;
                    ++tile_index
                ) {
                    const RawExecutionTile& tile =
                        channel.tiles[tile_index];
                    const RawExecutionGroup& execution =
                        raw_execution_groups_[tile.execution];
                    const std::int64_t la =
                        execution.dims[0] * execution.dims[2];
                    for (
                        std::size_t action_index = tile.action_start;
                        action_index < tile.action_stop;
                        ++action_index
                    ) {
                        const RawExecutionAction& action =
                            raw_execution_action_arena_[action_index];
                        const ComplementaryLocalAction& local =
                            complementary_local_actions_.at(action.group);
                        if (
                            action.factor < 0
                            || static_cast<std::size_t>(action.factor)
                                < local.term_start
                            || static_cast<std::size_t>(action.factor)
                                >= action.factor_stop
                            || action.factor_stop > local.term_stop
                        ) {
                            throw std::logic_error(
                                "Complementary right-pack terms are invalid."
                            );
                        }
                        ++batch.direct_action_count;
                        batch.combined_left = batch.combined_left ||
                            action.combined_left_start
                                != action.combined_left_stop;
                        batch.direct_term_count +=
                            static_cast<std::size_t>(
                                action.factor_stop
                                - static_cast<std::uint32_t>(
                                    action.factor
                                )
                            );
                        const ComplementaryLocalTerm& term =
                            complementary_local_terms_.at(
                                static_cast<std::size_t>(action.factor)
                            );
                        const std::int64_t rows = la * local.dims[2];
                        const std::array<std::int64_t, 3> left_key{
                            raw_execution_action_left_key(action),
                            la,
                            local.dims[2],
                        };
                        auto found =
                            left_row_offsets.find(left_key);
                        if (found == left_row_offsets.end()) {
                            found = left_row_offsets.emplace(
                                left_key,
                                packed_left_rows
                            ).first;
                            batch.unique_left_actions.push_back(
                                static_cast<std::uint32_t>(action_index)
                            );
                            batch.unique_left_row_offsets.push_back(
                                packed_left_rows
                            );
                            packed_left_rows += rows;
                        } else {
                            const ReducedContextualMatrix& matrix =
                                reduced_contextual_left_matrices_.at(
                                    static_cast<std::size_t>(
                                        term.left_matrix
                                    )
                                );
                            if (
                                matrix.size() !=
                                static_cast<std::size_t>(
                                    rows * channel.kb
                                )
                            ) {
                                throw std::logic_error(
                                    "Shared complementary left shape changed."
                                );
                            }
                        }
                        batch.action_left_row_offsets.push_back(
                            found->second
                        );
                    }
                }
                if (shared_right_copy_budget() > 0) {
                    batch.packed_left_rows = packed_left_rows;
                    if (packed_left_rows == batch.total_left_rows) {
                        std::vector<std::uint32_t>().swap(
                            batch.unique_left_actions
                        );
                        std::vector<std::int64_t>().swap(
                            batch.unique_left_row_offsets
                        );
                        std::vector<std::int64_t>().swap(
                            batch.action_left_row_offsets
                        );
                    }
                } else {
                    // Reusing flattened left panels across changing
                    // reduced-sector actions is not exact.  The optional
                    // shared-right planner uses the complete shape key above;
                    // ordinary batches retain explicit rows.
                    batch.packed_left_rows = batch.total_left_rows;
                    std::vector<std::uint32_t>().swap(
                        batch.unique_left_actions
                    );
                    std::vector<std::int64_t>().swap(
                        batch.unique_left_row_offsets
                    );
                    std::vector<std::int64_t>().swap(
                        batch.action_left_row_offsets
                    );
                }
            }
            if (
                enable_right_first_actions()
                && !complementary_local_actions_.empty()
                && batch.dq > 0
            ) {
                long double left_work =
                    static_cast<long double>(batch.packed_left_rows)
                    * channel.kb * channel.cr;
                long double right_work =
                    static_cast<long double>(channel.kb)
                    * channel.cr * batch.total_w * batch.dq;
                std::size_t tile_index = start;
                for (; tile_index < stop; ++tile_index) {
                    const RawExecutionTile& tile =
                        channel.tiles[tile_index];
                    const RawExecutionGroup& execution =
                        raw_execution_groups_[tile.execution];
                    const std::int64_t la =
                        execution.dims[0] * execution.dims[2];
                    left_work += static_cast<long double>(la)
                        * tile.total_w * channel.cr * batch.dq;
                    right_work += static_cast<long double>(la)
                        * tile.total_w * channel.kb * batch.dq;
                }
                const long double reorder_work =
                    static_cast<long double>(batch.total_w)
                    * channel.kb * batch.dq;
                batch.right_first =
                    right_work + reorder_work * 0.25L < left_work;
                if (batch.right_first) {
                    for (
                        std::size_t tile_index = start;
                        tile_index < stop;
                        ++tile_index
                    ) {
                        channel.tiles[tile_index].direct_preferred =
                            false;
                    }
                    batch.packed_left_rows = batch.total_left_rows;
                    std::vector<std::uint32_t>().swap(
                        batch.unique_left_actions
                    );
                    std::vector<std::int64_t>().swap(
                        batch.unique_left_row_offsets
                    );
                    std::vector<std::int64_t>().swap(
                        batch.action_left_row_offsets
                    );
                }
            }
            ++raw_input_superchannel_batches_;
            start = stop;
        }
    }
    if (!complementary_local_actions_.empty()) {
        std::size_t unique_left_count = 0;
        std::size_t left_occurrence_count = 0;
        std::size_t shared_left_panel_count = 0;
        std::size_t shared_left_occurrence_count = 0;
        for (RawInputSuperchannel& channel : raw_input_superchannels_) {
            std::unordered_map<
                std::array<std::int64_t, 3>,
                std::uint16_t,
                IntegerArrayHash<3>
            > left_indices;
            std::vector<std::size_t> left_uses;
            for (RawExecutionBatch& batch : channel.batches) {
                batch.channel_left_indices.clear();
                if (batch.right_first) {
                    continue;
                }
                for (
                    std::size_t tile_index = batch.tile_start;
                    tile_index < batch.tile_stop;
                    ++tile_index
                ) {
                    const RawExecutionTile& tile =
                        channel.tiles[tile_index];
                    const RawExecutionGroup& execution =
                        raw_execution_groups_[tile.execution];
                    const std::int64_t la =
                        execution.dims[0] * execution.dims[2];
                    for (
                        std::size_t action_index = tile.action_start;
                        action_index < tile.action_stop;
                        ++action_index
                    ) {
                        const RawExecutionAction& action =
                            raw_execution_action_arena_[action_index];
                        const std::int64_t w =
                            complementary_local_actions_.at(
                                action.group
                            ).dims[2];
                        const std::array<std::int64_t, 3> key{
                            raw_execution_action_left_key(action),
                            la,
                            w,
                        };
                        auto found =
                            left_indices.find(key);
                        if (found == left_indices.end()) {
                            if (
                                channel.unique_left_rows < 0
                                || channel.unique_left_rows >
                                    std::numeric_limits<
                                        std::uint32_t
                                    >::max()
                            ) {
                                throw std::overflow_error(
                                    "Channel left row arena is too large."
                                );
                            }
                            if (
                                channel.unique_left_actions.size()
                                > std::numeric_limits<
                                    std::uint16_t
                                >::max()
                            ) {
                                throw std::overflow_error(
                                    "Channel unique-left table is too large."
                                );
                            }
                            const std::uint16_t unique_index =
                                static_cast<std::uint16_t>(
                                    channel.unique_left_actions.size()
                                );
                            found = left_indices.emplace(
                                key,
                                unique_index
                            ).first;
                            channel.unique_left_actions.push_back(
                                static_cast<std::uint32_t>(action_index)
                            );
                            channel.unique_left_row_offsets.push_back(
                                static_cast<std::uint32_t>(
                                    channel.unique_left_rows
                                )
                            );
                            left_uses.push_back(0);
                            channel.unique_left_rows +=
                                la * w;
                        }
                        ++left_uses.at(found->second);
                        batch.channel_left_indices.push_back(
                            found->second
                        );
                    }
                }
            }
            unique_left_count += left_uses.size();
            for (const std::size_t uses : left_uses) {
                left_occurrence_count += uses;
                if (uses >= 2) {
                    ++shared_left_panel_count;
                    shared_left_occurrence_count += uses;
                }
            }
        }
        peak_raw_channel_unique_left_count_ = std::max(
            peak_raw_channel_unique_left_count_,
            unique_left_count
        );
        peak_raw_channel_left_occurrence_count_ = std::max(
            peak_raw_channel_left_occurrence_count_,
            left_occurrence_count
        );
        peak_raw_shared_left_panel_count_ = std::max(
            peak_raw_shared_left_panel_count_,
            shared_left_panel_count
        );
        peak_raw_shared_left_occurrence_count_ = std::max(
            peak_raw_shared_left_occurrence_count_,
            shared_left_occurrence_count
        );
    }
    build_raw_output_fusion_waves();
    build_compact_right_panel_registry();
}

void MovingEnvironment::build_compact_right_panel_registry() {
    constexpr std::uint32_t no_panel =
        std::numeric_limits<std::uint32_t>::max();
    compact_right_panels_.clear();
    compact_right_panel_values_.clear();
    for (RawInputSuperchannel& channel : raw_input_superchannels_) {
        for (RawExecutionBatch& batch : channel.batches) {
            batch.compact_output_products.clear();
            batch.compact_output_wave_offsets.clear();
        }
    }
    const std::size_t budget = compact_right_panel_element_budget();
    if (budget == 0 || complementary_local_actions_.empty()) {
        return;
    }
    ++compact_right_panel_registry_builds_;
    struct Candidate {
        RawCompactRightPanel panel;
        std::size_t term_count = 0;
    };
    std::map<std::vector<std::int64_t>, std::uint32_t> lookup;
    std::vector<Candidate> candidates;
    std::vector<std::vector<std::uint32_t>> tile_candidates;
    tile_candidates.reserve(raw_input_superchannels_.size());
    for (const RawInputSuperchannel& channel : raw_input_superchannels_) {
        tile_candidates.emplace_back(channel.tiles.size(), no_panel);
        const std::size_t channel_index = tile_candidates.size() - 1;
        for (
            std::size_t tile_index = 0;
            tile_index < channel.tiles.size();
            ++tile_index
        ) {
            const RawExecutionTile& tile = channel.tiles[tile_index];
            if (!tile.requires_right) continue;
            const RawExecutionGroup& execution =
                raw_execution_groups_.at(tile.execution);
            const std::int64_t cols =
                execution.dims[6] * execution.dims[4];
            const std::int64_t rows = tile.total_w * channel.cr;
            std::vector<std::int64_t> key{
                rows,
                cols,
                static_cast<std::int64_t>(
                    tile.action_stop - tile.action_start
                ),
            };
            key.reserve(
                3 + 4 * (tile.action_stop - tile.action_start)
            );
            std::size_t term_count = 0;
            for (
                std::size_t action_index = tile.action_start;
                action_index < tile.action_stop;
                ++action_index
            ) {
                const RawExecutionAction& action =
                    raw_execution_action_arena_.at(action_index);
                const ComplementaryLocalAction& local =
                    complementary_local_actions_.at(action.group);
                if (
                    action.factor < 0
                    || static_cast<std::size_t>(action.factor)
                        < local.term_start
                    || static_cast<std::size_t>(action.factor)
                        >= action.factor_stop
                    || action.factor_stop > local.term_stop
                ) {
                    throw std::logic_error(
                        "Compact right-panel action range is invalid."
                    );
                }
                key.push_back(action.group);
                key.push_back(action.factor);
                key.push_back(action.factor_stop);
                key.push_back(action.right_grouped ? 1 : 0);
                term_count += static_cast<std::size_t>(
                    action.factor_stop
                    - static_cast<std::uint32_t>(action.factor)
                );
            }
            auto found = lookup.find(key);
            if (found == lookup.end()) {
                if (
                    candidates.size()
                    >= std::numeric_limits<std::uint32_t>::max()
                ) {
                    throw std::overflow_error(
                        "Compact right-panel registry is too large."
                    );
                }
                const std::uint32_t candidate =
                    static_cast<std::uint32_t>(candidates.size());
                found = lookup.emplace(std::move(key), candidate).first;
                Candidate pending;
                pending.panel.action_start = tile.action_start;
                pending.panel.action_stop = tile.action_stop;
                pending.panel.total_w = tile.total_w;
                pending.panel.rows = rows;
                pending.panel.cols = cols;
                pending.term_count = term_count;
                candidates.push_back(pending);
            }
            Candidate& candidate = candidates.at(found->second);
            if (
                candidate.panel.rows != rows
                || candidate.panel.cols != cols
                || candidate.panel.use_count
                    == std::numeric_limits<std::uint32_t>::max()
            ) {
                throw std::overflow_error(
                    "Compact right-panel occurrence count is invalid."
                );
            }
            ++candidate.panel.use_count;
            tile_candidates[channel_index][tile_index] = found->second;
        }
    }
    std::vector<std::uint32_t> order(candidates.size());
    std::iota(order.begin(), order.end(), std::uint32_t{0});
    std::stable_sort(
        order.begin(),
        order.end(),
        [&candidates](std::uint32_t left, std::uint32_t right) {
            const Candidate& a = candidates[left];
            const Candidate& b = candidates[right];
            const long double a_elements =
                static_cast<long double>(a.panel.rows)
                * static_cast<long double>(a.panel.cols);
            const long double b_elements =
                static_cast<long double>(b.panel.rows)
                * static_cast<long double>(b.panel.cols);
            const long double a_density =
                static_cast<long double>(a.panel.use_count)
                * static_cast<long double>(a.term_count)
                / a_elements;
            const long double b_density =
                static_cast<long double>(b.panel.use_count)
                * static_cast<long double>(b.term_count)
                / b_elements;
            if (a_density != b_density) return a_density > b_density;
            return a_elements < b_elements;
        }
    );
    std::size_t selected_elements = 0;
    std::vector<std::uint32_t> selected(
        candidates.size(),
        no_panel
    );
    for (const std::uint32_t candidate_index : order) {
        const Candidate& candidate = candidates[candidate_index];
        const std::size_t elements = static_cast<std::size_t>(
            candidate.panel.rows * candidate.panel.cols
        );
        if (
            elements > budget
            || selected_elements > budget - elements
        ) {
            continue;
        }
        selected[candidate_index] = static_cast<std::uint32_t>(
            compact_right_panels_.size()
        );
        compact_right_panels_.push_back(candidate.panel);
        selected_elements += elements;
    }
    for (std::vector<std::uint32_t>& channel : tile_candidates) {
        for (std::uint32_t& panel : channel) {
            panel = panel == no_panel ? no_panel : selected.at(panel);
        }
    }
    std::vector<std::uint8_t> panel_used(
        compact_right_panels_.size(),
        std::uint8_t{0}
    );
    for (
        std::size_t channel_index = 0;
        channel_index < raw_input_superchannels_.size();
        ++channel_index
    ) {
        RawInputSuperchannel& channel =
            raw_input_superchannels_[channel_index];
        for (RawExecutionBatch& batch : channel.batches) {
            if (
                batch.right_first
                || batch.tile_start == batch.tile_stop
                || batch.tile_stop - batch.tile_start
                    > compact_panel_batch_tile_limit()
            ) {
                continue;
            }
            bool has_persistent_panel = false;
            for (
                std::size_t tile_index = batch.tile_start;
                tile_index < batch.tile_stop;
                ++tile_index
            ) {
                if (
                    tile_candidates.at(channel_index).at(tile_index)
                    != no_panel
                ) {
                    has_persistent_panel = true;
                    break;
                }
            }
            if (!has_persistent_panel) continue;
            std::unordered_map<std::int64_t, std::uint32_t>
                output_occurrences;
            std::vector<std::vector<RawCompactOutputProduct>> waves;
            std::int64_t temporary_row_offset = 0;
            for (
                std::size_t tile_index = batch.tile_start;
                tile_index < batch.tile_stop;
                ++tile_index
            ) {
                const RawExecutionTile& tile = channel.tiles[tile_index];
                const RawExecutionGroup& execution =
                    raw_execution_groups_[tile.execution];
                const std::int64_t la =
                    execution.dims[0] * execution.dims[2];
                const std::uint32_t panel =
                    tile_candidates.at(channel_index).at(tile_index);
                std::uint32_t& occurrence =
                    output_occurrences[execution.output_offset];
                if (occurrence == waves.size()) waves.emplace_back();
                waves[occurrence++].push_back(
                    RawCompactOutputProduct{
                        static_cast<std::uint32_t>(tile_index),
                        panel,
                        temporary_row_offset,
                    }
                );
                if (panel != no_panel) panel_used.at(panel) = 1;
                temporary_row_offset += la * tile.total_w;
            }
            if (temporary_row_offset != batch.total_left_rows) {
                throw std::logic_error(
                    "Compact action-product batch rows changed."
                );
            }
            batch.compact_output_wave_offsets.reserve(waves.size() + 1);
            batch.compact_output_wave_offsets.push_back(0);
            for (std::vector<RawCompactOutputProduct>& wave : waves) {
                batch.compact_output_products.insert(
                    batch.compact_output_products.end(),
                    std::make_move_iterator(wave.begin()),
                    std::make_move_iterator(wave.end())
                );
                if (
                    batch.compact_output_products.size()
                    > std::numeric_limits<std::uint32_t>::max()
                ) {
                    throw std::overflow_error(
                        "Compact action-product arena is too large."
                    );
                }
                batch.compact_output_wave_offsets.push_back(
                    static_cast<std::uint32_t>(
                        batch.compact_output_products.size()
                    )
                );
            }
        }
    }
    std::vector<std::uint32_t> panel_remap(
        compact_right_panels_.size(),
        no_panel
    );
    std::vector<RawCompactRightPanel> used_panels;
    used_panels.reserve(compact_right_panels_.size());
    for (
        std::size_t panel_index = 0;
        panel_index < compact_right_panels_.size();
        ++panel_index
    ) {
        if (panel_used[panel_index] == 0) continue;
        panel_remap[panel_index] = static_cast<std::uint32_t>(
            used_panels.size()
        );
        used_panels.push_back(compact_right_panels_[panel_index]);
    }
    compact_right_panels_.swap(used_panels);
    for (RawInputSuperchannel& channel : raw_input_superchannels_) {
        for (RawExecutionBatch& batch : channel.batches) {
            for (RawCompactOutputProduct& product :
                 batch.compact_output_products) {
                if (product.panel == no_panel) continue;
                product.panel = panel_remap.at(product.panel);
                if (product.panel == no_panel) {
                    throw std::logic_error(
                        "Compact action product lost its panel."
                    );
                }
            }
        }
    }
}

void MovingEnvironment::refresh_compact_right_panels() {
    if (compact_right_panels_.empty()) return;
    ++compact_right_panel_numeric_refreshes_;
    std::size_t elements = 0;
    for (RawCompactRightPanel& panel : compact_right_panels_) {
        panel.value_offset = elements;
        elements += static_cast<std::size_t>(panel.rows * panel.cols);
    }
    if (elements > compact_right_panel_values_.capacity()) {
        std::vector<double> exact_arena(elements);
        compact_right_panel_values_.swap(exact_arena);
    } else {
        compact_right_panel_values_.resize(elements);
    }
    for (const RawCompactRightPanel& panel : compact_right_panels_) {
        double* target = compact_right_panel_values_.data()
            + panel.value_offset;
        std::int64_t w_offset = 0;
        for (
            std::size_t action_index = panel.action_start;
            action_index < panel.action_stop;
            ++action_index
        ) {
            const RawExecutionAction& action =
                raw_execution_action_arena_.at(action_index);
            pack_raw_execution_action_into(
                action,
                panel.total_w,
                w_offset,
                nullptr,
                target
            );
            w_offset += complementary_local_actions_.at(
                action.group
            ).dims[2];
        }
        if (w_offset != panel.total_w) {
            throw std::logic_error(
                "Compact right-panel refresh width changed."
            );
        }
    }
}

