void MovingEnvironment::build_raw_output_fusion_waves() {
    static constexpr std::size_t target_fusion_elements = 1'048'576;
    static constexpr std::size_t target_shared_left_elements = 262'144;
    static constexpr std::size_t target_wave_batches = 32;
    static constexpr std::size_t target_wave_bindings = 4'096;
    const std::size_t requested_output_copy_budget =
        output_fusion_copy_budget();
    const std::size_t requested_shared_right_copy_budget =
        shared_right_copy_budget();
    const std::size_t max_copy_elements_per_saved_gemm = (
        requested_shared_right_copy_budget == 0
        ? requested_output_copy_budget
        : std::min(
            requested_output_copy_budget,
            requested_shared_right_copy_budget
        )
    );
    const bool amortize_right_pack =
        amortize_output_fusion_right_pack();
    const auto profitable_fusion_elements = [
        max_copy_elements_per_saved_gemm,
        amortize_right_pack
    ](
        std::int64_t la,
        std::int64_t dq,
        std::int64_t total_k,
        std::uint32_t tile_count
    ) -> std::size_t {
        if (tile_count < 2) {
            return 0;
        }
        const std::size_t stored_elements = static_cast<std::size_t>(
            (la + dq) * total_k
        );
        const std::size_t copied_elements = static_cast<std::size_t>(
            (amortize_right_pack ? la : la + dq) * total_k
        );
        return (
            copied_elements <=
                max_copy_elements_per_saved_gemm
                * static_cast<std::size_t>(tile_count - 1)
            ? stored_elements
            : 0
        );
    };
    using BatchReference = std::array<std::uint32_t, 2>;
    raw_output_fusion_waves_.clear();
    for (RawInputSuperchannel& channel : raw_input_superchannels_) {
        for (RawExecutionTile& tile : channel.tiles) {
            tile.requires_right = true;
            tile.planned_requires_right = true;
        }
        for (RawExecutionBatch& batch : channel.batches) {
            batch.requires_right = true;
            batch.planned_requires_right = true;
            batch.planned_total_right_elements =
                batch.total_right_elements;
        }
    }
    std::size_t grouped_output_candidate_bindings = 0;
    std::array<std::uint64_t, 10>
        grouped_output_candidate_work_counts{};
    if (disable_output_fusion() || requested_output_copy_budget == 0) {
        return;
    }
    std::vector<BatchReference> references;
    references.reserve(raw_input_superchannel_batches_);
    for (
        std::size_t channel_index = 0;
        channel_index < raw_input_superchannels_.size();
        ++channel_index
    ) {
        const RawInputSuperchannel& channel =
            raw_input_superchannels_[channel_index];
        if (
            channel_index >
            static_cast<std::size_t>(
                std::numeric_limits<std::uint32_t>::max()
            )
        ) {
            throw std::overflow_error(
                "Raw output-fusion channel index is too large."
            );
        }
        for (
            std::size_t batch_index = 0;
            batch_index < channel.batches.size();
            ++batch_index
        ) {
            if (channel.batches[batch_index].right_first) {
                continue;
            }
            if (
                batch_index >
                static_cast<std::size_t>(
                    std::numeric_limits<std::uint32_t>::max()
                )
            ) {
                throw std::overflow_error(
                    "Raw output-fusion batch index is too large."
                );
            }
            references.push_back(BatchReference{
                static_cast<std::uint32_t>(channel_index),
                static_cast<std::uint32_t>(batch_index),
            });
        }
    }
    std::size_t cursor = 0;
    while (cursor < references.size()) {
        RawOutputFusionWave wave;
        std::unordered_map<std::int64_t, std::uint32_t> group_lookup;
        group_lookup.reserve(target_wave_bindings);
        std::size_t fusion_elements = 0;
        while (cursor < references.size()) {
            const BatchReference reference = references[cursor];
            const RawInputSuperchannel& channel =
                raw_input_superchannels_[reference[0]];
            const RawExecutionBatch& batch =
                channel.batches[reference[1]];
            struct PendingGroup {
                std::int64_t la = 0;
                std::int64_t dq = 0;
                std::int64_t total_k = 0;
                std::uint32_t tile_count = 0;
            };
            std::unordered_map<std::int64_t, PendingGroup> pending;
            pending.reserve(
                batch.tile_stop - batch.tile_start
            );
            for (
                std::size_t tile_index = batch.tile_start;
                tile_index < batch.tile_stop;
                ++tile_index
            ) {
                const RawExecutionTile& tile =
                    channel.tiles[tile_index];
                const RawExecutionGroup& execution =
                    raw_execution_groups_[tile.execution];
                const std::int64_t la =
                    execution.dims[0] * execution.dims[2];
                const std::int64_t dq =
                    execution.dims[6] * execution.dims[4];
                PendingGroup& addition =
                    pending[execution.output_offset];
                if (addition.tile_count == 0) {
                    addition.la = la;
                    addition.dq = dq;
                } else if (
                    addition.la != la
                    || addition.dq != dq
                ) {
                    throw std::logic_error(
                        "Raw output-fusion block shape changed."
                    );
                }
                addition.total_k += tile.total_w * channel.cr;
                ++addition.tile_count;
            }
            std::size_t candidate_elements = fusion_elements;
            for (const auto& [output_offset, addition] : pending) {
                std::int64_t old_k = 0;
                std::uint32_t old_count = 0;
                const auto found = group_lookup.find(output_offset);
                if (found != group_lookup.end()) {
                    const RawOutputFusionGroup& group =
                        wave.groups[found->second];
                    if (
                        group.la != addition.la
                        || group.dq != addition.dq
                    ) {
                        throw std::logic_error(
                            "Raw output-fusion group shape changed."
                        );
                    }
                    old_k = group.total_k;
                    old_count = group.tile_count;
                }
                const std::size_t old_elements =
                    profitable_fusion_elements(
                        addition.la,
                        addition.dq,
                        old_k,
                        old_count
                    );
                const std::int64_t next_k =
                    old_k + addition.total_k;
                const std::uint32_t next_count =
                    old_count + addition.tile_count;
                const std::size_t next_elements =
                    profitable_fusion_elements(
                        addition.la,
                        addition.dq,
                        next_k,
                        next_count
                    );
                if (next_elements >= old_elements) {
                    candidate_elements +=
                        next_elements - old_elements;
                } else {
                    candidate_elements -=
                        old_elements - next_elements;
                }
            }
            if (
                !wave.batches.empty()
                && (
                    candidate_elements > target_fusion_elements
                    || wave.batches.size() >= target_wave_batches
                    || wave.bindings.size()
                        + batch.tile_stop - batch.tile_start
                        > target_wave_bindings
                )
            ) {
                break;
            }
            if (
                wave.bindings.size()
                    + batch.tile_stop - batch.tile_start
                > static_cast<std::size_t>(
                    std::numeric_limits<std::uint32_t>::max()
                )
            ) {
                throw std::overflow_error(
                    "Raw output-fusion binding arena is too large."
                );
            }
            RawOutputFusionBatch scheduled;
            scheduled.channel = reference[0];
            scheduled.batch = reference[1];
            scheduled.binding_start =
                static_cast<std::uint32_t>(wave.bindings.size());
            std::int64_t temporary_row_offset = 0;
            std::size_t right_offset = 0;
            for (
                std::size_t tile_index = batch.tile_start;
                tile_index < batch.tile_stop;
                ++tile_index
            ) {
                const RawExecutionTile& tile =
                    channel.tiles[tile_index];
                const RawExecutionGroup& execution =
                    raw_execution_groups_[tile.execution];
                const std::int64_t la =
                    execution.dims[0] * execution.dims[2];
                const std::int64_t dq =
                    execution.dims[6] * execution.dims[4];
                const std::int64_t k =
                    tile.total_w * channel.cr;
                auto found =
                    group_lookup.find(execution.output_offset);
                if (found == group_lookup.end()) {
                    if (
                        wave.groups.size() >
                        static_cast<std::size_t>(
                            std::numeric_limits<std::uint32_t>::max()
                        )
                    ) {
                        throw std::overflow_error(
                            "Raw output-fusion group arena is too large."
                        );
                    }
                    const std::uint32_t group =
                        static_cast<std::uint32_t>(
                            wave.groups.size()
                        );
                    found = group_lookup.emplace(
                        execution.output_offset,
                        group
                    ).first;
                    RawOutputFusionGroup output_group;
                    output_group.output_offset =
                        execution.output_offset;
                    output_group.la = la;
                    output_group.dq = dq;
                    wave.groups.push_back(output_group);
                }
                RawOutputFusionGroup& output_group =
                    wave.groups[found->second];
                if (
                    output_group.la != la
                    || output_group.dq != dq
                ) {
                    throw std::logic_error(
                        "Raw output-fusion execution shape changed."
                    );
                }
                wave.bindings.push_back(RawOutputFusionBinding{
                    static_cast<std::uint32_t>(tile_index),
                    found->second,
                    temporary_row_offset,
                    right_offset,
                    output_group.total_k,
                    0,
                    0,
                });
                output_group.total_k += k;
                ++output_group.tile_count;
                temporary_row_offset += la * tile.total_w;
                right_offset += static_cast<std::size_t>(k * dq);
            }
            scheduled.binding_stop =
                static_cast<std::uint32_t>(wave.bindings.size());
            wave.batches.push_back(scheduled);
            fusion_elements = candidate_elements;
            ++cursor;
        }
        for (RawOutputFusionGroup& group : wave.groups) {
            if (
                profitable_fusion_elements(
                    group.la,
                    group.dq,
                    group.total_k,
                    group.tile_count
                ) == 0
            ) {
                continue;
            }
            group.temporary_offset = wave.temporary_elements;
            group.right_offset = wave.right_elements;
            wave.temporary_elements += static_cast<std::size_t>(
                group.la * group.total_k
            );
            wave.right_elements += static_cast<std::size_t>(
                group.total_k * group.dq
            );
        }
        if (
            !disable_shared_right_panels()
            && !complementary_local_actions_.empty()
            && shared_right_copy_budget() > 0
        ) {
            struct SharedRightReference {
                std::uint32_t binding = 0;
                std::int64_t source_k_offset = 0;
                double scale = 0.0;
                std::size_t copied_elements = 0;
            };
            struct SharedRightCandidate {
                std::int32_t right_matrix = -1;
                std::int64_t inner = 0;
                std::int64_t columns = 0;
                std::vector<SharedRightReference> references;
            };
            using SharedRightKey = std::array<std::int64_t, 3>;
            std::unordered_map<
                SharedRightKey,
                std::size_t,
                IntegerArrayHash<3>
            > panel_lookup;
            std::vector<SharedRightCandidate> candidates;
            panel_lookup.reserve(wave.bindings.size());
            candidates.reserve(wave.bindings.size());
            std::vector<std::vector<std::size_t>> binding_candidates(
                wave.bindings.size()
            );
            std::vector<bool> binding_active(
                wave.bindings.size(),
                false
            );
            for (
                const RawOutputFusionBatch& scheduled :
                wave.batches
            ) {
                const RawInputSuperchannel& channel =
                    raw_input_superchannels_.at(scheduled.channel);
                for (
                    std::size_t binding_index =
                        scheduled.binding_start;
                    binding_index < scheduled.binding_stop;
                    ++binding_index
                ) {
                    const RawOutputFusionBinding& binding =
                        wave.bindings[binding_index];
                    const RawOutputFusionGroup& output_group =
                        wave.groups.at(binding.group);
                    if (
                        output_group.temporary_offset
                            != std::numeric_limits<std::size_t>::max()
                        || binding_index >
                            static_cast<std::size_t>(
                                std::numeric_limits<std::uint32_t>::max()
                            )
                    ) {
                        continue;
                    }
                    const RawExecutionTile& tile =
                        channel.tiles.at(binding.tile);
                    bool eligible = output_group.dq > 0;
                    std::int64_t source_k_offset = 0;
                    for (
                        std::size_t action_index = tile.action_start;
                        eligible && action_index < tile.action_stop;
                        ++action_index
                    ) {
                        const RawExecutionAction& action =
                            raw_execution_action_arena_.at(
                                action_index
                            );
                        if (
                            action.factor < 0
                            || action.factor_stop !=
                                static_cast<std::uint32_t>(
                                    action.factor + 1
                                )
                        ) {
                            eligible = false;
                            break;
                        }
                        const ComplementaryLocalAction& local =
                            complementary_local_actions_.at(
                                action.group
                            );
                        const ComplementaryLocalTerm& term =
                            complementary_local_terms_.at(
                                static_cast<std::size_t>(
                                    action.factor
                                )
                            );
                        if (
                            term.right_matrix < 0
                            || static_cast<std::size_t>(
                                term.right_matrix
                            ) >=
                                reduced_contextual_right_matrices_.size()
                        ) {
                            eligible = false;
                            break;
                        }
                        const std::int64_t inner =
                            local.dims[2] * channel.cr;
                        const ReducedContextualMatrix& right =
                            reduced_contextual_right_matrices_.at(
                                static_cast<std::size_t>(
                                    term.right_matrix
                                )
                            );
                        if (
                            right.rows != inner
                            || right.cols != output_group.dq
                        ) {
                            eligible = false;
                            break;
                        }
                        const SharedRightKey key{
                            term.right_matrix,
                            inner,
                            output_group.dq,
                        };
                        auto found = panel_lookup.find(key);
                        if (found == panel_lookup.end()) {
                            const std::size_t candidate =
                                candidates.size();
                            found = panel_lookup.emplace(
                                key,
                                candidate
                            ).first;
                            SharedRightCandidate pending;
                            pending.right_matrix =
                                term.right_matrix;
                            pending.inner = inner;
                            pending.columns = output_group.dq;
                            candidates.push_back(
                                std::move(pending)
                            );
                        }
                        candidates[found->second].references.push_back(
                            SharedRightReference{
                                static_cast<std::uint32_t>(
                                    binding_index
                                ),
                                source_k_offset,
                                action.right_grouped ? 1.0 : term.scale,
                                static_cast<std::size_t>(
                                    output_group.la
                                    * (inner + output_group.dq)
                                ),
                            }
                        );
                        binding_candidates[binding_index].push_back(
                            found->second
                        );
                        source_k_offset += inner;
                    }
                    binding_active[binding_index] =
                        eligible
                        && source_k_offset
                            == tile.total_w * channel.cr;
                }
            }
            const std::size_t copy_budget =
                shared_right_copy_budget();
            const auto candidate_profitable = [
                &binding_active,
                copy_budget
            ](const SharedRightCandidate& candidate) {
                std::size_t bindings = 0;
                std::size_t copied_elements = 0;
                std::uint32_t previous =
                    std::numeric_limits<std::uint32_t>::max();
                for (
                    const SharedRightReference& reference :
                    candidate.references
                ) {
                    if (!binding_active[reference.binding]) {
                        continue;
                    }
                    copied_elements += reference.copied_elements;
                    if (reference.binding != previous) {
                        ++bindings;
                        previous = reference.binding;
                    }
                }
                return bindings >= 2
                    && copied_elements <=
                        copy_budget * (bindings - 1);
            };
            std::vector<bool> candidate_active(candidates.size(), false);
            for (
                std::size_t candidate_index = 0;
                candidate_index < candidates.size();
                ++candidate_index
            ) {
                candidate_active[candidate_index] =
                    candidate_profitable(candidates[candidate_index]);
            }
            bool changed = true;
            while (changed) {
                changed = false;
                for (
                    std::size_t binding_index = 0;
                    binding_index < binding_active.size();
                    ++binding_index
                ) {
                    if (!binding_active[binding_index]) {
                        continue;
                    }
                    for (
                        const std::size_t candidate :
                        binding_candidates[binding_index]
                    ) {
                        if (!candidate_active[candidate]) {
                            binding_active[binding_index] = false;
                            changed = true;
                            break;
                        }
                    }
                }
                for (
                    std::size_t candidate_index = 0;
                    candidate_index < candidates.size();
                    ++candidate_index
                ) {
                    if (
                        candidate_active[candidate_index]
                        && !candidate_profitable(
                            candidates[candidate_index]
                        )
                    ) {
                        candidate_active[candidate_index] = false;
                        changed = true;
                    }
                }
                // Sharing only part of an output group mixes panel products
                // with deferred per-tile products.  That representation is
                // not invariant under changing reduced-sector topologies.
                // Keep the optimization only when it owns the complete group.
                std::vector<std::size_t> active_group_bindings(
                    wave.groups.size(),
                    0
                );
                for (
                    std::size_t binding_index = 0;
                    binding_index < binding_active.size();
                    ++binding_index
                ) {
                    if (binding_active[binding_index]) {
                        ++active_group_bindings.at(
                            wave.bindings.at(binding_index).group
                        );
                    }
                }
                for (
                    std::size_t binding_index = 0;
                    binding_index < binding_active.size();
                    ++binding_index
                ) {
                    if (!binding_active[binding_index]) {
                        continue;
                    }
                    const RawOutputFusionGroup& group = wave.groups.at(
                        wave.bindings.at(binding_index).group
                    );
                    const std::size_t active = active_group_bindings.at(
                        wave.bindings.at(binding_index).group
                    );
                    if (active != group.tile_count) {
                        binding_active[binding_index] = false;
                        changed = true;
                    }
                }
            }
            const std::size_t selected_tiles = static_cast<std::size_t>(
                std::count(
                    binding_active.begin(),
                    binding_active.end(),
                    true
                )
            );
            const std::size_t selected_panels = static_cast<std::size_t>(
                std::count(
                    candidate_active.begin(),
                    candidate_active.end(),
                    true
                )
            );
            if (
                selected_tiles > selected_panels
                && selected_panels > 0
            ) {
              std::vector<std::vector<std::uint32_t>> tile_bindings(
                  wave.bindings.size()
              );
              for (
                std::size_t candidate_index = 0;
                candidate_index < candidates.size();
                ++candidate_index
              ) {
                if (!candidate_active[candidate_index]) {
                    continue;
                }
                if (
                    wave.shared_right_panels.size() >
                    static_cast<std::size_t>(
                        std::numeric_limits<std::uint32_t>::max()
                    )
                ) {
                    throw std::overflow_error(
                        "Shared-right panel arena is too large."
                    );
                }
                const SharedRightCandidate& candidate =
                    candidates[candidate_index];
                const std::uint32_t panel_index =
                    static_cast<std::uint32_t>(
                        wave.shared_right_panels.size()
                    );
                RawSharedRightPanel panel;
                panel.right_matrix = candidate.right_matrix;
                panel.inner = candidate.inner;
                panel.columns = candidate.columns;
                panel.binding_start =
                    static_cast<std::uint32_t>(
                        wave.shared_right_bindings.size()
                    );
                panel.input_offset =
                    wave.shared_right_input_elements;
                panel.output_offset =
                    wave.shared_right_output_elements;
                for (
                    const SharedRightReference& reference :
                    candidate.references
                ) {
                    if (!binding_active[reference.binding]) {
                        continue;
                    }
                    RawOutputFusionBinding& binding =
                        wave.bindings.at(reference.binding);
                    const RawOutputFusionGroup& output_group =
                        wave.groups.at(binding.group);
                    if (
                        wave.shared_right_bindings.size() >
                        static_cast<std::size_t>(
                            std::numeric_limits<std::uint32_t>::max()
                        )
                    ) {
                        throw std::overflow_error(
                            "Shared-right binding arena is too large."
                        );
                    }
                    const std::uint32_t shared_binding =
                        static_cast<std::uint32_t>(
                            wave.shared_right_bindings.size()
                        );
                    wave.shared_right_bindings.push_back(
                        RawSharedRightBinding{
                            panel_index,
                            output_group.output_offset,
                            reference.source_k_offset,
                            panel.total_rows,
                            output_group.la,
                            reference.scale,
                        }
                    );
                    tile_bindings[reference.binding].push_back(
                        shared_binding
                    );
                    panel.total_rows += output_group.la;
                }
                panel.binding_stop =
                    static_cast<std::uint32_t>(
                        wave.shared_right_bindings.size()
                    );
                wave.shared_right_input_elements +=
                    static_cast<std::size_t>(
                        panel.total_rows * panel.inner
                    );
                wave.shared_right_output_elements +=
                    static_cast<std::size_t>(
                        panel.total_rows * panel.columns
                    );
                wave.shared_right_panels.push_back(panel);
              }
              for (
                  std::size_t binding_index = 0;
                  binding_index < wave.bindings.size();
                  ++binding_index
              ) {
                  if (!binding_active[binding_index]) {
                      continue;
                  }
                  RawOutputFusionBinding& binding =
                      wave.bindings[binding_index];
                  std::vector<std::uint32_t>& ordered_bindings =
                      tile_bindings[binding_index];
                  std::sort(
                      ordered_bindings.begin(),
                      ordered_bindings.end(),
                      [&wave](
                          std::uint32_t left,
                          std::uint32_t right
                      ) {
                          return wave.shared_right_bindings.at(left)
                              .source_k_offset
                              < wave.shared_right_bindings.at(right)
                                  .source_k_offset;
                      }
                  );
                  binding.shared_right_start =
                      static_cast<std::uint32_t>(
                          wave.shared_right_tile_bindings.size()
                      );
                  wave.shared_right_tile_bindings.insert(
                      wave.shared_right_tile_bindings.end(),
                      ordered_bindings.begin(),
                      ordered_bindings.end()
                  );
                  binding.shared_right_stop =
                      static_cast<std::uint32_t>(
                          wave.shared_right_tile_bindings.size()
                      );
                  const RawOutputFusionGroup& output_group =
                      wave.groups.at(binding.group);
                  wave.shared_right_tile_output_elements = std::max(
                      wave.shared_right_tile_output_elements,
                      static_cast<std::size_t>(
                          output_group.la * output_group.dq
                      )
                  );
              }
            }
        }
        std::vector<bool> deferred_groups(wave.groups.size(), false);
        for (
            const RawOutputFusionBinding& binding : wave.bindings
        ) {
            if (
                binding.shared_right_start
                != binding.shared_right_stop
            ) {
                deferred_groups.at(binding.group) = true;
            }
        }
        if (!wave.shared_right_panels.empty()) {
            wave.shared_right_deferred_output_offsets.assign(
                wave.bindings.size(),
                std::numeric_limits<std::size_t>::max()
            );
            for (
                std::size_t binding_index = 0;
                binding_index < wave.bindings.size();
                ++binding_index
            ) {
                const RawOutputFusionBinding& binding =
                    wave.bindings[binding_index];
                if (
                    !deferred_groups.at(binding.group)
                    || binding.shared_right_start
                        != binding.shared_right_stop
                ) {
                    continue;
                }
                const RawOutputFusionGroup& output_group =
                    wave.groups.at(binding.group);
                wave.shared_right_deferred_output_offsets[
                    binding_index
                ] = wave.shared_right_deferred_output_elements;
                wave.shared_right_deferred_output_elements +=
                    static_cast<std::size_t>(
                        output_group.la * output_group.dq
                    );
            }
        }
        for (RawOutputFusionBatch& scheduled : wave.batches) {
            scheduled.singleton_outputs = true;
            for (
                std::size_t binding_index = scheduled.binding_start;
                binding_index < scheduled.binding_stop;
                ++binding_index
            ) {
                if (
                    wave.groups[wave.bindings[binding_index].group]
                        .temporary_offset
                    != std::numeric_limits<std::size_t>::max()
                ) {
                    scheduled.singleton_outputs = false;
                    break;
                }
            }
            for (
                std::size_t binding_index = scheduled.binding_start;
                binding_index < scheduled.binding_stop;
                ++binding_index
            ) {
                if (
                    wave.bindings[binding_index].shared_right_start
                    != wave.bindings[binding_index].shared_right_stop
                ) {
                    scheduled.shared_right_panels = true;
                }
                if (
                    deferred_groups.at(
                        wave.bindings[binding_index].group
                    )
                ) {
                    scheduled.deferred_outputs = true;
                }
            }
        }
        std::vector<std::uint8_t> shared_left_selected(
            wave.bindings.size(),
            std::uint8_t{0}
        );
        std::vector<std::uint8_t> persistent_product_selected(
            wave.bindings.size(),
            std::uint8_t{0}
        );
        std::size_t channel_unique_left_elements = 0;
        for (const RawInputSuperchannel& candidate_channel :
             raw_input_superchannels_) {
            channel_unique_left_elements += static_cast<std::size_t>(
                candidate_channel.unique_left_rows
                * candidate_channel.kb
            );
        }
        const bool use_channel_left_output_groups =
            group_channel_left_outputs()
            && channel_unique_left_elements
                <= complementary_execution_cache_elements();
        for (
            std::size_t scheduled_index = 0;
            scheduled_index < wave.batches.size();
        ) {
            RawOutputFusionBatch& scheduled =
                wave.batches[scheduled_index];
            const RawInputSuperchannel& channel =
                raw_input_superchannels_.at(scheduled.channel);
            const RawExecutionBatch& batch =
                channel.batches.at(scheduled.batch);
            std::size_t scheduled_stop = scheduled_index + 1;
            if (
                use_channel_left_output_groups
                && !batch.channel_left_indices.empty()
            ) {
                while (
                    scheduled_stop < wave.batches.size()
                    && wave.batches[scheduled_stop].channel
                        == scheduled.channel
                    && !channel.batches.at(
                        wave.batches[scheduled_stop].batch
                    ).channel_left_indices.empty()
                ) {
                    ++scheduled_stop;
                }
            }
            scheduled.shared_left_group_start =
                static_cast<std::uint32_t>(
                    wave.shared_left_groups.size()
                );
            for (
                std::size_t later = scheduled_index + 1;
                later < scheduled_stop;
                ++later
            ) {
                wave.batches[later].shared_left_group_start =
                    scheduled.shared_left_group_start;
                wave.batches[later].shared_left_group_stop =
                    scheduled.shared_left_group_start;
            }
            if (
                complementary_local_actions_.empty()
                || batch.channel_left_indices.empty()
            ) {
                scheduled.shared_left_group_stop =
                    scheduled.shared_left_group_start;
                scheduled_index = scheduled_stop;
                continue;
            }
            struct SharedLeftOccurrence {
                std::uint32_t binding = 0;
                std::uint32_t action = 0;
                std::int64_t source_k_offset = 0;
            };
            struct SharedLeftCandidate {
                std::int64_t rows = 0;
                std::int64_t inner = 0;
                std::uint16_t unique_left = 0;
                std::vector<SharedLeftOccurrence> occurrences;
            };
            std::map<std::array<std::int64_t, 3>, std::size_t>
                candidate_lookup;
            std::vector<SharedLeftCandidate> candidates;
            std::vector<std::vector<std::size_t>> binding_candidates(
                wave.bindings.size()
            );
            std::vector<bool> binding_active(
                wave.bindings.size(),
                false
            );
            for (
                std::size_t batch_schedule_index = scheduled_index;
                batch_schedule_index < scheduled_stop;
                ++batch_schedule_index
            ) {
              const RawOutputFusionBatch& batch_schedule =
                  wave.batches[batch_schedule_index];
              const RawExecutionBatch& scheduled_batch =
                  channel.batches.at(batch_schedule.batch);
              std::size_t action_position = 0;
              for (
                std::size_t binding_index =
                    batch_schedule.binding_start;
                binding_index < batch_schedule.binding_stop;
                ++binding_index
              ) {
                const RawOutputFusionBinding& binding =
                    wave.bindings.at(binding_index);
                const RawOutputFusionGroup& group =
                    wave.groups.at(binding.group);
                const RawExecutionTile& tile =
                    channel.tiles.at(binding.tile);
                const std::size_t action_count =
                    tile.action_stop - tile.action_start;
                if (
                    action_position + action_count
                        > scheduled_batch.channel_left_indices.size()
                ) {
                    throw std::logic_error(
                        "Shared-left output schedule exceeded its action table."
                    );
                }
                const bool eligible =
                    shared_left_selected[binding_index] == 0
                    &&
                    group.tile_count == 1
                    && group.temporary_offset ==
                        std::numeric_limits<std::size_t>::max()
                    && binding.shared_right_start
                        == binding.shared_right_stop
                    && (
                        wave.shared_right_deferred_output_offsets.empty()
                        || wave.shared_right_deferred_output_offsets.at(
                            binding_index
                        ) == std::numeric_limits<std::size_t>::max()
                    );
                if (eligible) {
                    const std::int64_t rows = group.la;
                    std::int64_t source_k_offset = 0;
                    for (
                        std::size_t local = 0;
                        local < action_count;
                        ++local
                    ) {
                        const std::uint32_t action_index =
                            static_cast<std::uint32_t>(
                                tile.action_start + local
                            );
                        const RawExecutionAction& action =
                            raw_execution_action_arena_.at(action_index);
                        const std::int64_t inner =
                            complementary_local_actions_.at(
                                action.group
                            ).dims[2] * channel.cr;
                        const std::array<std::int64_t, 3> key{
                            scheduled_batch.channel_left_indices[
                                action_position + local
                            ],
                            rows,
                            inner,
                        };
                        auto found = candidate_lookup.find(key);
                        if (found == candidate_lookup.end()) {
                            const std::size_t candidate =
                                candidates.size();
                            found = candidate_lookup.emplace(
                                key,
                                candidate
                            ).first;
                            SharedLeftCandidate pending;
                            pending.rows = rows;
                            pending.inner = inner;
                            pending.unique_left =
                                scheduled_batch.channel_left_indices[
                                    action_position + local
                                ];
                            candidates.push_back(std::move(pending));
                        }
                        candidates[found->second].occurrences.push_back(
                            SharedLeftOccurrence{
                                static_cast<std::uint32_t>(binding_index),
                                action_index,
                                source_k_offset,
                            }
                        );
                        binding_candidates[binding_index].push_back(
                            found->second
                        );
                        source_k_offset += inner;
                    }
                    binding_active[binding_index] =
                        !binding_candidates[binding_index].empty()
                        && source_k_offset
                            == tile.total_w * channel.cr;
                }
                action_position += action_count;
              }
              if (
                  action_position
                    != scheduled_batch.channel_left_indices.size()
              ) {
                throw std::logic_error(
                    "Shared-left output schedule did not consume its action table."
                );
              }
            }
            const auto candidate_profitable = [
                &binding_active,
                &wave,
                requested_output_copy_budget
            ](const SharedLeftCandidate& candidate) {
                std::size_t occurrences = 0;
                std::int64_t total_columns = 0;
                for (const SharedLeftOccurrence& occurrence :
                     candidate.occurrences) {
                    if (!binding_active[occurrence.binding]) {
                        continue;
                    }
                    ++occurrences;
                    total_columns += wave.groups.at(
                        wave.bindings.at(occurrence.binding).group
                    ).dq;
                }
                const long double copied_elements =
                    static_cast<long double>(total_columns)
                    * static_cast<long double>(candidate.rows);
                return occurrences >= 2
                    && candidate.rows > 0
                    && candidate.inner > 0
                    && total_columns > 0
                    && copied_elements <=
                        static_cast<long double>(
                            requested_output_copy_budget
                        ) * static_cast<long double>(occurrences - 1);
            };
            std::vector<bool> candidate_active(
                candidates.size(),
                true
            );
            bool changed = true;
            while (changed) {
                changed = false;
                for (
                    std::size_t candidate = 0;
                    candidate < candidates.size();
                    ++candidate
                ) {
                    if (
                        candidate_active[candidate]
                        && !candidate_profitable(candidates[candidate])
                    ) {
                        candidate_active[candidate] = false;
                        changed = true;
                    }
                }
                for (
                    std::size_t batch_schedule_index = scheduled_index;
                    batch_schedule_index < scheduled_stop;
                    ++batch_schedule_index
                ) {
                    const RawOutputFusionBatch& batch_schedule =
                        wave.batches[batch_schedule_index];
                    for (
                        std::size_t binding_index =
                            batch_schedule.binding_start;
                        binding_index < batch_schedule.binding_stop;
                        ++binding_index
                    ) {
                        if (!binding_active[binding_index]) {
                            continue;
                        }
                        for (const std::size_t candidate :
                             binding_candidates[binding_index]) {
                            if (!candidate_active[candidate]) {
                                binding_active[binding_index] = false;
                                changed = true;
                                break;
                            }
                        }
                    }
                }
            }
            for (
                std::size_t candidate_index = 0;
                candidate_index < candidates.size();
                ++candidate_index
            ) {
                if (!candidate_active[candidate_index]) {
                    continue;
                }
                const SharedLeftCandidate& candidate =
                    candidates[candidate_index];
                std::vector<SharedLeftOccurrence> selected;
                std::int64_t total_columns = 0;
                for (const SharedLeftOccurrence& occurrence :
                     candidate.occurrences) {
                    if (!binding_active[occurrence.binding]) {
                        continue;
                    }
                    selected.push_back(occurrence);
                    total_columns += wave.groups.at(
                        wave.bindings.at(occurrence.binding).group
                    ).dq;
                }
                if (selected.size() < 2) {
                    throw std::logic_error(
                        "Active shared-left output group became singular."
                    );
                }
                const std::size_t additional_elements =
                    static_cast<std::size_t>(
                        (candidate.inner + candidate.rows)
                        * total_columns
                    );
                if (
                    additional_elements > target_shared_left_elements
                    || wave.shared_left_right_elements
                        + wave.shared_left_output_elements
                        > target_shared_left_elements
                            - additional_elements
                ) {
                    continue;
                }
                if (
                    wave.shared_left_groups.size()
                        > std::numeric_limits<std::uint32_t>::max()
                    || wave.shared_left_bindings.size() + selected.size()
                        > std::numeric_limits<std::uint32_t>::max()
                ) {
                    throw std::overflow_error(
                        "Shared-left output arena is too large."
                    );
                }
                RawSharedLeftOutputGroup shared;
                shared.binding_start = static_cast<std::uint32_t>(
                    wave.shared_left_bindings.size()
                );
                shared.reference_binding = selected.front().binding;
                shared.channel = scheduled.channel;
                shared.channel_level =
                    scheduled_stop > scheduled_index + 1;
                if (shared.channel_level) {
                    shared.reference_source_k_offset =
                        static_cast<std::int64_t>(
                            channel.unique_left_row_offsets.at(
                                candidate.unique_left
                            )
                        ) * channel.cr;
                    shared.reference_stride = candidate.inner;
                } else {
                    shared.reference_source_k_offset =
                        selected.front().source_k_offset;
                    shared.reference_stride =
                        channel.tiles.at(
                            wave.bindings.at(
                                selected.front().binding
                            ).tile
                        ).total_w * channel.cr;
                }
                shared.rows = candidate.rows;
                shared.inner = candidate.inner;
                shared.total_columns = total_columns;
                shared.right_offset = wave.shared_left_right_elements;
                shared.output_offset = wave.shared_left_output_elements;
                std::int64_t column_offset = 0;
                for (const SharedLeftOccurrence& occurrence : selected) {
                    wave.shared_left_bindings.push_back(
                        RawSharedLeftOutputBinding{
                            occurrence.binding,
                            occurrence.action,
                            occurrence.source_k_offset,
                            column_offset,
                        }
                    );
                    shared_left_selected[occurrence.binding] = 1;
                    column_offset += wave.groups.at(
                        wave.bindings.at(occurrence.binding).group
                    ).dq;
                }
                shared.binding_stop = static_cast<std::uint32_t>(
                    wave.shared_left_bindings.size()
                );
                wave.shared_left_right_elements +=
                    static_cast<std::size_t>(
                        candidate.inner * total_columns
                    );
                wave.shared_left_output_elements +=
                    static_cast<std::size_t>(
                        candidate.rows * total_columns
                    );
                wave.shared_left_groups.push_back(shared);
            }
            scheduled.shared_left_group_stop =
                static_cast<std::uint32_t>(
                    wave.shared_left_groups.size()
                );
            scheduled_index = scheduled_stop;
        }
        constexpr std::size_t minimum_grouped_products = 4;
        constexpr std::size_t no_offset =
            std::numeric_limits<std::size_t>::max();
        const bool grouped_product_backend =
            grouped_dgemm_batch_function() != nullptr
            && !disable_grouped_output_products();
        const std::size_t grouped_small_work_limit =
            grouped_small_output_work_limit();
        for (RawOutputFusionBatch& scheduled : wave.batches) {
            if (
                !grouped_product_backend
                && grouped_small_work_limit == 0
            ) {
                continue;
            }
            struct PendingProduct {
                std::uint32_t binding = 0;
                std::int32_t rows = 0;
                std::int32_t cols = 0;
                std::int32_t inner = 0;
            };
            std::vector<PendingProduct> pending;
            pending.reserve(
                scheduled.binding_stop - scheduled.binding_start
            );
            const RawInputSuperchannel& channel =
                raw_input_superchannels_.at(scheduled.channel);
            for (
                std::size_t binding_index = scheduled.binding_start;
                binding_index < scheduled.binding_stop;
                ++binding_index
            ) {
                const RawOutputFusionBinding& binding =
                    wave.bindings.at(binding_index);
                const RawOutputFusionGroup& group =
                    wave.groups.at(binding.group);
                const RawExecutionTile& tile =
                    channel.tiles.at(binding.tile);
                if (
                    shared_left_selected[binding_index] != 0
                    || group.tile_count != 1
                    || group.temporary_offset != no_offset
                    || tile.direct_preferred
                    || binding.shared_right_start
                        != binding.shared_right_stop
                    || (
                        !wave.shared_right_deferred_output_offsets.empty()
                        && wave.shared_right_deferred_output_offsets.at(
                            binding_index
                        ) != no_offset
                    )
                ) {
                    continue;
                }
                const std::int64_t inner =
                    tile.total_w * channel.cr;
                const long double work =
                    static_cast<long double>(group.la)
                    * static_cast<long double>(group.dq)
                    * static_cast<long double>(inner);
                if (
                    group.la <= 0
                    || group.dq <= 0
                    || inner <= 0
                    || group.la
                        > std::numeric_limits<std::int32_t>::max()
                    || group.dq
                        > std::numeric_limits<std::int32_t>::max()
                    || inner
                        > std::numeric_limits<std::int32_t>::max()
                    || work > static_cast<long double>(
                        std::numeric_limits<std::int64_t>::max()
                    )
                ) {
                    continue;
                }
                ++grouped_output_candidate_bindings;
                static constexpr std::array<std::int64_t, 9>
                    work_limits{
                        16,
                        64,
                        256,
                        1'024,
                        4'096,
                        16'384,
                        65'536,
                        262'144,
                        1'000'000,
                    };
                std::size_t work_bin = 0;
                while (
                    work_bin < work_limits.size()
                    && work > work_limits[work_bin]
                ) {
                    ++work_bin;
                }
                ++grouped_output_candidate_work_counts[work_bin];
                const bool custom_safe =
                    grouped_small_work_limit > 0
                    && work <= static_cast<long double>(
                        grouped_small_work_limit
                    );
                const bool vendor_safe =
                    grouped_product_backend
                    && grouped_output_product_is_safe(
                        static_cast<std::int64_t>(work)
                    );
                if (!custom_safe && !vendor_safe) {
                    continue;
                }
                pending.push_back(PendingProduct{
                    static_cast<std::uint32_t>(binding_index),
                    static_cast<std::int32_t>(group.la),
                    static_cast<std::int32_t>(group.dq),
                    static_cast<std::int32_t>(inner),
                });
            }
            if (pending.size() < minimum_grouped_products) {
                continue;
            }
            std::sort(
                pending.begin(),
                pending.end(),
                [](const PendingProduct& left, const PendingProduct& right) {
                    return std::tie(left.rows, left.cols, left.inner)
                        < std::tie(right.rows, right.cols, right.inner);
                }
            );
            if (
                wave.grouped_product_groups.size()
                    > std::numeric_limits<std::uint32_t>::max()
                || wave.grouped_product_bindings.size()
                    + pending.size()
                    > std::numeric_limits<std::uint32_t>::max()
            ) {
                throw std::overflow_error(
                    "Grouped output-product arena is too large."
                );
            }
            scheduled.grouped_product_start =
                static_cast<std::uint32_t>(
                    wave.grouped_product_groups.size()
                );
            std::size_t product_index = 0;
            while (product_index < pending.size()) {
                const PendingProduct& first = pending[product_index];
                RawGroupedOutputProductGroup group;
                group.binding_start = static_cast<std::uint32_t>(
                    wave.grouped_product_bindings.size()
                );
                group.rows = first.rows;
                group.cols = first.cols;
                group.inner = first.inner;
                do {
                    wave.grouped_product_bindings.push_back(
                        pending[product_index].binding
                    );
                    ++product_index;
                } while (
                    product_index < pending.size()
                    && pending[product_index].rows == group.rows
                    && pending[product_index].cols == group.cols
                    && pending[product_index].inner == group.inner
                );
                group.binding_stop = static_cast<std::uint32_t>(
                    wave.grouped_product_bindings.size()
                );
                const std::size_t product_count =
                    group.binding_stop - group.binding_start;
                const std::size_t right_elements =
                    product_count
                    * static_cast<std::size_t>(
                        group.inner * group.cols
                    );
                const bool custom_group =
                    grouped_small_work_limit > 0
                    && static_cast<std::size_t>(
                        group.rows * group.cols * group.inner
                    ) <= grouped_small_work_limit;
                const bool has_custom_storage =
                    custom_group
                    && right_elements <= target_shared_left_elements
                    && wave.grouped_product_right_elements
                        <= target_shared_left_elements - right_elements;
                if (has_custom_storage) {
                    group.persistent_right_offset =
                        wave.grouped_product_right_elements;
                    wave.grouped_product_right_elements += right_elements;
                } else if (
                    !grouped_product_backend
                    || !grouped_output_product_is_safe(
                        static_cast<std::int64_t>(
                            group.rows * group.cols * group.inner
                        )
                    )
                ) {
                    wave.grouped_product_bindings.resize(
                        group.binding_start
                    );
                    continue;
                }
                if (
                    group.persistent_right_offset !=
                        std::numeric_limits<std::size_t>::max()
                ) {
                    for (
                        std::size_t reference = group.binding_start;
                        reference < group.binding_stop;
                        ++reference
                    ) {
                        persistent_product_selected.at(
                            wave.grouped_product_bindings.at(reference)
                        ) = 1;
                    }
                }
                wave.grouped_product_groups.push_back(group);
            }
            scheduled.grouped_product_stop =
                static_cast<std::uint32_t>(
                    wave.grouped_product_groups.size()
                );
        }
        for (const RawOutputFusionBatch& scheduled : wave.batches) {
            RawInputSuperchannel& channel =
                raw_input_superchannels_.at(scheduled.channel);
            RawExecutionBatch& batch =
                channel.batches.at(scheduled.batch);
            bool factorized_batch = scheduled.singleton_outputs;
            if (factorized_batch) {
                for (
                    std::size_t binding_index = scheduled.binding_start;
                    binding_index < scheduled.binding_stop;
                    ++binding_index
                ) {
                    const RawOutputFusionBinding& binding =
                        wave.bindings.at(binding_index);
                    if (
                        binding.shared_right_start
                            != binding.shared_right_stop
                    ) {
                        continue;
                    }
                    if (!can_accumulate_factorized_output(
                        channel,
                        channel.tiles.at(binding.tile)
                    )) {
                        factorized_batch = false;
                        break;
                    }
                }
            }
            std::size_t packed_right_elements = 0;
            for (
                std::size_t binding_index = scheduled.binding_start;
                binding_index < scheduled.binding_stop;
                ++binding_index
            ) {
                RawOutputFusionBinding& binding =
                    wave.bindings.at(binding_index);
                const RawOutputFusionGroup& group =
                    wave.groups.at(binding.group);
                RawExecutionTile& tile =
                    channel.tiles.at(binding.tile);
                const bool requires_right =
                    !factorized_batch
                    && shared_left_selected.at(binding_index) == 0
                    && persistent_product_selected.at(binding_index) == 0
                    && binding.shared_right_start
                        == binding.shared_right_stop
                    && group.temporary_offset
                        == std::numeric_limits<std::size_t>::max();
                tile.requires_right = requires_right;
                binding.right_offset = packed_right_elements;
                if (requires_right) {
                    packed_right_elements += static_cast<std::size_t>(
                        tile.total_w * channel.cr * group.dq
                    );
                }
            }
            batch.total_right_elements = packed_right_elements;
            batch.requires_right = packed_right_elements != 0;
        }
        raw_output_fusion_waves_.push_back(std::move(wave));
    }
    std::size_t fused_groups = 0;
    std::size_t fused_tiles = 0;
    std::size_t maximum_workspace = 0;
    std::size_t shared_right_panels = 0;
    std::size_t shared_right_bindings = 0;
    std::size_t grouped_product_groups = 0;
    std::size_t grouped_product_bindings = 0;
    std::size_t maximum_shared_right_workspace = 0;
    for (const RawOutputFusionWave& wave : raw_output_fusion_waves_) {
        maximum_workspace = std::max(
            maximum_workspace,
            wave.temporary_elements
                + wave.right_elements
                + wave.shared_left_right_elements
                + wave.shared_left_output_elements
                + wave.grouped_product_right_elements
        );
        shared_right_panels += wave.shared_right_panels.size();
        shared_right_bindings += wave.shared_right_bindings.size();
        grouped_product_groups += wave.grouped_product_groups.size()
            + wave.shared_left_groups.size();
        grouped_product_bindings +=
            wave.grouped_product_bindings.size()
            + wave.shared_left_bindings.size();
        maximum_shared_right_workspace = std::max(
            maximum_shared_right_workspace,
            wave.shared_right_input_elements
                + wave.shared_right_output_elements
                + wave.shared_right_deferred_output_elements
                + wave.shared_right_tile_output_elements
        );
        for (const RawOutputFusionGroup& group : wave.groups) {
            if (
                group.temporary_offset ==
                std::numeric_limits<std::size_t>::max()
            ) {
                continue;
            }
            ++fused_groups;
            fused_tiles += group.tile_count;
        }
    }
    peak_raw_output_fusion_waves_ = std::max(
        peak_raw_output_fusion_waves_,
        raw_output_fusion_waves_.size()
    );
    peak_raw_output_fusion_groups_ = std::max(
        peak_raw_output_fusion_groups_,
        fused_groups
    );
    peak_raw_output_fusion_tiles_ = std::max(
        peak_raw_output_fusion_tiles_,
        fused_tiles
    );
    peak_raw_output_fusion_workspace_elements_ = std::max(
        peak_raw_output_fusion_workspace_elements_,
        maximum_workspace
    );
    peak_raw_shared_right_panels_ = std::max(
        peak_raw_shared_right_panels_,
        shared_right_panels
    );
    peak_raw_shared_right_bindings_ = std::max(
        peak_raw_shared_right_bindings_,
        shared_right_bindings
    );
    peak_raw_shared_right_workspace_elements_ = std::max(
        peak_raw_shared_right_workspace_elements_,
        maximum_shared_right_workspace
    );
    grouped_output_product_groups_ = std::max(
        grouped_output_product_groups_,
        grouped_product_groups
    );
    grouped_output_product_bindings_ = std::max(
        grouped_output_product_bindings_,
        grouped_product_bindings
    );
    if (
        grouped_output_candidate_bindings
        > peak_grouped_output_candidate_bindings_
    ) {
        peak_grouped_output_candidate_bindings_ =
            grouped_output_candidate_bindings;
        peak_grouped_output_candidate_work_counts_ =
            grouped_output_candidate_work_counts;
    }
    for (RawInputSuperchannel& channel : raw_input_superchannels_) {
        for (RawExecutionTile& tile : channel.tiles) {
            tile.planned_requires_right = tile.requires_right;
        }
        for (RawExecutionBatch& batch : channel.batches) {
            batch.planned_requires_right = batch.requires_right;
            batch.planned_total_right_elements =
                batch.total_right_elements;
        }
    }
    if (
        fused_groups == 0
        && shared_right_panels == 0
        && grouped_product_groups == 0
    ) {
        raw_output_fusion_waves_.clear();
    }
}

std::uint64_t
MovingEnvironment::reduced_contextual_action_topology_revision()
    const noexcept {
    std::uint64_t revision = 1469598103934665603ULL;
    const auto mix = [&revision](std::int64_t value) {
        revision ^= static_cast<std::uint64_t>(value);
        revision *= 1099511628211ULL;
    };
    mix(static_cast<std::int64_t>(complementary_local_actions_.size()));
    mix(static_cast<std::int64_t>(complementary_local_terms_.size()));
    for (
        const ComplementaryLocalAction& action :
        complementary_local_actions_
    ) {
        mix(action.input_offset);
        mix(action.output_offset);
        for (const std::int64_t dimension : action.dims) {
            mix(dimension);
        }
        mix(action.term_start);
        mix(action.term_stop);
    }
    for (
        const ComplementaryLocalTerm& term :
        complementary_local_terms_
    ) {
        mix(term.left_matrix);
        mix(term.right_matrix);
    }
    return revision == 0 ? std::uint64_t{1} : revision;
}

bool MovingEnvironment::raw_combined_left_schedule_valid() const {
    for (const RawExecutionAction& action : raw_execution_action_arena_) {
        if (action.combined_left_start == action.combined_left_stop) {
            if (action.right_grouped) return false;
            continue;
        }
        if (
            action.factor < 0
            || !action.right_grouped
            || action.combined_left_start > action.combined_left_stop
            || action.combined_left_stop > raw_combined_left_terms_.size()
            || action.group >= complementary_local_actions_.size()
        ) {
            return false;
        }
        const ComplementaryLocalAction& local =
            complementary_local_actions_[action.group];
        const std::size_t reference_start =
            static_cast<std::size_t>(action.factor);
        const std::size_t reference_stop = action.factor_stop;
        if (
            reference_start < local.term_start
            || reference_start >= reference_stop
            || reference_stop > local.term_stop
        ) {
            return false;
        }
        const std::int32_t right_matrix =
            complementary_local_terms_[reference_start].right_matrix;
        for (
            std::size_t combined = action.combined_left_start;
            combined < action.combined_left_stop;
            ++combined
        ) {
            const std::uint32_t term = raw_combined_left_terms_[combined];
            if (
                term < local.term_start
                || term >= local.term_stop
                || complementary_local_terms_[term].right_matrix
                    != right_matrix
            ) {
                return false;
            }
        }
    }
    return true;
}

void MovingEnvironment::stash_reduced_contextual_execution_schedule() {
    if (!active_reduced_contextual_execution_schedule_) {
        return;
    }
    restore_planned_complementary_right_layout();
    const std::uint64_t topology_revision =
        reduced_contextual_action_topology_revision();
    ReducedContextualExecutionSchedule& schedule =
        *active_reduced_contextual_execution_schedule_;
    schedule.groups = std::move(raw_execution_groups_);
    schedule.actions = std::move(raw_execution_action_arena_);
    schedule.combined_left_terms =
        std::move(raw_combined_left_terms_);
    schedule.superchannels = std::move(raw_input_superchannels_);
    schedule.output_waves = std::move(raw_output_fusion_waves_);
    schedule.local_actions = std::move(complementary_local_actions_);
    schedule.local_terms = std::move(complementary_local_terms_);
    schedule.compact_right_panels = std::move(compact_right_panels_);
    compact_right_panel_values_.clear();
    schedule.action_count = raw_execution_actions_;
    schedule.right_grouped_action_count =
        right_grouped_execution_actions_;
    schedule.tile_count = raw_input_superchannel_tiles_;
    schedule.batch_count = raw_input_superchannel_batches_;
    schedule.topology_revision = topology_revision;
    active_reduced_contextual_execution_schedule_.reset();
}

bool MovingEnvironment::restore_reduced_contextual_execution_schedule(
    ContextualFactorRoutePlan& plan,
    bool restore_local_actions
) {
    const double started = wall_seconds();
    if (
        !plan.execution ||
        (
            plan.execution->groups.empty() &&
            plan.execution->action_count == 0
        )
    ) {
        return false;
    }
    ReducedContextualExecutionSchedule& schedule = *plan.execution;
    if (
        (
            !restore_local_actions
            && schedule.topology_revision !=
                reduced_contextual_action_topology_revision()
        )
        || (
            restore_local_actions
            && (
                schedule.local_actions.empty()
                || schedule.local_terms.empty()
            )
        )
    ) {
        plan.execution.reset();
        return false;
    }
    raw_execution_groups_ = std::move(schedule.groups);
    raw_execution_action_arena_ = std::move(schedule.actions);
    raw_combined_left_terms_ =
        std::move(schedule.combined_left_terms);
    raw_pointer_action_arena_.clear();
    raw_input_superchannels_ = std::move(schedule.superchannels);
    raw_output_fusion_waves_ = std::move(schedule.output_waves);
    compact_right_panels_ = std::move(schedule.compact_right_panels);
    raw_execution_actions_ = schedule.action_count;
    right_grouped_execution_actions_ =
        schedule.right_grouped_action_count;
    raw_input_superchannel_tiles_ = schedule.tile_count;
    raw_input_superchannel_batches_ = schedule.batch_count;
    if (restore_local_actions) {
        complementary_local_actions_ =
            std::move(schedule.local_actions);
        complementary_local_terms_ =
            std::move(schedule.local_terms);
    } else {
        schedule.local_actions.clear();
        schedule.local_terms.clear();
    }
    if (!raw_combined_left_schedule_valid()) {
        raw_execution_groups_.clear();
        raw_execution_action_arena_.clear();
        raw_combined_left_terms_.clear();
        raw_input_superchannels_.clear();
        raw_output_fusion_waves_.clear();
        compact_right_panels_.clear();
        compact_right_panel_values_.clear();
        raw_execution_actions_ = 0;
        right_grouped_execution_actions_ = 0;
        raw_input_superchannel_tiles_ = 0;
        raw_input_superchannel_batches_ = 0;
        plan.execution.reset();
        return false;
    }
    active_reduced_contextual_execution_schedule_ = plan.execution;
    ++complementary_execution_graph_hits_;
    contextual_compiled_schedule_restore_seconds_ +=
        wall_seconds() - started;
    return true;
}

void MovingEnvironment::refresh_complementary_execution_slab() {
    constexpr std::size_t no_offset =
        std::numeric_limits<std::size_t>::max();
    restore_planned_complementary_right_layout();
    const double started = wall_seconds();
    std::size_t slab_elements = 0;
    std::size_t required_elements = 0;
    for (const RawInputSuperchannel& channel : raw_input_superchannels_) {
        if (channel.cached_unique_left_offset != no_offset) {
            const std::size_t elements = static_cast<std::size_t>(
                channel.unique_left_rows * channel.kb
            );
            required_elements += elements;
            slab_elements = std::max(
                slab_elements,
                channel.cached_unique_left_offset + elements
            );
        }
        for (const RawExecutionBatch& batch : channel.batches) {
            if (channel.cached_unique_left_offset == no_offset) {
                required_elements += static_cast<std::size_t>(
                    batch.packed_left_rows * channel.kb
                );
            }
            if (batch.requires_right) {
                required_elements += batch.total_right_elements;
            }
            if (batch.cached_left_offset != no_offset) {
                slab_elements = std::max(
                    slab_elements,
                    batch.cached_left_offset
                        + static_cast<std::size_t>(
                            batch.packed_left_rows * channel.kb
                        )
                );
            }
            if (batch.requires_right && batch.cached_right_offset != no_offset) {
                slab_elements = std::max(
                    slab_elements,
                    batch.cached_right_offset
                        + batch.total_right_elements
                );
            }
        }
    }
    complementary_execution_slab_required_elements_ = required_elements;
    peak_complementary_execution_slab_required_elements_ = std::max(
        peak_complementary_execution_slab_required_elements_,
        required_elements
    );
    if (slab_elements == required_elements) {
        ++complementary_execution_slab_full_prepares_;
    } else {
        ++complementary_execution_slab_partial_prepares_;
    }
    complementary_execution_slab_.resize(slab_elements);
    select_direct_complementary_tiles();
    compact_selected_direct_right_layout();
    refresh_compact_right_panels();
    for (RawInputSuperchannel& channel : raw_input_superchannels_) {
        if (channel.cached_unique_left_offset == no_offset) {
            continue;
        }
        for (
            std::size_t unique_index = 0;
            unique_index < channel.unique_left_actions.size();
            ++unique_index
        ) {
            const RawExecutionAction& action =
                raw_execution_action_arena_.at(
                    channel.unique_left_actions[unique_index]
                );
            const std::int64_t w =
                complementary_local_actions_.at(
                    action.group
                ).dims[2];
            pack_raw_execution_action_into(
                action,
                w,
                0,
                complementary_execution_slab_.data()
                    + channel.cached_unique_left_offset
                    + channel.unique_left_row_offsets[unique_index]
                        * channel.kb,
                nullptr
            );
        }
    }
    for (RawInputSuperchannel& channel : raw_input_superchannels_) {
        for (RawExecutionBatch& batch : channel.batches) {
            if (
                batch.cached_left_offset == no_offset
                && batch.cached_right_offset == no_offset
            ) {
                continue;
            }
            pack_raw_execution_batch(
                channel,
                batch,
                batch.cached_left_offset == no_offset
                    ? nullptr
                    : complementary_execution_slab_.data()
                        + batch.cached_left_offset,
                batch.cached_right_offset == no_offset
                    ? nullptr
                    : complementary_execution_slab_.data()
                        + batch.cached_right_offset
            );
        }
    }
    prepare_output_fusion_right_slab();
    raw_execution_pack_seconds_ += wall_seconds() - started;
}

void MovingEnvironment::pack_raw_execution_batch(
    const RawInputSuperchannel& channel,
    const RawExecutionBatch& batch,
    double* left_values,
    double* right_values
) {
    if (
        left_values != nullptr
        && !complementary_local_actions_.empty()
        && batch.packed_left_rows < batch.total_left_rows
    ) {
        if (
            batch.unique_left_actions.size()
                != batch.unique_left_row_offsets.size()
        ) {
            throw std::logic_error(
                "Complementary unique-left schedule is inconsistent."
            );
        }
        for (
            std::size_t unique = 0;
            unique < batch.unique_left_actions.size();
            ++unique
        ) {
            const RawExecutionAction& action =
                raw_execution_action_arena_.at(
                    batch.unique_left_actions[unique]
                );
            const std::int64_t w =
                complementary_local_actions_.at(action.group).dims[2];
            pack_raw_execution_action_into(
                action,
                w,
                0,
                left_values
                    + batch.unique_left_row_offsets[unique] * channel.kb,
                nullptr
            );
        }
    }
    std::int64_t left_row_offset = 0;
    std::int64_t batch_w_offset = 0;
    std::size_t right_offset = 0;
    for (
        std::size_t tile_index = batch.tile_start;
        tile_index < batch.tile_stop;
        ++tile_index
    ) {
        const RawExecutionTile& tile = channel.tiles[tile_index];
        const RawExecutionGroup& execution =
            raw_execution_groups_[tile.execution];
        const std::int64_t la =
            execution.dims[0] * execution.dims[2];
        const std::int64_t dq =
            execution.dims[6] * execution.dims[4];
        double* left_target = (
            left_values == nullptr
                || (
                    !complementary_local_actions_.empty()
                    && batch.packed_left_rows < batch.total_left_rows
                )
            ? nullptr
            : left_values + left_row_offset * channel.kb
        );
        double* right_target = (
            right_values == nullptr || !tile.requires_right
                ? nullptr
                : (
                    batch.right_first
                    ? right_values
                    : right_values
                        + static_cast<std::ptrdiff_t>(right_offset)
                )
        );
        std::int64_t w_offset = 0;
        for (
            std::size_t action_index = tile.action_start;
            action_index < tile.action_stop;
            ++action_index
        ) {
            const RawExecutionAction& action =
                raw_execution_action_arena_[action_index];
            const std::int64_t w = (
                complementary_local_actions_.empty()
                ? raw_route_groups_[action.group].dims[2]
                : complementary_local_actions_[action.group].dims[2]
            );
            if (
                action.direct_preferred
                && right_target != nullptr
            ) {
                if (batch.right_first) {
                    throw std::logic_error(
                        "Direct complementary action entered a "
                        "right-first panel."
                    );
                }
                std::fill_n(
                    right_target
                        + static_cast<std::ptrdiff_t>(
                            w_offset * channel.cr * dq
                        ),
                    static_cast<std::size_t>(w * channel.cr * dq),
                    0.0
                );
            }
            pack_raw_execution_action_into(
                action,
                tile.total_w,
                w_offset,
                left_target,
                action.direct_preferred ? nullptr : right_target,
                batch.right_first,
                batch.total_w,
                batch_w_offset + w_offset
            );
            w_offset += w;
        }
        left_row_offset += la * tile.total_w;
        batch_w_offset += tile.total_w;
        if (tile.requires_right) {
            right_offset += static_cast<std::size_t>(
                tile.total_w * channel.cr * dq
            );
        }
    }
    if (
        right_values != nullptr && !batch.right_first
        && right_offset != batch.total_right_elements
    ) {
        throw std::logic_error(
            "Complementary compact-right schedule is inconsistent."
        );
    }
}

