void MovingEnvironment::apply_persistent_output_groups_real(
    const double* packed_input,
    double* output
) {
    for (const RawPersistentOutputGroup& group :
         raw_persistent_output_groups_) {
        raw_output_fusion_temporary_real_.resize(
            static_cast<std::size_t>(group.la * group.total_k)
        );
        double* temporary = raw_output_fusion_temporary_real_.data();
        for (
            std::size_t binding_index = group.binding_start;
            binding_index < group.binding_stop;
            ++binding_index
        ) {
            const RawPersistentOutputBinding& binding =
                raw_persistent_output_bindings_[binding_index];
            const RawInputSuperchannel& channel =
                raw_input_superchannels_[binding.channel];
            const RawExecutionTile& tile =
                channel.tiles[binding.tile];
            const double* left = raw_persistent_output_left_.data()
                + binding.left_offset;
            const double* source =
                packed_input + channel.input_offset;
            for (std::int64_t left_axis = 0;
                 left_axis < group.la;
                 ++left_axis)
            for (std::int64_t w = 0; w < tile.total_w; ++w) {
                const double* left_row = left
                    + (left_axis * tile.total_w + w) * channel.kb;
                double* target = temporary
                    + left_axis * group.total_k
                    + binding.group_k_offset
                    + w * channel.cr;
                std::fill(
                    target,
                    target + channel.cr,
                    0.0
                );
                for (
                    std::int64_t inner = 0;
                    inner < channel.kb;
                    ++inner
                ) {
                    const double scale = left_row[inner];
                    const double* source_row =
                        source + inner * channel.cr;
                    for (
                        std::int64_t right_axis = 0;
                        right_axis < channel.cr;
                        ++right_axis
                    ) {
                        target[right_axis] +=
                            scale * source_row[right_axis];
                    }
                }
            }
        }
        raw_dgemm(
            false,
            false,
            group.la,
            group.dq,
            group.total_k,
            1.0,
            temporary,
            group.total_k,
            raw_persistent_output_right_.data() + group.right_offset,
            group.dq,
            1.0,
            output + group.output_offset,
            group.dq
        );
        ++raw_output_fusion_gemm_calls_;
    }
}
