std::size_t
MovingEnvironment::complementary_execution_graph_bytes() const noexcept {
    std::size_t total = 0;
    std::set<const ReducedContextualExecutionSchedule*> counted;
    for (const auto& [key, plan] : contextual_route_plans_) {
        static_cast<void>(key);
        if (plan.execution && counted.insert(plan.execution.get()).second) {
            total += plan.execution->memory_bytes();
        }
    }
    if (
        active_reduced_contextual_execution_schedule_ &&
        counted.insert(
            active_reduced_contextual_execution_schedule_.get()
        ).second
    ) {
        total +=
            active_reduced_contextual_execution_schedule_->memory_bytes();
    }
    return total;
}
