std::size_t
MovingEnvironment::contextual_route_core_elements() const noexcept {
    std::size_t total = 0;
    for (const auto& [key, plan] : contextual_route_plans_) {
        static_cast<void>(key);
        total += plan.left.w_data.size() + plan.right.w_data.size();
    }
    return total;
}
std::size_t
MovingEnvironment::contextual_route_core_nonzero_elements() const noexcept {
    std::size_t total = 0;
    for (const auto& [key, plan] : contextual_route_plans_) {
        static_cast<void>(key);
        total += static_cast<std::size_t>(std::count_if(
            plan.left.w_data.begin(),
            plan.left.w_data.end(),
            [](double value) { return value != 0.0; }
        ));
        total += static_cast<std::size_t>(std::count_if(
            plan.right.w_data.begin(),
            plan.right.w_data.end(),
            [](double value) { return value != 0.0; }
        ));
    }
    return total;
}
