std::size_t
MovingEnvironment::contextual_core_cache_bytes() const noexcept {
    std::size_t total = 0;
    for (const auto& [key, blocks] : contextual_core_cache_) {
        static_cast<void>(key);
        total += sizeof(key);
        total += blocks.capacity() * sizeof(ContextualCoreBlock);
        for (const ContextualCoreBlock& block : blocks) {
            total += block.values.capacity() * sizeof(double);
        }
    }
    return total;
}
