std::size_t MovingEnvironment::owned_boundary_bytes() const noexcept {
    std::size_t total = 0;
    for (const auto& [key, arena] : boundaries_) {
        static_cast<void>(key);
        if (arena.owns_values) {
            total += (
                arena.owned_values ? arena.owned_values->size() : 0
            ) * sizeof(double);
        }
    }
    for (const auto& [key, arena] : complex_boundaries_) {
        static_cast<void>(key);
        total += (
            arena.owned_values ? arena.owned_values->size() : 0
        ) * sizeof(Complex);
    }
    for (const auto& [key, arena] : complex_metric_boundaries_) {
        static_cast<void>(key);
        total += (
            arena.owned_values ? arena.owned_values->size() : 0
        ) * sizeof(Complex);
    }
    return total;
}
