std::size_t MovingEnvironment::factor_route_table_bytes() const noexcept {
    std::size_t total = factor_routes_.capacity() * sizeof(FactorRoute)
        + raw_route_groups_.capacity() * sizeof(RawRouteGroup);
    total += complementary_local_actions_.capacity()
        * sizeof(ComplementaryLocalAction);
    total += complementary_local_terms_.capacity()
        * sizeof(ComplementaryLocalTerm);
    total += reduced_contextual_left_matrices_.capacity()
        * sizeof(ReducedContextualMatrix);
    for (
        const ReducedContextualMatrix& matrix :
        reduced_contextual_left_matrices_
    ) {
        total += matrix.values.capacity() * sizeof(double);
    }
    total += reduced_contextual_right_matrices_.capacity()
        * sizeof(ReducedContextualMatrix);
    for (
        const ReducedContextualMatrix& matrix :
        reduced_contextual_right_matrices_
    ) {
        total += matrix.values.capacity() * sizeof(double);
    }
    const auto decomposition_workspace_bytes = [](
        const ContextualDecompositionWorkspace& workspace
    ) {
        return workspace.values.capacity()
                * sizeof(ContextualBoundaryDecomposition)
            + workspace.ready.capacity() * sizeof(std::uint8_t)
            + (
                workspace.component_values.capacity()
                + workspace.matrix_values.capacity()
                + workspace.square_scratch.capacity()
                + workspace.residual_scratch.capacity()
            ) * sizeof(double)
            + workspace.pivot_components.capacity()
                * sizeof(std::uint16_t);
    };
    total += decomposition_workspace_bytes(
        left_decomposition_workspace_
    );
    total += decomposition_workspace_bytes(
        right_decomposition_workspace_
    );
    for (const RawRouteGroup& group : raw_route_groups_) {
        total += group.factors.capacity() * sizeof(RawFactorPair);
        total += group.factor_scales.capacity() * sizeof(double);
        total += group.fused_left_factors.capacity() * sizeof(std::int64_t);
        total += group.fused_right_factors.capacity() * sizeof(std::int64_t);
        total += group.fused_left_values.capacity() * sizeof(double);
        total += group.fused_right_values.capacity() * sizeof(double);
    }
    total += reduced_contextual_diagonal_.capacity() * sizeof(double);
    total += raw_execution_groups_.capacity() * sizeof(RawExecutionGroup);
    total += (
        raw_execution_action_arena_.capacity()
        + raw_pointer_action_arena_.capacity()
    ) * sizeof(RawExecutionAction);
    total += raw_combined_left_terms_.capacity()
        * sizeof(std::uint32_t);
    total += raw_input_superchannels_.capacity()
        * sizeof(RawInputSuperchannel);
    for (const RawInputSuperchannel& channel : raw_input_superchannels_) {
        total += channel.tiles.capacity() * sizeof(RawExecutionTile);
        total += channel.batches.capacity() * sizeof(RawExecutionBatch);
        total += channel.unique_left_actions.capacity()
            * sizeof(std::uint32_t);
        total += channel.unique_left_row_offsets.capacity()
            * sizeof(std::uint32_t);
        for (const RawExecutionBatch& batch : channel.batches) {
            total += batch.left_values.capacity() * sizeof(double);
            total += batch.right_values.capacity() * sizeof(double);
            total += batch.unique_left_actions.capacity()
                * sizeof(std::uint32_t);
            total += (
                batch.unique_left_row_offsets.capacity()
                + batch.action_left_row_offsets.capacity()
            ) * sizeof(std::int64_t);
            total += batch.channel_left_indices.capacity()
                * sizeof(std::uint16_t);
            total += batch.compact_output_products.capacity()
                * sizeof(RawCompactOutputProduct);
            total += batch.compact_output_wave_offsets.capacity()
                * sizeof(std::uint32_t);
        }
    }
    total += compact_right_panels_.capacity()
        * sizeof(RawCompactRightPanel);
    total += compact_right_panel_values_.capacity() * sizeof(double);
    total += raw_output_fusion_waves_.capacity()
        * sizeof(RawOutputFusionWave);
    for (const RawOutputFusionWave& wave : raw_output_fusion_waves_) {
        total += wave.memory_bytes();
    }
    total += complementary_execution_slab_.capacity() * sizeof(double);
    total += dense_pair_executions_.capacity() * sizeof(DensePairExecution);
    for (const DensePairExecution& execution : dense_pair_executions_) {
        total += execution.offsets.capacity() * sizeof(std::int64_t);
        total += execution.sizes.capacity() * sizeof(std::int64_t);
        total += execution.values.capacity() * sizeof(double);
    }
    const auto owned_topology_bytes = [](const RawFactorSource& source) {
        return (
            source.owned_boundary_ids.capacity()
            + source.owned_w_ids.capacity()
            + source.owned_boundary_offsets.capacity()
            + source.owned_boundary_shape_offsets.capacity()
            + source.owned_boundary_shapes.capacity()
            + source.owned_w_offsets.capacity()
            + source.owned_w_shape_offsets.capacity()
            + source.owned_w_shapes.capacity()
        ) * sizeof(std::int64_t);
    };
    total += owned_topology_bytes(left_raw_factor_source_);
    total += owned_topology_bytes(right_raw_factor_source_);
    total += (
        left_raw_factor_source_.cache_starts.capacity()
        + left_raw_factor_source_.cache_sizes.capacity()
        + right_raw_factor_source_.cache_starts.capacity()
        + right_raw_factor_source_.cache_sizes.capacity()
    ) * sizeof(std::int64_t);
    total += (
        left_raw_factor_source_.cacheable.capacity()
        + left_raw_factor_source_.cache_valid.capacity()
        + right_raw_factor_source_.cacheable.capacity()
        + right_raw_factor_source_.cache_valid.capacity()
    ) * sizeof(std::uint8_t);
    return total;
}
std::size_t MovingEnvironment::borrowed_factor_pool_bytes() const noexcept {
    return (left_factor_elements_ + right_factor_elements_) * sizeof(double)
        + borrowed_raw_factor_source_bytes();
}
std::size_t MovingEnvironment::factor_route_scratch_bytes() const noexcept {
    return (
            factor_route_scratch_.capacity()
            + active_bond_h_diagonal_.capacity()
            + active_bond_n_diagonal_.capacity()
            + active_bond_solution_.capacity()
        ) * sizeof(Complex)
        + (
            factor_route_real_scratch_.capacity()
            + real_matvec_input_.capacity()
            + real_matvec_output_.capacity()
            + active_bond_h_diagonal_real_.capacity()
            + active_bond_n_diagonal_real_.capacity()
            + complementary_panel_scratch_.capacity()
        ) * sizeof(double)
        + (
            raw_input_real_.capacity()
            + raw_input_imag_.capacity()
            + raw_packed_input_real_.capacity()
            + raw_packed_input_imag_.capacity()
            + raw_temporary_real_.capacity()
            + raw_temporary_imag_.capacity()
            + raw_output_real_.capacity()
            + raw_output_imag_.capacity()
            + raw_batch_left_.capacity()
            + raw_batch_right_.capacity()
            + raw_unique_temporary_real_.capacity()
            + raw_batch_temporary_real_.capacity()
            + raw_batch_temporary_imag_.capacity()
            + raw_right_first_product_real_.capacity()
            + raw_persistent_output_right_.capacity()
            + raw_output_fusion_temporary_real_.capacity()
            + raw_shared_right_input_real_.capacity()
            + raw_shared_right_output_real_.capacity()
            + raw_shared_right_deferred_output_real_.capacity()
            + raw_shared_right_tile_output_real_.capacity()
            + raw_shared_left_output_real_.capacity()
            + dense_factor_pack_arena_.capacity()
            + left_raw_factor_source_.build_scratch.capacity()
            + right_raw_factor_source_.build_scratch.capacity()
        ) * sizeof(double)
        + (
            raw_basis_offsets_.capacity()
            + raw_basis_shapes_.capacity()
            + dense_left_factor_pack_starts_.capacity()
            + dense_right_factor_pack_starts_.capacity()
            + active_bond_basis_offsets_.capacity()
            + active_bond_basis_shapes_.capacity()
            + active_bond_basis_quantum_numbers_.capacity()
        ) * sizeof(std::int64_t)
        + active_bond_basis_order_.capacity() * sizeof(std::size_t)
        + (
            grouped_output_transpose_left_.capacity()
            + grouped_output_transpose_right_.capacity()
            + grouped_output_rows_.capacity()
            + grouped_output_cols_.capacity()
            + grouped_output_inner_.capacity()
            + grouped_output_left_strides_.capacity()
            + grouped_output_right_strides_.capacity()
            + grouped_output_strides_.capacity()
            + grouped_output_group_sizes_.capacity()
        ) * sizeof(std::int32_t)
        + (
            grouped_output_alpha_.capacity()
            + grouped_output_beta_.capacity()
        ) * sizeof(double)
        + (
            grouped_output_left_.capacity()
            + grouped_output_right_.capacity()
            + grouped_output_values_.capacity()
        ) * sizeof(double*)
        + grouped_output_executed_.capacity() * sizeof(std::uint8_t)
        + grouped_output_executed_bindings_.capacity()
            * sizeof(std::uint32_t);
}
